TURATH_CHUNK(28,[{"num":5600,"demo":false,"sanad":"","matn":["عن عُقْبَةَ بن عَامِرٍ يَقُولُ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: لَا تُخِيفُوا أَنْفُسَكُمْ بَعْدَ أَمْنِهَا. قَالُوا: وَمَا ذَاكَ يَا رَسُولَ اللَّهِ؟ قَالَ: الدَّيْنُ."],"takhrij":"حسن: رواه أحمد (17320، 17407)، والطبراني في الكبير (17/328)، وأبو يعلى (1739)، والحاكم (2/26)، والبيهقي (5/355)، ويعقوب بن سفيان في المعرفة والتاريخ (2/509) كلهم من طرق عن بكر بن عمرو المعافري، عن شعيب بن زرعة المعافري أنه سمع عقبة بن عامر يقول فذكره.","grade":"حسن","chapter_ar":"باب التشديد في الدين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (17407, 17320), al-Tabarani in al-Kabir (17/328), Abu Yala (1739), and al-Hakim (2/26).","chapter_en":"The stern warning regarding debt","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":2,"content":{"translation":{"en":["Uqbah ibn Amir said: The Messenger of Allah ﷺ said: “Do not frighten yourselves after having been safe.” They said: “What is that, O Messenger of Allah ﷺ?” He said: “Debt.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (17407 ،17320)، والطبراني في الكبير (17/328)، وأبو يعلى (1739)، والحاكم (2/26)."},{"num":5601,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ، عَنْ أَبِي قَتَادَةَ: أَنَّهُ سَمِعَهُ يُحَدِّثُ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  أَنَّهُ قَامَ فِيهِمْ، فَذَكَرَ لَهُمْ: أَنَّ الْجِهَادَ فِي سَبِيلِ اللَّهِ وَالْإِيمَانَ بِاللهِ أَفْضَلُ الْأَعْمَالِ. فَقَامَ رَجُلٌ، فَقَالَ: يَا رَسُولَ اللَّهِ، أَرَأَيْتَ إِنْ قُتِلْتُ فِي سَبِيلِ اللَّهِ تُكَفَّرُ عَنِّي خَطَايَايَ؟ فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: نَعَمْ، إِنْ قُتِلْتَ فِي سَبِيلِ اللَّهِ وَأَنْتَ صَابِرٌ مُحْتَسِبٌ، مُقْبِلٌ غَيْرُ مُدْبِرٍ. ثُمَّ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: كَيْفَ قُلْتَ؟. قَالَ: أَرَأَيْتَ إِنْ قُتِلْتُ فِي سَبِيلِ اللَّهِ، أَتُكَفَّرُ عَنِّي خَطَايَايَ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: نَعَمْ، وَأَنْتَ صَابِرٌ مُحْتَسِبٌ، مُقْبِلٌ غَيْرُ مُدْبِرٍ، إِلَّا الدَّيْنَ، فَإِنَّ جِبْرِيلَ عَلَيْهِ السلام قَالَ لِي ذَلِكَ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1885) عن قتيبة بن سعيد، حدثنا ليث، عن سعيد بن أبي سعيد، عن عبد الله بن أبي قتادة فذكره.","grade":"صحيح","chapter_ar":"باب من قتل في سبيل الله كفرت خطاياه إلا الدَّين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1885).","chapter_en":"The one who is killed in the path of Allah has his sins expiated except debt","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":3,"content":{"translation":{"en":["Abdullah ibn Abi Qatadah narrated from Abu Qatadah that he heard him narrating from the Messenger of Allah ﷺ that he stood among them and mentioned to them: “Jihad in the path of Allah and faith in Allah are the best deeds.” A man stood and said: “O Messenger of Allah ﷺ, if I am killed in the path of Allah, will my sins be expiated for me?” The Messenger of Allah ﷺ said to him: “Yes, if you are killed in the path of Allah while being patient, seeking reward, advancing and not retreating.” Then the Messenger of Allah ﷺ said: “What did you say?” He said: “If I am killed in the path of Allah, will my sins be expiated for me?” The Messenger of Allah ﷺ said: “Yes, while you are patient, seeking reward, advancing and not retreating, except debt, for Jibril, peace be upon him, told me that.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1885)."},{"num":5602,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  يُغْفَرُ لِلشَّهِيدِ كُلُّ ذَنْبٍ إِلَّا الدَّيْنَ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1886) عن زكريا بن يحيى بن صالح المصري، حدثنا المفضل (يعنى ابن فضالة)، عن عياش (وهو ابن عباس القِتباني)، عن عبد الله بن يزيد أبى عبد الرحمن الحُبُلى، عن عبد الله بن عمرو فذكره.","grade":"صحيح","chapter_ar":"باب من قتل في سبيل الله كفرت خطاياه إلا الدَّين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1886). In another wording with him: “Being killed in the path of Allah expiates everything except debt.”","chapter_en":"The one who is killed in the path of Allah has his sins expiated except debt","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":3,"content":{"translation":{"en":["Abdullah ibn Amr narrated that the Messenger of Allah ﷺ said: “Every sin of the martyr is forgiven except debt.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[8101,13278],"tks":"صحيح: رواه مسلم (1886). وفي رواية عنده: (( القتل في سبيل الله يكفر كل شيء إلا الدين ))."},{"num":5603,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا أَنَّهُ أَخْبَرَهُ أَنَّ أَبَاهُ تُوُفِّيَ، وَتَرَكَ عَلَيْهِ ثَلاَثِينَ وَسْقًا لِرَجُلٍ مِنَ الْيَهُودِ، فَاسْتَنْظَرَهُ جَابِرٌ، فَأَبَى أَنْ يُنْظِرَهُ، فَكَلَّمَ جَابِرٌ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؛ لِيَشْفَعَ لَهُ إِلَيْهِ، فَجَاءَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَكَلَّمَ الْيَهُودِيَّ لِيَأْخُذَ ثَمَرَ نَخْلِهِ بِالَّذِي لَهُ، فَأَبَى، فَدَخَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ النَّخْلَ، فَمَشَى فِيهَا، ثُمَّ قَالَ لِجَابِرٍ: جُدَّ لَهُ، فَأَوْفِ لَهُ الَّذِي لَهُ. فَجَدَّهُ بَعْدَ مَا رَجَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَوْفَاهُ ثَلاَثِينَ وَسْقًا، وَفَضَلَتْ لَهُ سَبْعَةَ عَشَرَ وَسْقًا، فَجَاءَ جَابِرٌ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِيُخْبِرَهُ بِالَّذِي كَانَ، فَوَجَدَهُ يُصَلِّي الْعَصْرَ، فَلَمَّا انْصَرَفَ أَخْبَرَهُ بِالْفَضْلِ، فَقَالَ: أَخْبِرْ ذَلِكَ ابْنَ الْخَطَّابِ. فَذَهَبَ جَابِرٌ إِلَى عُمَرَ، فَأَخْبَرَهُ. فَقَالَ لَهُ عُمَرُ لَقَدْ عَلِمْتُ حِينَ مَشَى فِيهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَيُبَارَكَنَّ فِيهَا."],"takhrij":"صحيح: رواه البخاري في الاستقراض (2396) عن إبراهيم بن المنذر، حدثنا أنس، عن هشام، عن وهب بن كيسان، عن جابر بن عبد الله فذكره.","grade":"صحيح","chapter_ar":"باب قضاء الدين عن الميت","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2396).","chapter_en":"Paying the debt of the deceased","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":4,"content":{"translation":{"en":["Jabir narrated that his father died and left behind a debt of thirty wasqs owed to a Jewish man. Jabir asked him to grant time, but he refused. So Jabir spoke to the Messenger of Allah ﷺ to intercede for him. The Messenger of Allah ﷺ came and spoke to the Jew so that he would take the produce of his palm trees for what was owed to him, but he refused. Then the Messenger of Allah ﷺ entered the orchard and walked through it, then said to Jabir: “Harvest it and pay him what is owed to him.” So Jabir harvested it after the Messenger of Allah ﷺ returned, paid him the thirty wasqs, and seventeen wasqs remained extra. Jabir came to the Messenger of Allah ﷺ to tell him what had happened and found him praying Asr. When he finished, Jabir told him about the surplus, and he said: “Inform Ibn al-Khattab of that.” Jabir went to Umar and informed him, and Umar said to him: I knew when the Messenger of Allah ﷺ walked through it that blessing would be placed in it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (2396)."},{"num":5604,"demo":false,"sanad":"","matn":["عَنْ سَعْدِ بْنِ الأَطْوَلِ، أَنَّ أَخَاهُ، مَاتَ، وَتَرَكَ ثَلاَثَمِائَةِ دِرْهَمٍ، وَتَرَكَ عِيَالاً، فَأَرَدْتُ أَنْ أُنْفِقَهَا عَلَى عِيَالِهِ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ أَخَاكَ مُحْتَبَسٌ بِدَيْنِهِ، فَاقْضِ عَنْهُ. فَقَالَ: يَا رَسُولَ اللَّهِ، قَدْ أَدَّيْتُ عَنْهُ إِلاَّ دِينَارَيْنِ ادَّعَتْهُمَا امْرَأَةٌ، وَلَيْسَ لَهَا بَيِّنَةٌ. قَالَ: فَأَعْطِهَا فَإِنَّهَا مُحِقَّةٌ."],"takhrij":"حسن: رواه ابن ماجه (2433)، وأحمد (17227، 20076) كلاهما من حديث حماد بن سلمة، عن عبد الملك أبي جعفر، عن أبي نضرة، عن سعد بن الأطول فذكره.","grade":"حسن","chapter_ar":"باب قضاء الدين عن الميت","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2433) and Ahmad (20077, 20076, 17227).","chapter_en":"Paying the debt of the deceased","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":4,"content":{"translation":{"en":["Sad ibn al-Atwal said that his brother died and left three hundred dirhams and left dependents behind. I wanted to spend that money on his dependents. The Prophet ﷺ said: “Your brother is being held back by his debt, so pay it off for him.” He said: “O Messenger of Allah ﷺ, I have paid it except for two dinars that a woman claims, but she has no proof.” He said: “Give them to her, for she is truthful.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (2433)، وأحمد (20077 ،20076 ،17227)."},{"num":5605,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَوْ كَانَ عِنْدِي أُحد ذَهَبًا لأَحْبَبْتُ أَنْ لاَ يَأْتِيَ ثَلاَثٌ، وَعِنْدِي مِنْهُ دِينَارٌ –لَيْسَ شيء أُرْصِدُهُ فِي دَيْنٍ علي- أَجِدُ مَنْ يَقْبَلُهُ."],"takhrij":"متفق عليه: رواه البخاري في التمني (7228) عن إسحاق بن نصر، حدثنا عبدالرزاق، عن معمر، عن همام، سمع أبا هريرة عن النبي صلى الله عليه وسلم فذكره.","grade":"متفق عليه","chapter_ar":"باب الترغيب في قضاء الديون","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (7228) and Muslim (991).","chapter_en":"Encouragement to repay debts","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":5,"content":{"translation":{"en":["Abu Hurairah narrated from the Prophet ﷺ that he said: “If I had Uhud mountain in gold, I would not like three nights to pass while a single dinar remained with me — except something I set aside for a debt upon me — until I found someone to take it.”"]},"buhuth":{"en":["The phrase “I set aside” means: I reserve it."]}},"tuhfa":{},"full":1,"dr":1,"rep":[4025],"tks":"متفق عليه: رواه البخاري (7228)، ومسلم (991). وقوله: (( أرصده )) أي أعده."},{"num":5606,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ قَالَ: قَالَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا يَسُرُّنِي أَنَّ عِنْدِي مِثْلَ أحُد هَذَا ذَهَبًا تَمْضِي علي ثَالِثَةٌ، وَعِنْدِي مِنْهُ دِينَارٌ إِلاَّ شَيْئًا أُرْصِدُهُ لِدَيْنٍ إِلاَّ أَنْ أَقُولَ بِهِ فِي عِبَادِ اللَّهِ هَكَذَا وَهَكَذَا وَهَكَذَا عَنْ يَمِينِهِ، وَعَنْ شِمَالِهِ، وَمِنْ خَلْفِهِ."],"takhrij":"متفق عليه: رواه البخاري في الرقاق (6444)، ومسلم في الزكاة (992) كلاهما من حديث الأعمش، عن زيد بن وهب، عن أبي ذر في حديث طويل.","grade":"متفق عليه","chapter_ar":"باب الترغيب في قضاء الديون","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6444) and Muslim (992).","chapter_en":"Encouragement to repay debts","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":5,"content":{"translation":{"en":["Abu Dharr said: The Messenger of Allah ﷺ said: “It would not please me to have the like of this mountain of Uhud in gold and for three nights to pass while I still had a dinar of it, except something I reserve for a debt, unless I were to distribute it among the servants of Allah like this, and this, and this,” to his right, to his left, and behind him."]}},"tuhfa":{},"full":1,"rep":[4026],"tks":"متفق عليه: رواه البخاري (6444)، ومسلم (992)."},{"num":5607,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ أَخَذَ أَمْوَالَ النَّاسِ يُرِيدُ أَدَاءَهَا أَدَّى اللَّهُ عَنْهُ، وَمَنْ أَخَذَ يُرِيدُ إِتْلاَفَهَا أَتْلَفَهُ اللَّهُ."],"takhrij":"صحيح: رواه البخاري في الاستقراض (2387) عن عبد العزيز بن عبد الله الأويسي، حدثنا سليمان بن بلال، عن ثور بن يزيد، عن أبي الغيث، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب من استدان دينا وهو ينوي قضاءه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2387).","chapter_en":"The one who borrows while intending repayment","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":6,"content":{"translation":{"en":["Abu Hurairah narrated from the Prophet ﷺ that he said: “Whoever takes people’s wealth intending to repay it, Allah will repay it on his behalf; and whoever takes it intending to destroy it, Allah will destroy him.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (2387)."},{"num":5608,"demo":false,"sanad":"","matn":["عن مَيْمُونَةَ زوج النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اسْتَدَانَتْ، فَقِيلَ لَهَا: يَا أُمَّ الْمُؤْمِنِينَ، تَسْتَدِينِينَ وَلَيْسَ عِنْدَكِ وَفَاءٌ. قَالَتْ: إِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ أَخَذَ دَيْنًا وَهُوَ يُرِيدُ أَنْ يُؤَدِّيَهُ أَعَانَهُ اللَّهُ عَزَّ وَجَلَّ."],"takhrij":"حسن: رواه النسائي (4687) عن محمد بن المثنى قال: حدثنا وهب ابن جرير قال: حدثنا أبي، عن الأعمش، عن حصين بن عبد الرحمن، عن عبيد الله بن عتبة أن ميمونة استدانت فذكره.","grade":"حسن","chapter_ar":"باب من استدان دينا وهو ينوي قضاءه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasai (4686, 4687), Ibn Majah (2408), Abd ibn Humayd (1549), and Ibn Hibban (5041).","chapter_en":"The one who borrows while intending repayment","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":6,"content":{"translation":{"en":["Maymunah, the wife of the Prophet ﷺ, once borrowed money. It was said to her: “O Mother of the Believers, you borrow while you do not have means to repay?” She said: I heard the Messenger of Allah ﷺ say: “Whoever takes a debt while intending to repay it, Allah the Mighty and Majestic will help him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (4686 ،4687)، وابن ماجه (2408)، وعبد بن حميد (1549)، وابن حبان (5041)."},{"num":5609,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ جَعْفَرٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ اللَّهَ مَعَ الدَّائِنِ حَتَّى يَقْضِيَ دَيْنَهُ مَا لَمْ يَكُنْ فِيمَا يَكْرَهُ اللَّهُ."],"takhrij":"حسن: رواه ابن ماجه (2409)، والدارمي (2637)، والحاكم (2205)، والبيهقي (10960) كلهم من طريق محمد بن إسماعيل بن أبي فديك، حدثنا سعيد بن سفيان مولى الأسلميين، عن جعفر بن محمد، عن أبيه، عن عبد الله بن جعفر فذكره.","grade":"حسن","chapter_ar":"باب من استدان دينا وهو ينوي قضاءه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2409), al-Darimi (2637), al-Hakim (2/23), and al-Bayhaqi (5/355).","chapter_en":"The one who borrows while intending repayment","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":6,"content":{"translation":{"en":["Abdullah ibn Jafar said: The Messenger of Allah ﷺ said: “Allah is with the debtor until he pays his debt, so long as it was not incurred in something Allah dislikes.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (2409)، والدارمي (2637)، والحاكم (2205)، والبيهقي (10960)."},{"num":5610,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَجُلاً، أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَتَقَاضَاهُ بَعِيرًا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَعْطُوهُ. فَقَالُوا: مَا نَجِدُ إِلاَّ سِنًّا أَفْضَلَ مِنْ سِنِّهِ. فَقَالَ الرَّجُلُ: أَوْفَيْتَنِي أَوْفَاكَ اللَّهُ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَعْطُوهُ؛ فَإِنَّ مِنْ خِيَارِ النَّاسِ أَحْسَنَهُمْ قَضَاءً."],"takhrij":"متفق عليه: رواه البخاري في الاستقراض (2392)، ومسلم في المساقاة (1601: 122) من طريق سفيان، حدثني سلمة بن كهيل، عن أبي سلمة، عن أبي هريرة فذكره. واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب ما جاء في حسن القضاء بالزيادة وغيرها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2392) and Muslim (1601:122). The wording is al-Bukhari’s.","chapter_en":"What has been reported regarding excellence in repayment through giving extra and similar manners","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":7,"content":{"translation":{"en":["Abu Hurairah narrated that a man came to the Prophet ﷺ demanding a camel that he was owed. The Messenger of Allah ﷺ said: “Give it to him.” They said: “We only find one better in age than his.” The man said: “You have fulfilled my due — may Allah fulfill yours.” The Messenger of Allah ﷺ said: “Give it to him, for the best of people are those best in repayment.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (2392)، ومسلم (1601: 122). واللفظ للبخاري."},{"num":5611,"demo":false,"sanad":"","matn":["عَنْ أَبِى هُرَيْرَةَ قَالَ: كَانَ لِرَجُلٍ عَلَى رَسُولِ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  حَقٌّ، فَأَغْلَظَ لَهُ، فَهَمَّ بِهِ أَصْحَابُ النَّبِىِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، فَقَالَ النَّبِىُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : إِنَّ لِصَاحِبِ الحق مَقَالاً، اشْتَرُوا لَهُ سِنًّا فَأَعْطُوهُ إِيَّاهُ. فَقَالُوا: إِنَّا لاَ نَجِدُ إِلاَّ سِنًّا هُوَ خَيْرٌ مِنْ سِنِّهِ. قَالَ: فَاشْتَرُوهُ فَأَعْطُوهُ إِيَّاهُ فَإِنَّ مِنْ خَيْرِكُمْ - أَوْ خَيْرَكُمْ - أَحْسَنُكُمْ قَضَاءً."],"takhrij":"متفق عليه: رواه البخاري في الوكالة (2306)، ومسلم في المساقاة (1601: 120) كلاهما من طريق شعبة، عن سلمة بن كهيل، عن أبي سلمة بن عبد الرحمن، عن أبي هريرة قال: فذكره.واللفظ لمسلم. وعند البخاري في أوله: دعوه، فإن لصاحب الحق مقالا...","grade":"متفق عليه","chapter_ar":"باب ما جاء في حسن القضاء بالزيادة وغيرها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2306) and Muslim (1601:120). The wording is Muslim’s.","chapter_en":"What has been reported regarding excellence in repayment through giving extra and similar manners","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":7,"content":{"translation":{"en":["Abu Hurairah said: A man had a claim against the Messenger of Allah ﷺ, and he spoke harshly to him. The companions of the Prophet ﷺ intended to deal with him, but the Prophet ﷺ said: “The one who has a right may speak. Buy for him a camel of the proper age and give it to him.” They said: “We only find one better than his.” He said: “Then buy it and give it to him, for among the best of you — or the best of you — are those best in repayment.”"]},"buhuth":{"ar":["وعند البخاري في أوله:  دعوه؛ فإن لصاحب الحق مقالًا … ."],"en":["In al-Bukhari the beginning reads: “Leave him, for the one who has a right may speak.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (2306)، ومسلم (1601: 120). واللفظ لمسلم."},{"num":5612,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلٌ يَتَقَاضَاهُ، قَدِ اسْتَسْلَفَ مِنْهُ شَطْرَ وَسْقٍ، فَأَعْطَاهُ وَسْقًا، فَقَالَ: نِصْفُ وَسْقٍ لَكَ، وَنِصْفُ وَسْقٍ لَكَ مِنْ عِنْدِي، ثُمَّ جَاءَ صَاحِبُ الْوَسْقِ يَتَقَاضَاهُ، فَأَعْطَاهُ وَسْقَيْنِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: وَسْقٌ لَكَ، وَوَسْقٌ مِنْ عِنْدِي."],"takhrij":"حسن: رواه البزار –كشف الأستار (1306) عن محمد بن أبي غالب، ثنا أبو صالح الفراء، ثنا عبد الله بن المبارك، عن حمزة الزيات، عن حبيب بن أبي ثابت، عن أبي صالح، عن أبي هريرة، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في حسن القضاء بالزيادة وغيرها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzār in Kashf al-Astār (1306).","chapter_en":"What has been reported regarding excellence in repayment through giving extra and similar manners","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":7,"content":{"translation":{"en":["Abū Hurayrah reported: A man came to the Prophet ﷺ seeking repayment of half a wasq that the Prophet ﷺ had borrowed from him. He gave him a full wasq and said: “Half a wasq is what is due to you, and the other half wasq is a gift from me.” Then another man to whom a full wasq was owed came seeking repayment. The Prophet ﷺ gave him two wasqs and said: “One wasq is what is due to you, and one wasq is from me.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار في كشف الأستار (1306)."},{"num":5613,"demo":false,"sanad":"","matn":["عَنْ أَبِي رَافِعٍ، مَوْلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: اسْتَسْلَفَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَكْرًا فَجَاءَتْهُ إِبِلٌ مِنَ الصَّدَقَةِ. قَالَ أَبُو رَافِعٍ: فَأَمَرَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ أَقْضِيَ الرَّجُلَ بَكْرَهُ، فَقُلْتُ: لَمْ أَجِدْ فِي الإِبِلِ إِلاَّ جَمَلاً خِيَارًا رَبَاعِيًا. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَعْطِهِ إِيَّاهُ؛ فَإِنَّ خِيَارَ النَّاسِ أَحْسَنُهُمْ قَضَاءً."],"takhrij":"صحيح: رواه مالك في البيوع (89) عن زيد بن أسلم، عن عطاء بن يسار، عن أبي رافع مولى رسول الله صلى الله عليه وسلم أنه قال فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في حسن القضاء بالزيادة وغيرها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (89) and Muslim (1600:118).","chapter_en":"What has been reported regarding excellence in repayment through giving extra and similar manners","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":7,"content":{"translation":{"en":["Abu Rafi, the freed slave of the Messenger of Allah ﷺ, said: The Messenger of Allah ﷺ borrowed a young camel. Then camels from charity arrived. Abu Rafi said: The Messenger of Allah ﷺ ordered me to repay the man his camel. I said: “I found among the camels only an excellent mature camel.” The Messenger of Allah ﷺ said: “Give it to him, for the best of people are those best in repayment.”"]},"buhuth":{"en":["Malik said: There is no harm in a person receiving, from one to whom he loaned gold, silver, food, or animals, something better than what he loaned, so long as it was not stipulated between them and was not a customary expectation. If it was a condition, a promise, or an established habit, then it is disliked and not good.","The word “or a promise” means: a prior promise."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مالك (89)، ومسلم (118 :1600)."},{"num":5614,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ قَالَ:  كَانَ لِي عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَيْنٌ، فَقَضَانِي، وَزَادَنِي، وَدَخَلْتُ عَلَيْهِ الْمَسْجِدَ، فَقَالَ لِي: صَلِّ رَكْعَتَيْنِ."],"takhrij":"متفق عليه: رواه البخاري في الاستقراض (2394)، ومسلم في صلاة المسافرين (715: 71) كلاهما من طريق محارب بن دثار، عن جابر فذكره. واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب ما جاء في حسن القضاء بالزيادة وغيرها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2394) and Muslim (715:71). The wording is Muslim’s.","chapter_en":"What has been reported regarding excellence in repayment through giving extra and similar manners","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":7,"content":{"translation":{"en":["Jabir ibn Abdullah said: The Prophet ﷺ owed me a debt, and he repaid me and gave me extra. Then I entered upon him in the mosque and he said to me: “Pray two units of prayer.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (2394)، ومسلم (715: 71) واللفظ لمسلم."},{"num":5615,"demo":false,"sanad":"","matn":["عن إِسْمَاعِيلَ بن إِبْرَاهِيمَ بن عَبْدِ اللَّهِ بن أَبِي رَبِيعَةَ المخزومي، عَنْ أَبِيهِ، عَنْ جَدِّهِ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اسْتَسْلَفَ مِنْهُ حِينَ غَزَا حُنَيْنًا ثَلاَثِينَ أَوْ أَرْبَعِينَ أَلْفًا، فَلَمَّا قَدِمَ قَضَاهَا إِيَّاهُ. ثُمَّ قَالَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: بَارَكَ اللَّهُ لَكَ فِي أَهْلِكَ وَمَالِكَ. إِنَّمَا جَزَاءُ السَّلَفِ الْوَفَاءُ وَالْحَمْدُ."],"takhrij":"حسن: رواه النسائي (4683)، وابن ماجه (2424)، وأحمد (16410)، والبيهقي (5/355) كلهم من حديث إسماعيل بن إبراهيم بن عبد الله بن أبي ربيعة المخزومي بإسناده مثله. ولكن انقلب في مسند أحمد إلى إبراهيم بن إسماعيل، والصواب ما ذكرناه.","grade":"حسن","chapter_ar":"باب ما جاء في حسن القضاء بالزيادة وغيرها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasai (4683), Ibn Majah (2424), Ahmad (16410), and al-Bayhaqi (5/355).","chapter_en":"What has been reported regarding excellence in repayment through giving extra and similar manners","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":7,"content":{"translation":{"en":["Ismail ibn Ibrahim ibn Abdullah ibn Abi Rabiah al-Makhzumi narrated from his father, from his grandfather, that the Prophet ﷺ borrowed from him thirty or forty thousand during the campaign of Hunayn. When he returned, he repaid him. Then the Prophet ﷺ said to him: “May Allah bless your family and your wealth. The reward for a loan is repayment and gratitude.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (4683)، وابن ماجه (2424)، وأحمد (16410)، والبيهقي (5/355)."},{"num":5616,"demo":false,"sanad":"","matn":["عن الْعِرْبَاضِ بن سَارِيَةَ يَقُولُ: كُنْتُ عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ أَعْرَابِيٌّ: اقْضِنِي بَكْرِي. فَأَعْطَاهُ بَعِيرًا مُسِنًّا، فَقَالَ الأَعْرَابِيُّ: يَا رَسُولَ اللَّهِ، هَذَا أَسَنُّ مِنْ بَعِيرِي. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: خَيْرُ النَّاسِ خَيْرُهُمْ قَضَاءً."],"takhrij":"حسن: رواه النسائي (4619)، وابن مـاجه (2286)، وأحمد (17149)، والحاكم (2/30)، والبيهقي (5/351) كلهم من طريق معاوية بن صالح قال: حدثني سعيد بن هانئ قال: سمعت العرباض بن سارية فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في حسن القضاء بالزيادة وغيرها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasai (4619), Ibn Majah (2286), Ahmad (17149), al-Hakim (2/30), and al-Bayhaqi (5/351).","chapter_en":"What has been reported regarding excellence in repayment through giving extra and similar manners","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":7,"content":{"translation":{"en":["Al-Irbad ibn Sariyah said: I was with the Prophet ﷺ when a Bedouin said: “Repay me my young camel.” So he gave him an older camel. The Bedouin said: “O Messenger of Allah ﷺ, this is older than my camel.” The Messenger of Allah ﷺ said: “The best of people are those best in repayment.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (4619)، وابن ماجه (2286)، وأحمد (17149)، والحاكم (2/30)، والبيهقي (5/351)."},{"num":5617,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ: ابْتَاعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ رَجُلٍ مِنَ الْأَعْرَابِ جَزُورًا - أَوْ جَزَائِرَ - بِوَسْقٍ مِنْ تَمْرِ الذَّخِرَةِ، وَتَمْرُ الذَّخِرَةِ: الْعَجْوَةُ، فَرَجَعَ بِهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى بَيْتِهِ، فَالْتَمَسَ لَهُ التَّمْرَ، فَلَمْ يَجِدْهُ، فَخَرَجَ إِلَيْهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ لَهُ: يَا عَبْدَ اللَّهِ، إِنَّا قَدْ ابْتَعْنَا مِنْكَ جَزُورًا - أَوْ جَزَائِرَ - بِوَسْقٍ مِنْ تَمْرِ الذَّخْرَةِ، فَالْتَمَسْنَاهُ، فَلَمْ نَجِدْهُ. قَالَ: فَقَالَ الْأَعْرَابِيُّ: وَا غَدْرَاهُ. قَالَتْ: فَنَهَمَهُ النَّاسُ، وَقَالُوا: قَاتَلَكَ اللهُ، أَيَغْدِرُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَتْ: فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: دَعُوهُ، فَإِنَّ لِصَاحِبِ الْحَقِّ مَقَالًا. ثُمَّ عَادَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: يَا عَبْدَ اللَّهِ، إِنَّا ابْتَعْنَا مِنْكَ جَزَائِرَكَ، وَنَحْنُ نَظُنُّ أَنَّ عِنْدَنَا مَا سَمَّيْنَا لَكَ، فَالْتَمَسْنَاهُ، فَلَمْ نَجِدْهُ. فَقَالَ الْأَعْرَابِيُّ: وَاغَدْرَاهُ، فَنَهَمَهُ النَّاسُ، وَقَالُوا: قَاتَلَكَ اللهُ، أَيَغْدِرُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: دَعُوهُ، فَإِنَّ لِصَاحِبِ الْحَقِّ مَقَالًا فَرَدَّدَ ذَلِكَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَرَّتَيْنِ، أَوْ ثَلَاثًا، فَلَمَّا رَآهُ لَا يَفْقَهُ عَنْهُ، قَالَ لِرَجُلٍ مِنْ أَصْحَابِهِ: اذْهَبْ إِلَى خُوَيْلَةَ بِنْتِ حَكِيمِ بْنِ أُمَيَّةَ، فَقُلْ لَهَا: رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ لَكِ: إِنْ كَانَ عِنْدَكِ وَسْقٌ مِنْ تَمْرِ الذَّخِرَةِ، فَأَسْلِفِينَاهُ حَتَّى نُؤَدِّيَهُ إِلَيْكِ إِنْ شَاءَ اللَّهُ، . فَذَهَبَ إِلَيْهَا الرَّجُلُ، ثُمَّ رَجَعَ الرَّجُلُ، فَقَالَ: قَالَتْ: نَعَمْ، هُوَ عِنْدِي يَا رَسُولَ اللَّهِ، فَابْعَثْ مَنْ يَقْبِضُهُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِلرَّجُلِ: اذْهَبْ بِهِ، فَأَوْفِهِ الَّذِي لَهُ. قَالَ: فَذَهَبَ بِهِ، فَأَوْفَاهُ الَّذِي لَهُ. قَالَتْ: فَمَرَّ الْأَعْرَابِيُّ بِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ جَالِسٌ فِي أَصْحَابِهِ، فَقَالَ: جَزَاكَ اللهُ خَيْرًا، فَقَدْ أَوْفَيْتَ وَأَطْيَبْتَ. قَالَتْ: فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أُولَئِكَ خِيَارُ عِبَادِ اللَّهِ عِنْدَ اللَّهِ يَوْمَ الْقِيَامَةِ الْمُوفُونَ الْمُطِيبُونَ."],"takhrij":"حسن: رواه أحمد (26312) عن يعقوب قال: حدثنا أبي، عن ابن إسحاق قال: حدثني هشام بن عروة، عن أبيه، عن عائشة فذكرته.","grade":"حسن","chapter_ar":"باب ما جاء في حسن القضاء بالزيادة وغيرها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (26312) and al-Bazzār in Kashf al-Astār (1309).","chapter_en":"What has been reported regarding excellence in repayment through giving extra and similar manners","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":7,"content":{"translation":{"en":["ʿĀʾishah reported: The Messenger of Allah ﷺ purchased from a Bedouin a camel—or several camels—for one wasq of al-dhakhīrah dates, and al-dhakhīrah dates were ʿajwah dates. The Messenger of Allah ﷺ returned home with the animal and searched for the dates to pay the man, but he could not find them. He went out to the Bedouin and said: “O servant of Allah, we purchased from you a camel—or camels—for one wasq of al-dhakhīrah dates, but we looked for them and could not find them.” The Bedouin exclaimed: “What treachery!” The people rebuked him and said: “May Allah deal with you! Would the Messenger of Allah ﷺ betray anyone?” The Messenger of Allah ﷺ said: “Leave him, for the person who possesses a right is entitled to speak.” Then the Messenger of Allah ﷺ repeated to him: “O servant of Allah, we purchased your camels while thinking that we possessed what we had specified for you. We searched for it, but we could not find it.” The Bedouin again exclaimed: “What treachery!” The people rebuked him and said: “May Allah deal with you! Would the Messenger of Allah ﷺ betray anyone?” The Messenger of Allah ﷺ said: “Leave him, for the person who possesses a right is entitled to speak.” The Messenger of Allah ﷺ repeated this two or three times. When he saw that the man did not understand, he said to one of his Companions: “Go to Khuwaylah bint Ḥakīm ibn Umayyah and say to her: ‘The Messenger of Allah ﷺ says to you: If you have one wasq of al-dhakhīrah dates, lend it to us until we repay you, if Allah wills.’” The man went to her and then returned, saying: “She says: Yes, I have it, O Messenger of Allah ﷺ. Send someone to collect it.” The Messenger of Allah ﷺ said to the man: “Take it to him and give him in full what is owed to him.” So he took it and paid the Bedouin his full due. ʿĀʾishah said: The Bedouin later passed by the Messenger of Allah ﷺ while he was sitting among his Companions and said: “May Allah reward you with good. You have paid in full and dealt generously.” The Messenger of Allah ﷺ said: “Those are the best servants of Allah in the sight of Allah on the Day of Resurrection: those who fulfill what they owe and do so graciously.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (26312)، والبزار في كشف الأستار (1309)."},{"num":5618,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، وَعَائِشَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ طَلَبَ حَقًّا فَلْيَطْلُبْهُ فِي عَفَافٍ وَافٍ، أَوْ غَيْرِ وَافٍ."],"takhrij":"حسن: رواه ابن ماجه (2421)، وصحّحه ابن حبان (5080)، والحاكم (2238)، والبيهقي (10980) كلهم من طرق عن ابن أبي مريم قال: حدثنا يحيى بن أيوب، عن عبيدالله بن أبي جعفر، عن نافع، عن ابن عمر، وعائشة فذكراه.","grade":"حسن","chapter_ar":"باب حسن المطالبة، وأخذ الحق في عفاف","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2421), authenticated by Ibn Hibban (5080), al-Hakim (2/32), and al-Bayhaqi (5/358).","chapter_en":"Properly seeking repayment and taking one’s right with dignity","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":8,"content":{"translation":{"en":["Ibn Umar and Aishah narrated that the Messenger of Allah ﷺ said: “Whoever seeks his right should seek it with dignity, whether it is fully paid or not fully paid.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (2421)، وصححه ابن حبان (5080)، والحاكم (2238)، والبيهقي (10980)."},{"num":5619,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لِصَاحِبِ الْحَقِّ: خُذْ حَقَّكَ فِي عَفَافٍ وَافٍ، أَوْ غَيْرِ وَافٍ."],"takhrij":"حسن: رواه ابن ماجه (2422) عن محمد بن المؤمل بن الصباح القيسي قال: حدثنا محمد بن محبَّب القرشي قال: حدثنا سعيد بن السائب الطائفي، عن عبدالله بن يامين، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب حسن المطالبة، وأخذ الحق في عفاف","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2422).","chapter_en":"Properly seeking repayment and taking one’s right with dignity","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":8,"content":{"translation":{"en":["Abu Hurairah narrated that the Messenger of Allah ﷺ said to the one who had a claim: “Take your right with dignity, whether fully or not fully.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (2422)."},{"num":5620,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَطْلُ الْغَنِيِّ ظُلْمٌ، فَإِذَا أُتْبِعَ أَحَدُكُمْ عَلَى مَلِيٍّ فَلْيَتْبَعْ."],"takhrij":"متفق عليه: رواه مالك في البيوع (84) عن أبي الزناد، عن الأعرج، عن أبي هريرة فذكره. ورواه البخاري في الحوالة (2287)، ومسلم في المساقاة (1564) كلاهما من طريق مالك به.","grade":"متفق عليه","chapter_ar":"باب عدم جواز تأخير الوفاء بالدين لمن قدر عليه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik (84), al-Bukhārī (2287), and Muslim (1564).","chapter_en":"The impermissibility of delaying repayment of debt for one who is able","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":9,"content":{"translation":{"en":["Abū Hurayrah reported that the Messenger of Allah ﷺ said: “Delay in payment by one who is able to pay is injustice. If one of you is referred for payment to a solvent person, then let him accept the transfer.”"]}},"tuhfa":{},"full":1,"rep":[5529],"tks":"متفق عليه: رواه مالك (84)، والبخاري (2287)، ومسلم (1564)."},{"num":5621,"demo":false,"sanad":"","matn":["عن جابر بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا أَخْبَرَهُ أَنَّ أَبَاهُ قُتِلَ يَوْمَ أُحُدٍ شَهِيدًا، وَعَلَيْهِ دَيْنٌ، فَاشْتَدَّ الْغُرَمَاءُ فِي حُقُوقِهِمْ، فَأَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَسَأَلَهُمْ أَنْ يَقْبَلُوا تَمْرَ حَائِطِي، وَيُحَلِّلُوا أَبِي فَأَبَوْا، فَلَمْ يُعْطِهِمِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَائِطِي، وَقَالَ: سَنَغْدُو عَلَيْكَ. فَغَدَا عَلَيْنَا حِينَ أَصْبَحَ، فَطَافَ فِي النَّخْلِ، وَدَعَا فِي ثَمَرِهَا بِالْبَرَكَةِ، فَجَدَدْتُهَا، فَقَضَيْتُهُمْ، وَبَقِيَ لَنَا مِنْ تَمْرِهَا."],"takhrij":"صحيح: رواه البخاري في الاستقراض (2395) عن عبدان، أخبرنا عبد الله ، أخبرنا يونس، عن الزهري، حدثني ابن كعب بن مالك أن جابر بن عبد الله أخبره أن أباه فذكره.","grade":"صحيح","chapter_ar":"باب تأخير يوم أو نحوه لا يعد مطلًا","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2395).","chapter_en":"Delaying for a day or the like is not considered procrastination","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":10,"content":{"translation":{"en":["Jabir ibn Abdullah said: My father was killed as a martyr on the Day of Uhud and he had debts. The creditors pressed strongly for their rights, so I came to the Prophet ﷺ and asked him to request that they accept the dates of my orchard and release my father, but they refused. The Prophet ﷺ did not hand over my orchard to them and said: “We will come to you in the morning.” So he came to us in the morning, walked through the palm trees, and supplicated for blessing in their fruit. Then I harvested the dates, repaid the creditors, and some of the dates remained for us."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (2395)."},{"num":5622,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: غَزَوْتُ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ كَيْفَ تَرَى بَعِيرَكَ؟ أَتَبِيعُنِيهِ. قُلْتُ: نَعَمْ. فَبِعْتُهُ إِيَّاهُ، فَلَمَّا قَدِمَ الْمَدِينَةَ غَدَوْتُ إِلَيْهِ بِالْبَعِيرِ، فَأَعْطَانِي ثَمَنَهُ."],"takhrij":"متفق عليه: رواه البخاري في الاستقراض (2385)، ومسلم في صلاة المسافرين (715: 11) كلاهما من طريق جرير، عن المغيرة، عن الشعبي، عن جابر فذكره.","grade":"متفق عليه","chapter_ar":"باب جواز الشراء بالدَّين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2385) and Muslim (715:11). The wording is al-Bukhari’s.","chapter_en":"The permissibility of purchasing on credit","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":11,"content":{"translation":{"en":["Jabir ibn Abdullah said: I went on a campaign with the Prophet ﷺ, and he said: “How do you find your camel? Will you sell it?” I said: Yes. So I sold it to him. When we arrived in Madinah, I brought the camel to him in the morning, and he gave me its price."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2385)، ومسلم (715: 11) واللفظ للبخاري."},{"num":5623,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَنَّهُ ذَكَرَ: أَنَّ رَجُلًا مِنْ بَنِي إِسْرَائِيلَ سَأَلَ بَعْضَ بَنِي إِسْرَائِيلَ أَنْ يُسَلِّفَهُ أَلْفَ دِينَارٍ، قَالَ: ائْتِنِي بِشُهَدَاءَ أُشْهِدُهُمْ، قَالَ: كَفَى بِاللهِ شَهِيدًا، قَالَ: ائْتِنِي بِكَفِيلٍ، قَالَ: كَفَى بِاللهِ كَفِيلًا، قَالَ: صَدَقْتَ، فَدَفَعَهَا إِلَيْهِ إِلَى أَجَلٍ مُسَمًّى، فَخَرَجَ."],"takhrij":"صحيح: رواه أحمد (8587) عن يونس بن محمد، حدثنا ليث بن سعد، عن جعفر بن ربيعة، عن عبد الرحمن بن هرمز، عن أبي هريرة. فذكره بطوله.","grade":"صحيح","chapter_ar":"باب الدَّين إلى أجل مسمى","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (8587), and al-Bukhari (2404) in suspended form.","chapter_en":"Debt to a specified term","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":12,"content":{"translation":{"en":["Abu Hurairah narrated that the Messenger of Allah ﷺ mentioned: “A man from the Children of Israel asked another man from the Children of Israel to lend him one thousand dinars. He said: ‘Bring me witnesses so I may have them witness it.’ He said: ‘Allah is sufficient as a witness.’ He said: ‘Bring me a guarantor.’ He said: ‘Allah is sufficient as a guarantor.’ He said: ‘You have spoken truthfully.’ So he gave it to him until a specified term.” The rest of the hadith follows."]},"intro":{"ar":["قال اللّٰه تعالى: ( يَاأَيُّهَا الَّذِينَ آمَنُوا إِذَا تَدَايَنْتُم بِدَيْنٍ إِلَى أَجَلٍ مُسَمًّى فَاكْتُبُوهُ ) [البقرة: ٢٨٢]."],"en":["Allah the Exalted said: “O you who believe, when you contract a debt for a specified term, write it down.” [al-Baqarah: 282]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (8587) والبخاري (2404) تعليقا."},{"num":5624,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: كَانَ تَاجِرٌ يُدَايِنُ النَّاسَ، فَإِذَا رَأَى مُعْسِرًا قَالَ لِفِتْيَانِهِ: تَجَاوَزُوا عَنْهُ، لَعَلَّ اللَّهَ أَنْ يَتَجَاوَزَ عَنَّا، فَتَجَاوَزَ اللَّهُ عَنْهُ."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2078)، ومسلم في المساقاة (1562) كلاهما من حديث ابن شهاب الزهري، عن عبيدالله بن عبد الله بن عتبة، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب فضل إنظار المعسر","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2078) and Muslim (1562).","chapter_en":"The virtue of giving respite to one in hardship","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":13,"content":{"translation":{"en":["Abu Hurairah narrated from the Prophet ﷺ that he said: “There was a merchant who used to lend people money. Whenever he saw someone in hardship, he would say to his servants: ‘Overlook him, perhaps Allah will overlook us.’ So Allah overlooked him.”"]},"intro":{"ar":["قال اللّٰه تعالى: ( فَنَظِرَةٌ إِلَى مَيْسَرَةٍ ) [سورة البقرة: ٢٨٠] أي يسار."],"en":["Allah the Exalted said: “Then let there be postponement until ease.” [al-Baqarah: 280] Meaning: until the debtor has means."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (2078)، ومسلم (1562)."},{"num":5625,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  مَنْ نَفَّسَ عَنْ مُؤْمِنٍ كُرْبَةً مِنْ كُرَبِ الدُّنْيَا نَفَّسَ اللهُ عَنْهُ كُرْبَةً مِنْ كُرَبِ يَوْمِ الْقِيَامَةِ، وَمَنْ يَسَّرَ عَلَى مُعْسِرٍ يَسَّرَ اللهُ عَلَيْهِ فِي الدُّنْيَا وَالْآخِرَةِ."],"takhrij":"صحيح: رواه مسلم في العلم (2699) من طرق عن أبي معاوية، عن الأعمش، عن أبي صالح، عن أبي هريرة في حديث طويل ذكر في موضعه.","grade":"صحيح","chapter_ar":"باب فضل إنظار المعسر","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2699).","chapter_en":"The virtue of giving respite to one in hardship","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":13,"content":{"translation":{"en":["Abu Hurairah said: The Messenger of Allah ﷺ said: “Whoever relieves a believer of a hardship from the hardships of this world, Allah will relieve him of a hardship from the hardships of the Day of Resurrection. And whoever makes matters easy for one in hardship, Allah will make matters easy for him in this world and the Hereafter.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2699)."},{"num":5626,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ أَنْظَرَ مُعْسِرًا أَوْ وَضَعَ لَهُ أَظَلَّهُ اللَّهُ فِي ظِلِّ عَرْشِهِ يَوْمَ الْقِيَامَةِ."],"takhrij":"صحيح: رواه الترمذي (1306)، وأحمد (8711) كلاهما من حديث إسحاق بن سليمان الرازي، حدثنا داود بن قيس، عن زيد بن أسلم، عن أبي صالح، عن أبي هريرة فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب فضل إنظار المعسر","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (1306) and Ahmad (8711). Al-Tirmidhi said: “Hasan Sahih.”","chapter_en":"The virtue of giving respite to one in hardship","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":13,"content":{"translation":{"en":["Abu Hurairah narrated that the Messenger of Allah ﷺ said: “Whoever grants respite to one in hardship, or reduces what he owes, Allah will shade him under the shade of His Throne on the Day of Resurrection.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (1306)، وأحمد (8711). وقال الترمذي: “حديث حسن صحيح”."},{"num":5627,"demo":false,"sanad":"","matn":["عَنْ حُذَيْفَةَ بن الْيَمَانِ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: تَلَقَّتِ الْمَلَائِكَةُ رُوحَ رَجُلٍ مِمَّنْ كَانَ قَبْلَكُمْ، فَقَالُوا: أَعَمِلْتَ مِنَ الْخَيْرِ شَيْئًا؟ قَالَ: لَا. قَالُوا: تَذَكَّرْ. قَالَ: كُنْتُ أُدَايِنُ النَّاسَ، فَآمُرُ فِتْيَانِي أَنْ يُنْظِرُوا الْمُعْسِرَ، وَيَتَجَوَّزُوا عَنِ الْمُوسِرِ، قَالَ: قَالَ اللَّهُ عَزَّ وَجَلَّ: تَجَوَّزُوا عَنْهُ."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2077)، ومسلم في المساقاة (1560) كلاهما من حديث زهير، حدثنا منصور، عن ربعي بن حراش أن حذيفة حدثهم فذكره،","grade":"متفق عليه","chapter_ar":"باب فضل إنظار المعسر","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2077) and Muslim (1560). The wording is Muslim’s.","chapter_en":"The virtue of giving respite to one in hardship","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":13,"content":{"translation":{"en":["Hudhayfah ibn al-Yaman said: The Messenger of Allah ﷺ said: “The angels received the soul of a man from those before you and said: ‘Did you do any good?’ He said: ‘No.’ They said: ‘Remember.’ He said: ‘I used to deal with people in debt, and I would order my young servants to give respite to the one in hardship and to be lenient with the one who had means.’ Allah the Mighty and Majestic said: ‘Overlook him.’”"]},"buhuth":{"en":["The phrase “be lenient” means to show forbearance in collecting and settling the debt, and to accept a lesser or easier return."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2077)، ومسلم (1560)، واللفظ لمسلم."},{"num":5628,"demo":false,"sanad":"","matn":["عَنْ أَبِي مَسْعُودٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  حُوسِبَ رَجُلٌ مِمَّنْ كَانَ قَبْلَكُمْ، فَلَمْ يُوجَدْ لَهُ مِنَ الْخَيْرِ شَيْءٌ إِلَّا أَنَّهُ كَانَ يُخَالِطُ النَّاسَ، وَكَانَ مُوسِرًا، فَكَانَ يَأْمُرُ غِلْمَانَهُ أَنْ يَتَجَاوَزُوا عَنِ الْمُعْسِرِ. قَالَ: قَالَ اللَّهُ عَزَّ وَجَلَّ: نَحْنُ أَحَقُّ بِذَلِكَ مِنْهُ، تَجَاوَزُوا عَنْهُ."],"takhrij":"صحيح: رواه مسلم في المساقاة (1561: 30) من طرق عن أبي معاوية، عن الأعمش، عن شقيق، عن أبي مسعود فذكره.","grade":"صحيح","chapter_ar":"باب فضل إنظار المعسر","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1561:30).","chapter_en":"The virtue of giving respite to one in hardship","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":13,"content":{"translation":{"en":["Abu Masud said: The Messenger of Allah ﷺ said: “A man from those before you was brought to account, and no good was found for him except that he used to mix with people and was wealthy, and he would order his servants to overlook the debtor in hardship. Allah the Mighty and Majestic said: ‘We are more deserving of that than he was. Overlook him.’”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1561: 30)."},{"num":5629,"demo":false,"sanad":"","matn":["عَنْ أبِي الْيَسَرِ، قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  يَقُولُ: مَنْ أَنْظَرَ مُعْسِرًا أَوْ وَضَعَ عَنْهُ أَظَلَّهُ اللهُ فِي ظِلِّهِ."],"takhrij":"صحيح: رواه مسلم في كتاب الزهد والرقائق (3006) من طرق عن حاتم بن إسماعيل، عن يعقوب بن مجاهد، عن أبي حرزة، عن عبادة بن الوليد بن عبادة بن الصامت قال: خرجت أنا وأبي نطلب العلم في هذا الحي من الأنصار قبل أن يهلكوا، فكان أول من لقينا أبا اليسر. فذكر حديثا طويلا.","grade":"صحيح","chapter_ar":"باب فضل إنظار المعسر","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (3006).","chapter_en":"The virtue of giving respite to one in hardship","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":13,"content":{"translation":{"en":["Abu al-Yusr said: The Messenger of Allah ﷺ said: “Whoever gives respite to one in hardship, or remits part of what he owes, Allah will shade him in His shade.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (3006)."},{"num":5630,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ  أَنَّ أَبَا قَتَادَةَ طَلَبَ غَرِيمًا لَهُ، فَتَوَارَى عَنْهُ، ثُمَّ وَجَدَهُ، فَقَالَ: إِنِّي مُعْسِرٌ، فَقَالَ: اللَّهُ؟ قَالَ: اللَّهُ. قَالَ: فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ سَرَّهُ أَنْ يُنْجِيَهُ اللهُ مِنْ كُرَبِ يَوْمِ الْقِيَامَةِ، فَلْيُنَفِّسْ عَنْ مُعْسِرٍ أَوْ يَضَعْ عَنْهُ."],"takhrij":"صحيح: رواه مسلم في المساقاة (1563) عن أبي الهيثم خالد بن خداش بن عجلان، حدثنا حماد بن زيد، عن أيوب، عن يحيى بن أبى كثير، عن عبد الله بن أبي قتادة فذكره.","grade":"صحيح","chapter_ar":"باب فضل إنظار المعسر","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1563).","chapter_en":"The virtue of giving respite to one in hardship","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":13,"content":{"translation":{"en":["Abdullah ibn Abi Qatadah narrated that Abu Qatadah was seeking a debtor of his, but the man hid from him. Then he found him, and the man said: “I am in hardship.” He said: “By Allah?” He said: “By Allah.” He said: I heard the Messenger of Allah ﷺ say: “Whoever would be pleased that Allah saves him from the distress of the Day of Resurrection, let him give respite to one in hardship or waive part of it for him.”"]}},"tuhfa":{},"full":1,"rep":[12052],"tks":"صحيح: رواه مسلم (1563)."},{"num":5631,"demo":false,"sanad":"","matn":["عَنْ أَبِي قَتَادَةَ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ نَفَّسَ عَنْ غَرِيمِهِ أَوْ مَحَا عَنْهُ كَانَ فِي ظِلِّ الْعَرْشِ يَوْمَ الْقِيَامَةِ."],"takhrij":"صحيح: رواه أحمد (22559)، والدارمي (2631)، والبغوي في شرح السنة (2143) كلهم من حديث عفان بن مسلم، نا حماد بن سلمة، نا أبو جعفر الخطمي، عن محمد بن كعب القرظي، عن أبي قتادة فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب فضل إنظار المعسر","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (22559), al-Darimi (2631), and al-Baghawi in Sharh al-Sunnah (2143).","chapter_en":"The virtue of giving respite to one in hardship","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":13,"content":{"translation":{"en":["Abu Qatadah said: I heard the Messenger of Allah ﷺ say: “Whoever gives relief to his debtor, or wipes away part of the debt for him, will be under the shade of the Throne on the Day of Resurrection.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه أحمد (22559)، والدارمي (2631)، والبغوي في شرح السنة (2143)."},{"num":5632,"demo":false,"sanad":"","matn":["عَنْ سُلَيْمَانَ بْنِ بُرَيْدَةَ، عَنْ أَبِيهِ، قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ أَنْظَرَ مُعْسِرًا فَلَهُ بِكُلِّ يَوْمٍ مِثْلِهِ صَدَقَةٌ، قَالَ: ثُمَّ سَمِعْتُهُ يَقُولُ: مَنْ أَنْظَرَ مُعْسِرًا فَلَهُ بِكُلِّ يَوْمٍ مِثْلَيْهِ صَدَقَةٌ، قُلْتُ: سَمِعْتُكَ يَا رَسُولَ اللَّهِ تَقُولُ: مَنْ أَنْظَرَ مُعْسِرًا فَلَهُ بِكُلِّ يَوْمٍ مِثْلِهِ صَدَقَةٌ، ثُمَّ سَمِعْتُكَ تَقُولُ: مَنْ أَنْظَرَ مُعْسِرًا فَلَهُ بِكُلِّ يَوْمٍ مِثْلَيْهِ صَدَقَةٌ، قَالَ لَهُ: بِكُلِّ يَوْمٍ صَدَقَةٌ قَبْلَ أَنْ يَحِلَّ الدَّيْنُ، فَإِذَا حَلَّ الدَّيْنُ فَأَنْظَرَهُ فَلَهُ بِكُلِّ يَوْمٍ مِثْلَيْهِ صَدَقَةٌ."],"takhrij":"صحيح: رواه أحمد (23046) والحاكم (2225) كلاهما من حديث عفان بن مسلم، حدثنا عبد الوارث، حدثنا محمد بن جُحادة، عن سليمان بن بريدة، عن أبيه، فذكره،","grade":"صحيح","chapter_ar":"باب فضل إنظار المعسر","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (23046) and al-Hakim (2/29). The wording is Ahmad’s.","chapter_en":"The virtue of giving respite to one in hardship","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":13,"content":{"translation":{"en":["Buraydah ibn al-Husayb said: I heard the Messenger of Allah ﷺ say: “Whoever gives respite to one in hardship will have the equivalent of it in charity each day.” Then I heard him say: “Whoever gives respite to one in hardship will have double its equivalent in charity each day.” I said: “I heard you, O Messenger of Allah ﷺ, say: ‘Whoever gives respite to one in hardship will have the equivalent of it in charity each day,’ then I heard you say: ‘Whoever gives respite to one in hardship will have double its equivalent in charity each day.’” He said: “He has charity for each day before the debt becomes due, and when the debt becomes due and he still grants respite, then he has double its equivalent in charity for each day.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[12053],"tks":"صحيح: رواه أحمد (23046) والحاكم (2225)، واللفظ لأحمد."},{"num":5633,"demo":false,"sanad":"","matn":["عن كَعْبِ بن مَالِكٍ عَنْ كَعْبٍ، أَنَّهُ تَقَاضَى ابْنَ أَبِي حَدْرَدٍ دَيْنًا كَانَ لَهُ عَلَيْهِ فِي الْمَسْجِدِ، فَارْتَفَعَتْ أَصْوَاتُهُمَا، حَتَّى سَمِعَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهْوَ فِي بَيْتِهِ، فَخَرَجَ إِلَيْهِمَا حَتَّى كَشَفَ سِجْفَ حُجْرَتِهِ، فَنَادَى: يَا كَعْبُ. قَالَ: لَبَّيْكَ يَا رَسُولَ اللَّهِ. قَالَ: ضَعْ مِنْ دَيْنِكَ هَذَا. وَأَوْمَأَ إِلَيْهِ أَىِ الشَّطْرَ. قَالَ: لَقَدْ فَعَلْتُ يَا رَسُولَ اللَّهِ. قَالَ: قُمْ فَاقْضِهِ."],"takhrij":"متفق عليه: رواه البخاري في الصلاة (457)، ومسلم في المساقاة (1558) كلاهما من حديث عثمان بن عمر قال: أخبرنا يونس، عن الزهري، عن عبد الله بن كعب، عن كعب بن مالك فذكره.","grade":"متفق عليه","chapter_ar":"باب استحباب الوضع من الدَّين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (457) and Muslim (1558).","chapter_en":"The recommendation of reducing a debt","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":14,"content":{"translation":{"en":["Kab ibn Malik was demanding from Ibn Abi Hadrad a debt owed to him in the mosque, and their voices rose until the Messenger of Allah ﷺ heard them while he was in his house. He came out to them and lifted the curtain of his room, then called out: “O Kab.” He said: “At your service, O Messenger of Allah ﷺ.” He said: “Reduce some of your debt,” and he indicated half of it. Kab said: “I have done so, O Messenger of Allah ﷺ.” He said: “Then stand and pay him.”"]}},"tuhfa":{},"full":1,"rep":[3107,5590],"tks":"متفق عليه: رواه البخاري (457)، ومسلم (1558)."},{"num":5634,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ:  أُصِيبَ رَجُلٌ فِي عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي ثِمَارٍ ابْتَاعَهَا، فَكَثُرَ دَيْنُهُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: تَصَدَّقُوا عَلَيْهِ. فَتَصَدَّقَ النَّاسُ عَلَيْهِ، فَلَمْ يَبْلُغْ ذَلِكَ وَفَاءَ دَيْنِهِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِغُرَمَائِهِ: خُذُوا مَا وَجَدْتُمْ، وَلَيْسَ لَكُمْ إِلَّا ذَلِكَ."],"takhrij":"صحيح: رواه مسلم في المساقاة (1556) عن قتيبة بن سعيد، حدثنا الليث، عن بكير، عن عياض بن عبد الله ، عن أبي سعيد الخدري فذكره.","grade":"صحيح","chapter_ar":"باب قسمة مال المفلس بين الغرماء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1556).","chapter_en":"Dividing the wealth of the bankrupt among the creditors","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":15,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī reported: A man during the lifetime of the Messenger of Allah ﷺ suffered a loss in fruits that he had purchased, and his debts became numerous. The Messenger of Allah ﷺ said: “Give charity to him.” The people gave charity to him, but what they gave was not enough to discharge his debt fully. The Messenger of Allah ﷺ then said to his creditors: “Take whatever you find, and you are entitled to nothing beyond that.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[4254,5765,12484],"tks":"صحيح: رواه مسلم (1556)."},{"num":5635,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ أَدْرَكَ مَالَهُ بِعَيْنِهِ عِنْدَ رَجُلٍ - أَوْ إِنْسَانٍ- قَدْ أَفْلَسَ فَهْوَ أَحَقُّ بِهِ مِنْ غَيْرِهِ."],"takhrij":"متفق عليه: رواه البخاري في الاستقراض (2402)، ومسلم في المساقاة (1559: 22) كلاهما عن أحمد بن عبد الله بن يونس، حدثنا زهير بن حرب، حدثنا يحيى بن سعيد، أخبرني أبو بكر بن محمد بن عمرو بن حزم أن عمر بن عبد العزيز أخبره أن أبا بكر بن عبد الرحمن بن الحارث بن هشام أخبره أنه سمع أبا هريرة يقول فذكره.","grade":"متفق عليه","chapter_ar":"باب من وجد ماله بعينه عند مفلس فهو أحق به","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2402) and Muslim (1559:22).","chapter_en":"Whoever finds his property itself with a bankrupt person has more right to it","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":16,"content":{"translation":{"en":["Abu Hurairah said: The Messenger of Allah ﷺ said: “Whoever finds his property itself with a man — or a person — who has become bankrupt, he has more right to it than anyone else.”"]},"buhuth":{"en":["Muslim also narrated it by another route with the wording: “If a man becomes bankrupt and another man finds his goods themselves, then he has more right to them.” In another wording: “then he has more right to it than the creditors.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2402)، ومسلم (1559: 22)."},{"num":5636,"demo":false,"sanad":"","matn":["عَنْ سَمُرَةَ بْنِ جُنْدُبٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ وَجَدَ عَيْنَ مَالِهِ عِنْدَ رَجُلٍ فَهُوَ أَحَقُّ بِهِ."],"takhrij":"صحيح: رواه أبو داود في \"السنن\" (3531)، وفي \"المراسيل\" abudawud(181)، والنسائي (4681)، وأحمد (20148)، وابن الجارود (1026)، والبيهقي (11546) كلهم من حديث هشيم، عن موسى بن السائب، عن قتادة، عن الحسن، عن سمرة فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الرجل يجد ماله المسروق أو المفقود عند رجل فهو أحق به","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3531), in al-Marasil (181), al-Nasai (4681), and Ahmad (20148).","chapter_en":"What has been reported regarding a man finding his stolen or lost property with another man; he is more entitled to it","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":18,"content":{"translation":{"en":["Samurah ibn Jundub said: The Messenger of Allah ﷺ said: “Whoever finds the very property of his own with a man is more entitled to it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (3531)، وفي المراسيل abudawud(181)، والنسائي (4681)، وأحمد (20148)."},{"num":5637,"demo":false,"sanad":"","matn":["عن أُسَيْدِ بن ظهير الأنصاري أَخْبَرَهُ أَنَّهُ كَانَ عَامِلًا عَلَى الْيَمَامَةِ، وَأَنَّ مَرْوَانَ كَتَبَ إِلَيْهِ، أَنَّ مُعَاوِيَةَ كَتَبَ إِليَّ: أَيُّمَا رَجُلٍ سُرِقَ مِنْهُ سَرِقَةٌ فَهُوَ أَحَقُّ بِهَا حَيْثُمَا وَجَدَهَا، قَالَ: وَكَتَبَ بِذَلِكَ مَرْوَانُ إِلَيَّ، فَكَتَبْتُ إِلَى مَرْوَانَ، أَن النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَضَى بِأَنَّهُ إِذَا كَانَ الَّذِي ابْتَاعَهَا مِنَ الَّذِي سَرَقَهَا غَيْرَ مُتَّهَمٍ، فَخُيِّرَ سَيِّدُهَا، فَإِنْ شَاءَ أَخَذَ الَّذِي سُرِقَ مِنْهُ بِثَمَنِهِ، وإِنْ شَاءَ اتَّبَعَ سَارِقَه، ثُمَّ قَضَى بَعْدَ ذَلِكَ بِهِ أَبُو بَكْرٍ وَعُمَرُ وَعُثْمَان، قَالَ: فَبَعَثَ مَرْوَانُ بِكِتَابِي إِلَى مُعَاوِيَةَ، قَالَ: فَكَتَبَ مُعَاوِيَةُ إِلَى مَرْوَانَ: إِنَّكَ لَسْتَ أَنْتَ وَلَا أُسَيْدُ بْنُ ظُهَيْرٍ بِقَاضِيَيْنِ عَلَيَّ، وَلكنِّي أَقْضِي فِيمَا وُلِّيتُ عَلَيْكُمَا، فَأَنْفِذْ لِمَا أَمَرْتُكَ بِهِ، فَبَعَثَ مَرْوَانُ إِلَيَّ بِكِتَابِ مُعَاوِيَةَ، فَقُلْتُ: لَا أَقْضِي بِهِ مَا وُلِّيت، يَعْنِي بِقَوْلِ مُعَاوِيَةَ."],"takhrij":"صحيح: أخرجه عبد الرزاق (18829) عن ابن جريج قال: لقد أخبرني عكرمة بن خالد أن أسيد بن ظهير الأنصاري أخبره فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الرجل يجد ماله المسروق أو المفقود عند رجل فهو أحق به","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Related by Abd al-Razzaq (17986, 18829), Abu Dawud in al-Marasil (180), and al-Nasai (4680).","chapter_en":"What has been reported regarding a man finding his stolen or lost property with another man; he is more entitled to it","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":18,"content":{"translation":{"en":["Usayd ibn Zuhayr al-Ansari was an official over al-Yamamah, and Marwan wrote to him that Muawiyah had written to him: Any man from whom something was stolen is more entitled to it wherever he finds it. He said: Marwan wrote that to me, so I wrote back to Marwan that the Prophet ﷺ had judged that if the one who bought it from the thief was not accused of wrongdoing, then its owner is given a choice: if he wishes, he takes back what was stolen from him and pays its price, and if he wishes, he may pursue the thief. Then Abu Bakr, Umar, and Uthman also judged by that. He said: Marwan sent my letter to Muawiyah. Muawiyah then wrote to Marwan: Neither you nor Usayd ibn Zuhayr are to judge over me; rather I judge in what I have authority over you, so carry out what I ordered you. Marwan sent me Muawiyah’s letter, and I said: I will not judge by it while I remain in authority — meaning by Muawiyah’s opinion."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: أخرجه عبد الرزاق (17986 ،18829)، وأبو داود في المراسيل (180)، والنسائي (4680)."},{"num":5638,"demo":false,"sanad":"","matn":["عَنْ الشريد بن سُوَيْدٍ الثقفي قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لِي الْوَاجِدِ يحلُّ عِرْضَهُ وَعُقُوبَتَهُ."],"takhrij":"حسن: رواه أبو داود (3628)، والنسائي (4689، 4690)، وابن ماجه (2427)، وأحمد (17946)، وصحّحه ابن حبان (5089)، والحاكم (7065) كلهم من حديث وبر بن أبي دُلَيلة شيخ من أهل الطائف، عن محمد بن ميمون بن مسيكة، عن عمرو بن الشريد، عن أبيه فذكره.","grade":"حسن","chapter_ar":"باب الحبس في الدَّين والملازمة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3628), al-Nasai (4689, 4690), Ibn Majah (2427), and Ahmad (17946).","chapter_en":"Imprisonment for debt and holding the debtor to account","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":19,"content":{"translation":{"en":["Al-Sharid ibn Suwayd al-Thaqafi said: The Messenger of Allah ﷺ said: “The delay of one who has means makes his honor lawful to speak against and makes punishment lawful.”"]},"buhuth":{"en":["The phrase “delay of one who has means” means postponement by a person able to repay his debt.","“His honor” means: complaint against him.","“And his punishment” means: imprisonment. This was explained by Ali al-Tanafisi, the teacher of Ibn Majah."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3628)، والنسائي (4690 ،4689)، وابن ماجه (2427)، وأحمد (17946)."},{"num":5639,"demo":false,"sanad":"","matn":["عَنِ ابْنِ أُذْنَانَ، قَالَ: أَسْلَفْتُ عَلْقَمَةَ أَلْفَيْ دِرْهَمٍ، فَلَمَّا خَرَجَ عَطَاؤُهُ، قُلْتُ لَهُ: اقْضِنِي، قَالَ: أَخِّرْنِي إِلَى قَابِلٍ، فَأَبَيْتُ عَلَيْهِ، فَأَخَذْتُهَا، قَالَ: فَأَتَيْتُهُ بَعْدُ، قَالَ: بَرَّحْتَ بِي وقَدْ مَنَعْتَنِي، فَقُلْتُ: نَعَمْ، هُوَ عَمَلُكَ، قَالَ: وَمَا شَأْنِي؟ قُلْتُ: إِنَّكَ حَدَّثْتَنِي عَنِ ابْنِ مَسْعُودٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ السَّلَفَ يَجْرِي مَجْرَى شَطْرِ الصَّدَقَةِ. قَالَ: نَعَمْ، فَهُوَ كَذَاكَ، قَالَ: فَخُذِ الْآنَ."],"takhrij":"حسن: رواه أحمد (3911) وأبو يعلى (5366) كلاهما من حديث عفان، حدثنا حماد، أخبرنا عطاء بن السائب، عن ابن أذنان، قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الدَّين وإن أجره كأجر الصدقة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (3911), Abu Ya‘la (5366), and Ibn Majah (2430).","chapter_en":"What has been reported regarding lending and that its reward is like the reward of charity","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":20,"content":{"translation":{"en":["Ibn Adhnan said: I lent Alqamah two thousand dirhams. When his stipend came out, I said to him: “Pay me.” He said: “Delay me until next year.” I insisted and took it. Later he said to me: “You pressed me hard and withheld ease from me.” I said: “Yes, that was your own doing.” He said: “What do you mean?” I said: “You narrated to me from Ibn Masud that the Prophet ﷺ said: ‘A loan runs in place of half of charity.’” He said: “Yes, that is so.” Then he said: “Take it now.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (3911) وأبو يعلى (5366)، وابن ماجه (2430)."},{"num":5640,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ قَالَ: عُرِضتُ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ أُحُد وَأَنَا ابْنُ أَرْبَعَ عَشْرَةَ سَنَةً فَلَمْ يُجِزْنِي، وعُرضتُ عَلَيْهِ يَوْمَ الْخَنْدَقِ وَأَنَا ابْنُ خَمْسَ عَشْرَةَ سَنَةً فَأَجَازَنِي."],"takhrij":"متفق عليه: رواه البخاري في الشهادات (2664)، ومسلم في الإمارة (1868) كلاهما من حديث عبيد الله قال: حدثني نافـع قال: حدثني ابن عمر فذكره.","grade":"متفق عليه","chapter_ar":"باب علامات البلوغ في الرجال والنساء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2664) and Muslim (1868).","chapter_en":"The signs of maturity in men and women","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الحجر على الصغير والبالغين في السفه","group_en":"Collection of reports regarding restriction over minors and over adults due to foolishness","part_no":17,"group_no":10,"chapter_no":1,"content":{"translation":{"en":["Ibn Umar said: I was presented to the Prophet ﷺ on the Day of Uhud when I was fourteen years old, and he did not permit me. Then I was presented to him on the Day of al-Khandaq when I was fifteen years old, and he permitted me."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2664)، ومسلم (1868)."},{"num":5641,"demo":false,"sanad":"","matn":["عَنْ عَطِيَّةَ الْقُرَظِيِّ، قَالَ: عُرِضْنَا عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ قُرَيْظَةَ، فَكَانَ مَنْ أَنْبَتَ قُتِلَ، وَمَنْ لَمْ يُنْبِتْ خُلِّيَ سَبِيلُهُ، فَكُنْتُ مِمَّنْ لَمْ يُنْبِتْ، فَخُلِّيَ سَبِيلِي."],"takhrij":"صحيح: رواه أبو داود (4405)، والترمذي (1584)، والنسائي (4981)، وابن ماجه (2541)، وأحمد (18776)، وصحّحه ابن حبان (4781)، والحاكم (2/123) كلهم من طرق عن عبد الملك بن عمير قال: سمعت عطية القرظي فذكره.","grade":"صحيح","chapter_ar":"باب علامات البلوغ في الرجال والنساء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (4405), al-Tirmidhi (1584), al-Nasai (4981), Ibn Majah (2541), and Ahmad (18776). Al-Tirmidhi said: “Hasan Sahih.”","chapter_en":"The signs of maturity in men and women","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الحجر على الصغير والبالغين في السفه","group_en":"Collection of reports regarding restriction over minors and over adults due to foolishness","part_no":17,"group_no":10,"chapter_no":1,"content":{"translation":{"en":["Atiyyah al-Qurazi said: We were presented to the Prophet ﷺ on the Day of Qurayzah. Those who had grown pubic hair were killed, and those who had not were let go. I was among those who had not grown it, so my way was left open."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (4405)، والترمذي (1584)، والنسائي (4981)، وابن ماجه (2541)، وأحمد (18776). وقال الترمذي: “حسن صحيح”."},{"num":5642,"demo":false,"sanad":"","matn":["عَنْ سَمُرَةَ بْنِ جُنْدُبٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اقْتُلُوا شُيُوخَ الْمُشْرِكِينَ وَاسْتَبْقُوا شَرْخَهُمْ."],"takhrij":"حسن: رواه أبو داود (2670) عن سعيد بن منصور، وهو في سننه (2624): حدثنا هشيم، حدثنا حجاج، حدثنا قتادة، عن الحسن، عـن سمرة بن جندب قال: فذكره.","grade":"حسن","chapter_ar":"باب علامات البلوغ في الرجال والنساء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2670) and Sa‘id ibn Mansur in his Sunan (2624).","chapter_en":"The signs of maturity in men and women","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الحجر على الصغير والبالغين في السفه","group_en":"Collection of reports regarding restriction over minors and over adults due to foolishness","part_no":17,"group_no":10,"chapter_no":1,"content":{"translation":{"en":["Samurah ibn Jundub said: The Messenger of Allah ﷺ said: “Kill the elder polytheists and spare their young.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[7902],"tks":"حسن: رواه أبو داود (2670) وسعيد بن منصور في سننه (2624)."},{"num":5643,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: لاَ يَقْبَلُ اللَّهُ صَلاَةَ حَائِضٍ إِلاَّ بِخِمَارٍ."],"takhrij":"صحيح: رواه أبو داود (641)، والترمذي (377)، وابن ماجه (655) وصحّحه ابن خزيمة (775) وعنه ابن حبان (1712)، والحاكم (917) كلهم من طرق عن حماد بن سلمة، عن قتادة، عن محمد بن سيرين، عن صفية بنت الحارث، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب علامات البلوغ في الرجال والنساء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (641), al-Tirmidhi (377), Ibn Majah (655), and authenticated by Ibn Khuzaymah (775).","chapter_en":"The signs of maturity in men and women","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الحجر على الصغير والبالغين في السفه","group_en":"Collection of reports regarding restriction over minors and over adults due to foolishness","part_no":17,"group_no":10,"chapter_no":1,"content":{"translation":{"en":["Aishah, the Mother of the Believers, narrated from the Prophet ﷺ that he said: “Allah does not accept the prayer of a mature woman except with a head covering.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[2591],"tks":"صحيح: رواه أبو داود (641)، والترمذي (377)، وابن ماجه (655)، وصححه ابن خزيمة (775)."},{"num":5644,"demo":false,"sanad":"","matn":["عن عَوْفِ بْنِ مَالِكٍ بن الطُّفَيْلِ -وهو ابْنُ الْحَارِثِ ـ هُوَ ابْنُ الْحَارِثِ، وَهْوَ ابْنُ أَخِي عَائِشَةَ زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لأُمِّهَا ـ أَنَّ عَائِشَةَ حُدِّثَتْ أَنَّ عَبْدَ اللَّهِ بْنَ الزُّبَيْرِ قَالَ فِي بَيْعٍ أَوْ عَطَاءٍ أَعْطَتْهُ عَائِشَةُ: وَاللَّهِ لَتَنْتَهِيَنَّ عَائِشَةُ، أَوْ لأَحْجُرَنَّ عَلَيْهَا. فَقَالَتْ: أَهُوَ قَالَ هَذَا؟ قَالُوا: نَعَمْ. قَالَتْ: هُوَ لِلَّهِ عَلَىَّ نَذْرٌ، أَنْ لاَ أُكَلِّمَ ابْنَ الزُّبَيْرِ أَبَدًا. فَاسْتَشْفَعَ ابْنُ الزُّبَيْرِ إِلَيْهَا، حِينَ طَالَتِ الْهِجْرَةُ، فَقَالَتْ: لاَ وَاللَّهِ، لاَ أُشَفِّعُ فِيهِ أَبَدًا، وَلاَ أَتَحَنَّثُ إِلَى نَذْرِي. فَلَمَّا طَالَ ذَلِكَ عَلَى ابْنِ الزُّبَيْرِ كَلَّمَ الْمِسْوَرَ بْنَ مَخْرَمَةَ وَعَبْدَ الرَّحْمَنِ بْنَ الأَسْوَدِ بْنِ عَبْدِ يَغُوثَ، وَهُمَا مِنْ بَنِي زُهْرَةَ، وَقَالَ لَهُمَا: أَنْشُدُكُمَا بِاللَّهِ لَمَّا أَدْخَلْتُمَانِي عَلَى عَائِشَةَ، فَإِنَّهَا لاَ يَحِلُّ لَهَا أَنْ تَنْذُرَ قَطِيعَتِي. فَأَقْبَلَ بِهِ الْمِسْوَرُ وَعَبْدُ الرَّحْمَنِ مُشْتَمِلَيْنِ بِأَرْدِيَتِهِمَا حَتَّى اسْتَأْذَنَا عَلَى عَائِشَةَ، فَقَالاَ: السَّلاَمُ عَلَيْكِ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، أَنَدْخُلُ؟ قَالَتْ عَائِشَةُ: ادْخُلُوا. قَالُوا: كُلُّنَا. قَالَتْ: نَعَمِ، ادْخُلُوا كُلُّكُمْ. وَلاَ تَعْلَمُ أَنَّ مَعَهُمَا ابْنَ الزُّبَيْرِ، فَلَمَّا دَخَلُوا دَخَلَ ابْنُ الزُّبَيْرِ الْحِجَابَ، فَاعْتَنَقَ عَائِشَةَ، وَطَفِقَ يُنَاشِدُهَا، وَيَبْكِي، وَطَفِقَ الْمِسْوَرُ وَعَبْدُ الرَّحْمَنِ يُنَاشِدَانِهَا إِلاَّ مَا كَلَّمَتْهُ، وَقَبِلَتْ مِنْهُ، وَيَقُولاَنِ: إِنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَمَّا قَدْ عَلِمْتِ مِنَ الْهِجْرَةِ، فَإِنَّهُ لاَ يَحِلُّ لِمُسْلِمٍ أَنْ يَهْجُرَ أَخَاهُ فَوْقَ ثَلاَثِ لَيَالٍ. فَلَمَّا أَكْثَرُوا عَلَى عَائِشَةَ مِنَ التَّذْكِرَةِ وَالتَّحْرِيجِ طَفِقَتْ تُذَكِّرُهُمَا، نَذْرَهَا وَتَبْكِي، وَتَقُولُ: إِنِّي نَذَرْتُ، وَالنَّذْرُ شَدِيدٌ. فَلَمْ يَزَالاَ بِهَا حَتَّى كَلَّمَتِ ابْنَ الزُّبَيْرِ، وَأَعْتَقَتْ فِي نَذْرِهَا ذَلِكَ أَرْبَعِينَ رَقَبَةً. وَكَانَتْ تَذْكُرُ نَذْرَهَا بَعْدَ ذَلِكَ، فَتَبْكِي، حَتَّى تَبُلَّ دُمُوعُهَا خِمَارَهَا."],"takhrij":"صحيح: رواه البخاري في الأدب (6073، 6074، 6075) عـن أبي اليمان، أخبرنا شعيب، عن الزهري قال: حدثني عوف بن مالك فذكره.","grade":"صحيح","chapter_ar":"باب الحجر على البالغ إذا كان سفيها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (6073, 6074, 6075).","chapter_en":"Restricting an adult if he is foolish in financial conduct","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الحجر على الصغير والبالغين في السفه","group_en":"Collection of reports regarding restriction over minors and over adults due to foolishness","part_no":17,"group_no":10,"chapter_no":2,"content":{"translation":{"en":["Awf ibn Malik ibn al-Tufayl — who was the son of al-Harith, and the son of the sister of Aishah, the wife of the Prophet ﷺ through her mother — narrated that Aishah said that Abdullah ibn al-Zubayr remarked concerning a sale or gift that Aishah had given: “By Allah, Aishah must stop, or I will place restrictions on her.” She said: “Did he really say this?” They said: Yes. She said: “Then for Allah upon me is a vow that I will never speak to Ibn al-Zubayr again.” Ibn al-Zubayr later sought intercession with her after the estrangement had become long, but she said: “No, by Allah, I will never intercede for him, nor will I break my vow.” When that became difficult for Ibn al-Zubayr, he asked al-Miswar ibn Makhramah and Abd al-Rahman ibn al-Aswad ibn Abd Yaghuth — both from Banu Zuhrah — and said to them: “I ask you by Allah to get me admitted to Aishah, for it is not lawful for her to vow to cut me off.” So al-Miswar and Abd al-Rahman came with him wrapped in their cloaks until they sought permission from Aishah. They said: “Peace be upon you, and the mercy of Allah and His blessings. May we enter?” Aishah said: “Enter.” They said: “All of us?” She said: “Yes, all of you may enter,” not realizing that Ibn al-Zubayr was with them. When they entered, Ibn al-Zubayr slipped behind the curtain, embraced Aishah, and began pleading with her and weeping. Al-Miswar and Abd al-Rahman also pleaded with her to speak to him and accept from him, saying: “The Prophet ﷺ forbade the kind of estrangement you already know. It is not lawful for a Muslim to abandon his brother for more than three nights.” When they repeatedly reminded and pressed her, she began recalling that and weeping, saying: “I made a vow, and a vow is serious.” They continued until she spoke to Ibn al-Zubayr, and she freed forty slaves as expiation for that vow. After that, whenever she remembered her vow, she would weep until her tears soaked her head covering."]},"buhuth":{"en":["This proposed restriction against Aishah was not appropriate, because she was not foolish in judgment. Her financial conduct was sound, and that is why she did not accept Ibn al-Zubayr’s attempt to restrict her, but instead became firm in refusing to speak to him."]},"intro":{"ar":["قال اللّٰه تعالى: ( وَلَا تُؤْتُوا السُّفَهَاءَ أَمْوَالَكُمُ الَّتِي جَعَلَ اللَّهُ لَكُمْ قِيَامًا ) [سورة النساء: ٥].","وقال تعالى: ( فَإِن كَانَ الَّذِي عَلَيْهِ الْحَقُّ سَفِيهًا أَوْ ضَعِيفًا ) الآية [سورة البقرة: ٢٨٢].","فأثبت الولاية على السفيه، كما أثبتها على الضعيف.","ومعنى السفيه راجع إلى الكبير البالغ، ومعنى الضعيف راجع إلى الصغير.","وقال سبحانه وتعالى: ( وَابْتَلُوا الْيَتَامَى حَتَّىٰ إِذَا بَلَغُوا النِّكَاحَ فَإِنْ آنَسْتُم مِّنْهُمْ رُشْدًا فَادْفَعُوا إِلَيْهِمْ أَمْوَالَهُمْ ) [سورة النساء: ٦]. فشرط في دفع المال إليهم شيئين: الاحتلام والرشد.","والحكم إذا كان وجوبه معلقا بشيئين لم يجب إلا بورودهما معا.","قاله الخطابي في معالمه (٤/١٥٢-١٥٣).","وهذا الحجر على عائشة لم يكن في محله؛ لأنها لم تكن سفيهة؛ فإن تصرفها كان صحيحاً، ولذا لم ترض بحجر ابن الزبير، بل شددت عليه بأن لا تكلمه أبداً."],"en":["Allah the Exalted said: “Do not give the foolish your wealth which Allah has made a means of support for you.” [al-Nisa: 5]","And He said: “If the one upon whom the obligation is due is foolish or weak…” [al-Baqarah: 282]","So He established guardianship over the foolish person just as He established it over the weak one.","The meaning of “foolish” here refers to the adult of unsound financial judgment, while the meaning of “weak” refers to the minor.","And He, Glorified and Exalted, said: “Test the orphans until they reach marriageable age; then if you perceive in them sound judgment, hand over to them their wealth.” [al-Nisa: 6] Thus He made two conditions for handing wealth over to them: puberty and sound judgment.","A ruling whose obligation is tied to two conditions does not become due unless both are present together.","This was stated by al-Khattabi in Ma‘alim al-Sunan (4/152–153).","This proposed restriction against Aishah was not appropriate, because she was not foolish in judgment. Her financial conduct was sound, and that is why she did not accept Ibn al-Zubayr’s attempt to restrict her, but instead became firm in refusing to speak to him."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (6073، 6074، 6075)."},{"num":5645,"demo":false,"sanad":"","matn":["عَنْ حَنْظَلَةَ يَقُولُ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا يُتْمَ بَعْدَ احتلام، وَلَا يُتْمَ عَلَى جَارِيَةٍ إِذَا هِيَ حَاضَتْ."],"takhrij":"حسن: رواه الطبراني في الكبير (3502) عن محمد بن عبد الله الحضرمي، ثنا محمد بن أبي بكر المقدمي، ثنا سلم بن قتيبة، ثنا ذيال بن عبيد قال: سمعت جدي حنظلة فذكره.","grade":"حسن","chapter_ar":"باب متى ينقطع اليتم","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Kabir (4/16).","chapter_en":"When orphanhood ends","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الحجر على الصغير والبالغين في السفه","group_en":"Collection of reports regarding restriction over minors and over adults due to foolishness","part_no":17,"group_no":10,"chapter_no":3,"content":{"translation":{"en":["Hanzalah said: The Messenger of Allah ﷺ said: “There is no orphanhood after puberty, and there is no orphanhood for a girl once she menstruates.”"]},"buhuth":{"en":["Al-Khattabi said: The apparent meaning of this hadith indicates that the rulings of orphanhood end upon puberty, and the rulings of adulthood begin. Thus, a person who has reached puberty may buy, sell, manage his wealth, and contract marriage for himself; and if it is a woman, she is not married off except with her permission. However, if the person who has reached puberty is not sound in judgment, then the restriction over him is not lifted. A thing may be restricted for two reasons, and it does not become unrestricted just because one reason is gone while the other remains. Allah the Exalted commanded restriction over the foolish person, saying: “Do not give the foolish your wealth which Allah has made a means of support for you.” [al-Nisa: 5]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (3502)."},{"num":5646,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اشْتَرَى مِنْ يَهُودِيٍّ طَعَامًا إِلَى أَجَلٍ وَرَهَنَهُ دِرْعَهُ."],"takhrij":"متفق عليه: رواه البخاري في الرهن (2509)، ومسلم في المساقاة (162: 126) كلاهما من طريق عبدالواحد بن زياد، حدثنا الأعمش قال: تذاكرنا عند إبراهيم الرهن والقبيل في السلف، فقال إبراهيم: حدثنا الأسود، عن عائشة فذكرته.","grade":"متفق عليه","chapter_ar":"باب مشروعية الرهن وجوازه في السفر والحضر","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2509) and Muslim (1603:126).","chapter_en":"The legislation of pledges and their permissibility in travel and residence","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الرهن","group_en":"Collection of reports regarding pledges and collateral","part_no":17,"group_no":11,"chapter_no":1,"content":{"translation":{"en":["Aishah narrated that the Prophet ﷺ bought food from a Jew on deferred payment and pledged his armor to him."]},"intro":{"ar":["قال اللّٰه تعالى: ( وَإِنْ كُنْتُمْ عَلَى سَفَرٍ وَلَمْ تَجِدُوا كَاتِبًا فَرِهَانٌ مَقْبُوضَةٌ ) [سورة البقرة: ٢٨٣]."],"en":["Allah the Exalted said: “And if you are on a journey and cannot find a scribe, then let there be a pledge taken in possession.” [al-Baqarah: 283]"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (2509)، ومسلم (126 :1603)."},{"num":5647,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: وَلَقَدْ رَهَنَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دِرْعَهُ بِشَعِيرٍ، وَمَشَيْتُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِخُبْزِ شَعِيرٍ وَإِهَالَةٍ سَنِخَةٍ، وَلَقَدْ سَمِعْتُهُ يَقُولُ: مَا أَصْبَحَ لآلِ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلاَّ صَاعٌ، وَلاَ أَمْسَى. وَإِنَّهُمْ لَتِسْعَةُ أَبْيَاتٍ."],"takhrij":"صحيح: رواه البخاري في الرهن (2508) عن مسلم بن إبراهيم، حدثنا هشام حدثنا قتادة عن أنس قال فذكره.","grade":"صحيح","chapter_ar":"باب مشروعية الرهن وجوازه في السفر والحضر","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2508).","chapter_en":"The legislation of pledges and their permissibility in travel and residence","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الرهن","group_en":"Collection of reports regarding pledges and collateral","part_no":17,"group_no":11,"chapter_no":1,"content":{"translation":{"en":["Anas said: The Messenger of Allah ﷺ pledged his armor for barley, and I went to the Prophet ﷺ with barley bread and stale melted fat. I heard him say: “The family of Muhammad ﷺ does not have as much as one sa of food in the morning nor in the evening, though they are nine households.”"]}},"tuhfa":{},"full":1,"rep":[7381],"tks":"صحيح: رواه البخاري (2508)."},{"num":5648,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ: قُبِضَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَدِرْعُهُ مَرْهُونَةٌ عِنْدَ رَجُلٍ مِنْ يَهُودَ عَلَى ثَلَاثِينَ صَاعًا مِنْ شَعِير، أَخَذَهَا رِزْقًا لِعِيَالِهِ."],"takhrij":"صحيح: رواه الترمذي (1214)، والنسائي (4651)، وأحمد (2109، 3409)، والبيهقي (6/36) كلهم من حديث هشام بن حسان، عن عكرمة، عن ابن عباس فذكره إلا أن الترمذي قال: \"عشرين صاعا\".","grade":"صحيح","chapter_ar":"باب مشروعية الرهن وجوازه في السفر والحضر","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (1214), al-Nasai (4651), and Ahmad (2109, 3409). He said: “Hasan Sahih.”","chapter_en":"The legislation of pledges and their permissibility in travel and residence","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الرهن","group_en":"Collection of reports regarding pledges and collateral","part_no":17,"group_no":11,"chapter_no":1,"content":{"translation":{"en":["Abdullah ibn Abbas narrated that the Messenger of Allah ﷺ died while his armor was pledged with a Jew for thirty sa of barley, which he had taken as provision for his family."]},"buhuth":{"en":["Ahmad added at the beginning of the hadith that the Prophet ﷺ looked toward Uhud and said: “By the One in whose hand is Muhammad’s soul, it would not please me that the family of Muhammad had gold equal to Uhud which I spent in the path of Allah, then on the day I die I would leave behind from it two dinars — except two dinars set aside for a debt, if there were one.” So he died leaving behind neither dinar nor dirham, nor a male slave nor a female slave, and he left his armor pledged with a Jew … the hadith."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (1214)، والنسائي (4651)، وأحمد (2109، 3409)، وقال: “حسن صحيح”.","voc":["ahmad",3409]},{"num":5649,"demo":false,"sanad":"","matn":["عن جابر بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا يَقُولُ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ لِكَعْبِ بْنِ الأَشْرَفِ؛ فَإِنَّهُ آذَى اللَّهَ وَرَسُولَهُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَقَالَ مُحَمَّدُ بْنُ مَسْلَمَةَ: أَنَا. فَأَتَاهُ، فَقَالَ: أَرَدْنَا أَنْ تُسْلِفَنَا وَسْقًا أَوْ وَسْقَيْنِ. فَقَالَ: ارْهَنُونِي نِسَاءَكُمْ. قَالُوا: كَيْفَ نَرْهَنُكَ نِسَاءَنَا، وَأَنْتَ أَجْمَلُ الْعَرَبِ؟ قَالَ: فَارْهَنُونِي أَبْنَاءَكُمْ. قَالُوا: كَيْفَ نَرْهَنُ أَبْنَاءَنَا؛ فَيُسَبُّ أَحَدُهُمْ، فَيُقَالُ: رُهِنَ بِوَسْقٍ أَوْ وَسْقَيْنِ، هَذَا عَارٌ عَلَيْنَا، وَلَكِنَّا نَرْهَنُكَ اللأْمَةَ. ـ قَالَ سُفْيَانُ: يَعْنِي السِّلاَحَ ـ فَوَعَدَهُ أَنْ يَأْتِيَهُ، فَقَتَلُوهُ، ثُمَّ أَتَوُا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَخْبَرُوهُ."],"takhrij":"متفق عليه: رواه البخاري في الرهن (2510)، ومسلم في الجهاد (1801) كلاهما من طريق سفيان بن عيينة، عن عمرو (هو ابن دينار) قال: سمعت جابر بن عبد الله فذكره. والسياق للبخاري، ومسلم ذكره بتمامه، وهو بتمامه عند البخاري في المغازي (4037)","grade":"متفق عليه","chapter_ar":"باب مشروعية الرهن وجوازه في السفر والحضر","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2510) and Muslim (1801). The wording here is al-Bukhari’s.","chapter_en":"The legislation of pledges and their permissibility in travel and residence","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الرهن","group_en":"Collection of reports regarding pledges and collateral","part_no":17,"group_no":11,"chapter_no":1,"content":{"translation":{"en":["Jabir said: The Messenger of Allah ﷺ said: “Who will deal with Kab ibn al-Ashraf, for he has harmed Allah and His Messenger ﷺ?” Muhammad ibn Maslamah said: I will. He went to him and said: “We want you to lend us one or two wasqs.” He said: “Pledge your women to me.” They said: “How can we pledge our women to you when you are the most handsome of the Arabs?” He said: “Then pledge your sons to me.” They said: “How can we pledge our sons to you, and one of them would be insulted and it would be said that he was pledged for one or two wasqs? That would be a disgrace for us. But we can pledge you the la’mah.” Sufyan said: meaning weapons. So he promised to come to him, then they killed him, and afterward they came to the Prophet ﷺ and informed him."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (2510)، ومسلم (1801)، والسياق للبخاري."},{"num":5650,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. الرَّهْنُ يُرْكَبُ بِنَفَقَتِهِ إِذَا كَانَ مَرْهُونًا، وَلَبَنُ الدَّرِّ يُشْرَبُ بِنَفَقَتِهِ إِذَا كَانَ مَرْهُونًا، وَعَلَى الَّذِي يَرْكَبُ وَيَشْرَبُ النَّفَقَةُ."],"takhrij":"صحيح: رواه البخاري في الرهن (2512) عن محمد بن مقاتل، أخبرنا عبد الله (هو ابن المبارك)، أخبرنا زكريا (هو ابن أبي زائدة)، عن الشعبي، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب أن المرتهن يركب، ويحلب، وعليه نفقته","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2512).","chapter_en":"The pledge-holder may ride and milk the pledged animal, and he must bear its maintenance","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الرهن","group_en":"Collection of reports regarding pledges and collateral","part_no":17,"group_no":11,"chapter_no":2,"content":{"translation":{"en":["Abu Hurairah said: The Messenger of Allah ﷺ said: “A pledged riding animal may be ridden in return for its maintenance if it has been pledged, and the milk of a pledged milking animal may be drunk in return for its maintenance if it has been pledged, and the one who rides and drinks must bear the maintenance.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (2512)."},{"num":5651,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا يُغْلَقُ الرَّهْنُ، لَهُ غُنْمُهُ، وَعَلَيْهِ غُرْمُهُ."],"takhrij":"حسن: رواه الدارقطني (2923) عن أبي محمد بن صاعد، نا عبد الله بن عمران العابدي، نا سفيان بن عيينة، عن زياد بن سعد، عن الزهري، عن سعيد بن المسيب، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب أن المرتهن لا يستحق الرهن إذا تأخر الراهن عن الوفاء بالدين الذي عليه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Daraqutni (3/34).","chapter_en":"The pledge-holder does not become owner of the pledge merely because the pledger delays repayment","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الرهن","group_en":"Collection of reports regarding pledges and collateral","part_no":17,"group_no":11,"chapter_no":3,"content":{"translation":{"en":["Abu Hurairah said: The Messenger of Allah ﷺ said: “A pledge is not forfeited; its gain belongs to its owner, and its liability is upon him.”"]},"buhuth":{"en":["The phrase “a pledge is not forfeited” means that it does not become permanently closed off so that it can never return to the pledger. Rather, whenever the debt for which it was pledged is paid, it returns to the pledger.","“its gain belongs to its owner” means that any increase or benefit arising from it belongs to the pledger.","“its liability is upon him” means that if it perishes while in the hand of the pledge-holder, its loss remains upon the pledger."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الدارقطني (2923)."},{"num":5652,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا أَنَّهُ قَالَ: بَعَثَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعْثًا قِبَلَ السَّاحِلِ، فَأَمَّرَ عَلَيْهِمْ أَبَا عُبَيْدَةَ بْنَ الْجَرَّاحِ، وَهُمْ ثَلاَثُمِائَةٍ. وَأَنَا فِيهِمْ، فَخَرَجْنَا حَتَّى إِذَا كُنَّا بِبَعْضِ الطَّرِيقِ فَنِيَ الزَّادُ، فَأَمَرَ أَبُو عُبَيْدَةَ بِأَزْوَادِ ذَلِكَ الْجَيْشِ، فَجُمِعَ ذَلِكَ كُلُّهُ، فَكَانَ مِزْوَدَىْ تَمْرٍ، فَكَانَ يُقَوِّتُنَا كُلَّ يَوْمٍ قَلِيلاً قَلِيلاً، حَتَّى فَنِيَ، فَلَمْ يَكُنْ يُصِيبُنَا إِلاَّ تَمْرَةٌ تَمْرَةٌ. فَقُلْتُ: وَمَا تُغْنِي تَمْرَةٌ؟ فَقَالَ: لَقَدْ وَجَدْنَا فَقْدَهَا حِينَ فَنِيَتْ. قَالَ: ثُمَّ انْتَهَيْنَا إِلَى الْبَحْرِ فَإِذَا حُوتٌ مِثْلُ الظَّرِبِ، فَأَكَلَ مِنْهُ ذَلِكَ الْجَيْشُ ثَمَانِيَ عَشْرَةَ لَيْلَةً، ثُمَّ أَمَرَ أَبُو عُبَيْدَةَ بِضِلَعَيْنِ مِنْ أَضْلاَعِهِ، فَنُصِبَا، ثُمَّ أَمَرَ بِرَاحِلَةٍ فَرُحِلَتْ، ثُمَّ مَرَّتْ تَحْتَهُمَا، فَلَمْ تُصِبْهُمَا."],"takhrij":"متفق عليه: رواه مالك في صفة النبي صلى الله عليه وسلم (24) عن وهب بن كيسان، عن جابر بن عبدالله أنه قال فذكره.","grade":"متفق عليه","chapter_ar":"باب الشركة في الطعام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (24), al-Bukhari (2483), and Muslim (1935:21).","chapter_en":"Partnership in food","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الشركة","group_en":"Collection of reports regarding partnership","part_no":17,"group_no":12,"chapter_no":1,"content":{"translation":{"en":["Jabir ibn Abdullah said: The Messenger of Allah ﷺ sent an expedition toward the coast and appointed Abu Ubaydah ibn al-Jarrah over them, and they were three hundred men. I was among them. We set out until, at some point on the road, the provisions ran out. Abu Ubaydah ordered the provisions of that army to be gathered together, and all of it was collected; our provision consisted of dates. He would then give us a little each day until it was exhausted, until all we received was one date each. I said: “What good is one date?” He replied: “We truly realized its value once it was gone.” Then we reached the sea, and there was a huge fish like a hill. That army ate from it for eighteen nights. Then Abu Ubaydah ordered two of its ribs to be raised upright, then ordered a riding camel to be saddled, and it passed beneath them without touching them."]}},"tuhfa":{},"full":1,"dr":1,"rep":[8953],"tks":"متفق عليه: رواه مالك (24)، والبخاري (2483)، ومسلم (21 :1935)."},{"num":5653,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى، قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ الأَشْعَرِيِّينَ إِذَا أَرْمَلُوا فِي الْغَزْوِ، أَوْ قَلَّ طَعَامُ عِيَالِهِمْ بِالْمَدِينَةِ جَمَعُوا مَا كَانَ عِنْدَهُمْ فِي ثَوْبٍ وَاحِدٍ، ثُمَّ اقْتَسَمُوهُ بَيْنَهُمْ فِي إِنَاءٍ وَاحِدٍ بِالسَّوِيَّةِ، فَهُمْ مِنِّي، وَأَنَا مِنْهُمْ."],"takhrij":"متفق عليه: رواه البخاري في الشركة (2486)، ومسلم في فضائل الصحابة (2500) كلاهما من طريق أبي أسامة حماد بن أسامة، حدثني بُريد بن عبد الله بن أبي بردة، عن جده أبي بردة، عن أبي موسى قال فذكره.","grade":"متفق عليه","chapter_ar":"باب الشركة في الطعام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2486) and Muslim (2500).","chapter_en":"Partnership in food","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الشركة","group_en":"Collection of reports regarding partnership","part_no":17,"group_no":12,"chapter_no":1,"content":{"translation":{"en":["Abu Musa al-Ashari said: The Prophet ﷺ said: “When the Asharis become short of provisions during a campaign, or the food of their families in Madinah becomes scarce, they gather what they have into one cloth, then divide it equally among themselves in one vessel. They are from me, and I am from them.”"]}},"tuhfa":{},"full":1,"rep":[10518],"tks":"متفق عليه: رواه البخاري (2486)، ومسلم (2500)."},{"num":5654,"demo":false,"sanad":"","matn":["عَنْ جَبَلَةَ، قَالَ: كُنَّا بِالْمَدِينَةِ، فَأَصَابَتْنَا سَنَةٌ، فَكَانَ ابْنُ الزُّبَيْرِ يَرْزُقُنَا التَّمْرَ، وَكَانَ ابْنُ عُمَرَ يَمُرُّ بِنَا، فَيَقُولُ: لاَ تَقْرُنُوا؛ فَإِنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ الإِقْرَانِ، إِلاَّ أَنْ يَسْتَأْذِنَ الرَّجُلُ مِنْكُمْ أَخَاهُ."],"takhrij":"متفق عليه: رواه البخاري في الشركة (2490)، ومسلم في الأشربة (2045: 150) كلاهما من طريق شعبة قال: سمعت جبلة بن سحيم قال فذكره. والسياق للبخاري، وزاد مسلم: قال شعبة: لا أرى هذه الكلمة إلا من كلمة ابن عمر، يعني الاستئذان.","grade":"متفق عليه","chapter_ar":"باب لا يأكل أحد تمرتين في لقمة إذا كان بين الشركاء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2489, 2490) and Muslim (2045:150). The wording here is al-Bukhari’s.","chapter_en":"No one should eat two dates in one mouthful when food is jointly shared","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الشركة","group_en":"Collection of reports regarding partnership","part_no":17,"group_no":12,"chapter_no":2,"content":{"translation":{"en":["Jabalah said: We were in Madinah when a time of hardship struck us, and Ibn al-Zubayr used to provide us with dates. Ibn Umar would pass by us and say: “Do not combine two together, for the Prophet ﷺ forbade combining two dates together unless a man seeks permission from his companions.”"]},"buhuth":{"en":["Al-Bukhari also narrated by another route: “The Prophet ﷺ forbade a man from combining two dates together until he seeks permission from his companions.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2489، 2490)، ومسلم (2045: 150)، والسياق للبخاري."},{"num":5655,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عُمَرَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ أَعْتَقَ شِرْكًا لَهُ فِي عَبْدٍ، فَكَانَ لَهُ مَالٌ يَبْلُغُ ثَمَنَ الْعَبْدِ قُوِّم عَلَيْهِ قِيمَةَ العدل، فَأَعْطَى شركائه حِصَصَهُمْ، وَعَتَقَ عَلَيْهِ العبد، وَإِلاَّ فَقَدْ عَتَقَ مِنْهُ مَا عَتَقَ."],"takhrij":"متفق عليه: رواه مالك في العتق والولاء (1) عن نافع، عن عبدالله بن عمر قال: فذكره. ورواه البخاري في العتق (2522)، ومسلم في العتق (1501: 1) كلاهما من طريق مالك به.","grade":"متفق عليه","chapter_ar":"باب الشركة في العبد المملوك، وكيف يقوم إذا أعتق بعض الشركاء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (1), al-Bukhari (2522), and Muslim (1501:1).","chapter_en":"Partnership in a slave, and how he is valued when one partner frees his share","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الشركة","group_en":"Collection of reports regarding partnership","part_no":17,"group_no":12,"chapter_no":3,"content":{"translation":{"en":["Ibn Umar narrated that the Messenger of Allah ﷺ said: “Whoever frees a share of his in a slave, and he has enough wealth to cover the price of the slave, the slave is fairly valued against him, then he gives his partners their shares, and the slave is fully freed on his behalf. Otherwise, only the portion that he freed is freed.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه مالك (1)، والبخاري (2522)، ومسلم (1501: 1)."},{"num":5656,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ أَعْتَقَ شَقِيصًا مِنْ مَمْلُوكِهِ فَعَلَيْهِ خَلاَصُهُ فِي مَالِهِ، فَإِنْ لَمْ يَكُنْ لَهُ مَالٌ قُوِّمَ الْمَمْلُوكُ، قِيمَةَ عَدْلٍ، ثُمَّ اسْتُسْعِيَ غَيْرَ مَشْقُوقٍ عَلَيْهِ."],"takhrij":"متفق عليه: رواه البخاري في الشركة (2492)، ومسلم في العتق (1503) كلاهما من حديث سعيد بن أبي عروبة، عن قتادة، عن النضر بن أنس، عن بشير بن نهيك، عن أبي هريرة قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب الشركة في العبد المملوك، وكيف يقوم إذا أعتق بعض الشركاء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2492) and Muslim (1503).","chapter_en":"Partnership in a slave, and how he is valued when one partner frees his share","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الشركة","group_en":"Collection of reports regarding partnership","part_no":17,"group_no":12,"chapter_no":3,"content":{"translation":{"en":["Abu Hurairah narrated from the Prophet ﷺ that he said: “Whoever frees a share of his slave must complete his emancipation from his own wealth. If he does not have wealth, then the slave is fairly valued and then made to earn the remainder without being overburdened.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2492)، ومسلم (1503)."},{"num":5657,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ قَالَ:  نَحَرْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَامَ الْحُدَيْبِيَةِ الْبَدَنَةَ عَنْ سَبْعَةٍ، وَالْبَقَرَةَ عَنْ سَبْعَةٍ."],"takhrij":"صحيح: رواه مالك في الضحايا (9) عن أبي الزبير المكي، عن جابر بن عبد الله به. ورواه مسلم في الحج (1318: 350) من طريق مالك به مثله.","grade":"صحيح","chapter_ar":"باب الاشتراك في الهدي في الحج","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (9) and Muslim (1318:350).","chapter_en":"Sharing in sacrificial animals during Hajj","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الشركة","group_en":"Collection of reports regarding partnership","part_no":17,"group_no":12,"chapter_no":4,"content":{"translation":{"en":["Jabir said: We sacrificed with the Messenger of Allah ﷺ in the year of al-Hudaybiyah: one camel for seven people, and one cow for seven people."]}},"tuhfa":{},"full":1,"rep":[5334],"tks":"صحيح: رواه مالك (9)، ومسلم (1318: 350)."},{"num":5658,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ قَالَ:  خَرَجْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُهِلِّينَ بِالْحَجِّ، فَأَمَرَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ نَشْتَرِكَ فِي الْإِبِلِ وَالْبَقَرِ، كُلُّ سَبْعَةٍ مِنَّا فِي بَدَنَةٍ."],"takhrij":"صحيح: رواه مسلم في الحج (1318: 351) من طرق عن زهير أبي خيثمة، حدثنا أبو الزبير، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب الاشتراك في الهدي في الحج","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1318:351).","chapter_en":"Sharing in sacrificial animals during Hajj","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الشركة","group_en":"Collection of reports regarding partnership","part_no":17,"group_no":12,"chapter_no":4,"content":{"translation":{"en":["Jabir said: We went out with the Messenger of Allah ﷺ declaring the intention for Hajj, and the Messenger of Allah ﷺ ordered us to share in camels and cows, with every seven of us sharing in one camel."]}},"tuhfa":{},"full":1,"rep":[5335],"tks":"صحيح: رواه مسلم (1318: 351)."},{"num":5659,"demo":false,"sanad":"","matn":["عَنْ أنس بْنِ مَالِكٍ أَنَّ أَبَا بَكْرٍ رَضِيَ اللَّهِ عَنْهُ كَتَبَ لَهُ فَرِيضَةَ الصَّدَقَةِ الَّتِي فَرَضَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: وَمَا كَانَ مِنْ خَلِيطَيْنِ فَإِنَّهُمَا يَتَرَاجَعَانِ بَيْنَهُمَا بِالسَّوِيَّةِ."],"takhrij":"صحيح: رواه البخاري في الشركة (2487) عن محمد بن عبد الله بن المثنى قال: حدثني ثمامة بن عبد الله بن أنس، أن أنسا حدثه، فذكره هكذا مختصرا.","grade":"صحيح","chapter_ar":"باب الشركة في الصدقة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (2487).","chapter_en":"Partnership in zakah livestock","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الشركة","group_en":"Collection of reports regarding partnership","part_no":17,"group_no":12,"chapter_no":5,"content":{"translation":{"en":["Anas ibn Mālik reported: Abū Bakr, may Allah be pleased with him, wrote for him the ordinance of zakat prescribed by the Messenger of Allah ﷺ. It stated: “Whatever belongs to two partners whose livestock are mixed together, they shall settle between themselves equally.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (2487)."},{"num":5660,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ بْنُ عَبْدِ اللَّهِ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ كَانَ لَهُ شَرِيكٌ فِي رَبْعة أَوْ نَخْلٍ فَلَيْسَ لَهُ أَنْ يَبِيعَ حَتَّى يُؤْذِنَ شَرِيكَهُ، فَإِنْ رَضِيَ أَخَذَ، وَإِنْ كَرِهَ تَرَكَ."],"takhrij":"صحيح: رواه مسلم في المساقاة (1608: 133) من حديث زهير أبي خيثمة، وابن جريج، كلاهما عن أبي الزبير، عن جابر. هذا لفظ زهير أبي خيثمة.","grade":"صحيح","chapter_ar":"باب الشركاء في الدور والأراضي وغيرها، وأنه لا يبيع أحد حتى يستأذن شركاءه إذا لم تقسم","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1608:133).","chapter_en":"Partners in houses, lands, and other property, and that one should not sell until consulting the other partners when it has not been divided","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الشركة","group_en":"Collection of reports regarding partnership","part_no":17,"group_no":12,"chapter_no":6,"content":{"translation":{"en":["Jabir ibn Abdullah said: The Messenger of Allah ﷺ said: “Whoever has a partner in a dwelling or in date-palms, it is not lawful for him to sell until he informs his partner. If the partner is pleased, he takes it, and if he dislikes it, he leaves it.”"]},"buhuth":{"en":["In the wording of Ibn Jurayj: “The Messenger of Allah ﷺ ruled with preemption in every undivided partnership in a house or a garden. It is not lawful for him to sell until he informs his partner. If he wishes, he takes it, and if he wishes, he leaves it. If he sells without informing him, then the partner has more right to it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1608: 133)."},{"num":5661,"demo":false,"sanad":"","matn":["عَنْ رُوَيْفِعِ بْنِ ثَابِتٍ الْأَنْصَارِيِّ، أَنَّهُ غَزَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: وَكَانَ أَحَدُنَا يَأْخُذُ النَّاقَةَ عَلَى النِّصْفِ مِمَّا يَغْنَمُ، حَتَّى إِنَّ لِأَحَدِنَا الْقِدْحَ، وَلِلْآخَرِ النَّصْلَ وَالرِّيشَ."],"takhrij":"حسن: رواه الإمام أحمد (16994) عن يحيى بن إسحاق من كتابه قال: أخبرنا ابن لهيعة، عن عياش بن عباس، عن شييم بن بيتان، عن أبي سالم، عن شيبان بن أمية، عن رويفع بن ثابت فذكره.","grade":"حسن","chapter_ar":"باب الشركة في الغنيمة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (16994).","chapter_en":"Partnership in war booty","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الشركة","group_en":"Collection of reports regarding partnership","part_no":17,"group_no":12,"chapter_no":7,"content":{"translation":{"en":["Ruwayfi ibn Thabit al-Ansari said that he went on campaign with the Messenger of Allah ﷺ, and one of us would take a camel in exchange for half of what was taken as booty, so much so that one of us would have the wooden shaft while another would have the metal point and the feathers."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (16994)."},{"num":5662,"demo":false,"sanad":"","matn":["عَنِ النُّعْمَانِ بْنِ بَشِيرٍ قَالَ: سَمِعْتُهُ يَقُولُ:  سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ (وَأَهْوَى النُّعْمَانُ بِإِصْبَعَيْهِ إِلَى أُذُنَيْهِ): إِنَّ الْحَلَالَ بَيِّنٌ، وَإِنَّ الْحَرَامَ بَيِّنٌ، وَبَيْنَهُمَا مُشْتَبِهَاتٌ لَا يَعْلَمُهُنَّ كَثِيرٌ مِنَ النَّاسِ، فَمَنِ اتَّقَى الشُّبُهَاتِ اسْتَبْرَأَ لِدِينِهِ وَعِرْضِهِ، وَمَنْ وَقَعَ فِي الشُّبُهَاتِ وَقَعَ فِي الْحَرَامِ، كَالرَّاعِي يَرْعَى حَوْلَ الْحِمَى يُوشِكُ أَنْ يَرْتَعَ فِيهِ، أَلَا وَإِنَّ لِكُلِّ مَلِكٍ حِمًى، أَلَا وَإِنَّ حِمَى اللهِ مَحَارِمُهُ، أَلَا وَإِنَّ فِي الْجَسَدِ مُضْغَةً، إِذَا صَلَحَتْ صَلَحَ الْجَسَدُ كُلُّهُ، وَإِذَا فَسَدَتْ فَسَدَ الْجَسَدُ كُلُّهُ، أَلَا وَهِيَ الْقَلْبُ."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2051)، ومسلم في المساقاة (1599: 107) كلاهما من طريق الشعبي قال: سمعت النعمان بن بشير يقول فذكره. واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب النهي عن المحرمات والشبهات في البيوع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2051) and Muslim (1599/107). The wording is Muslim’s.","chapter_en":"Prohibition of unlawful and doubtful matters in sales","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":1,"content":{"translation":{"en":["Al-Nu‘man ibn Bashir said: I heard the Messenger of Allah ﷺ say — and al-Nu‘man pointed with his two fingers to his ears —: “The lawful is clear, and the unlawful is clear, and between them are doubtful matters that many people do not know. Whoever avoids the doubtful matters has protected his religion and his honor. Whoever falls into doubtful matters falls into the unlawful, like a shepherd grazing around a protected boundary, soon to graze within it. Indeed, every king has a protected boundary, and indeed the protected boundary of Allah is His prohibitions. Indeed, in the body there is a morsel of flesh: if it is sound, the whole body is sound; and if it is corrupt, the whole body is corrupt. Truly, it is the heart.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (2051)، ومسلم (1599: 107)، واللفظ لمسلم."},{"num":5663,"demo":false,"sanad":"","matn":["عن ابْنِ عَبَّاسٍ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: الْحَلَالُ بَيِّنٌ، وَالْحَرَامُ بَيِّنٌ، وَبَيْنَ ذَلِكَ شُبُهَاتٌ، فَمَنْ أُوقِعَ بِهِنَّ فَهُوَ قَمِنٌ أَنْ يَأْثَمَ، وَمَنِ اجْتَنَبَهُنَّ فَهُوَ أَوْفَرُ لِدِينِهِ، كَمُرْتِعٍ إِلَى جَنْبِ حِمًى، أَوْشَكَ أَنْ يَقَعَ فِيهِ، وَلِكُلِّ مَلِكٍ حِمًى، وَحِمَى اللَّهِ الْحَرَامُ."],"takhrij":"حسن: رواه الطبراني في الكبير (10824)، وابن عساكر في تاريخ دمشق (2358) كلاهما من طرقٍ عن الوليد بن شجاع بن الوليد، حدثني أبي، حدثنا سابق الجزري، أن عمرو بن أبي عمرو مولى المطلب، عن عبد الرحمن بن الحارث، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب النهي عن المحرمات والشبهات في البيوع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Kabir (10/404) and Ibn Asakir in Tarikh Dimashq (1/7).","chapter_en":"Prohibition of unlawful and doubtful matters in sales","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":1,"content":{"translation":{"en":["Ibn Abbas narrated that the Messenger of Allah ﷺ said: “The lawful is clear and the unlawful is clear, and between them are doubtful matters. Whoever falls into them is likely to sin, and whoever avoids them better protects his religion, like one grazing near a protected boundary, soon to fall into it. Every king has a protected boundary, and the protected boundary of Allah is what He has made unlawful.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (10824)، وابن عساكر في تاريخ دمشق (2358)."},{"num":5664,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَيَأْتِيَنَّ عَلَى النَّاسِ زَمَانٌ لاَ يُبَالِي الْمَرْءُ بِمَا أَخَذَ الْمَالَ، أَمِنْ حَلاَلٍ أَمْ مِنْ حَرَامٍ."],"takhrij":"صحيح: رواه البخاري في البيوع (2083) عن آدم، حدثنا ابن أبي ذئب، حدثنا سعيد المقبري، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن المحرمات والشبهات في البيوع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2083).","chapter_en":"Prohibition of unlawful and doubtful matters in sales","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":1,"content":{"translation":{"en":["Abu Hurairah narrated from the Prophet ﷺ that he said: “A time will surely come upon the people when a man will not care how he acquires wealth, whether from lawful sources or unlawful ones.”"]}},"tuhfa":{},"full":1,"rep":[15924],"tks":"صحيح: رواه البخاري (2083)."},{"num":5665,"demo":false,"sanad":"","matn":["عَنْ جَابِر بن عبد الله أَنَّ رَسُولَ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  وَأَصْحَابَهُ مَرُّوا بِامْرَأَةٍ، فَذَبَحَتْ لَهُمْ شَاةً، وَاتَّخَذَتْ لَهُمْ طَعَامًا، فَلَمَّا رَجَعَ، قَالَتْ: يَا رَسُولَ الله إِنَّا اتَّخَذْنَا لَكُمْ طَعَامًا، فَادْخُلُوا، فَكُلُوا. فَدَخَلَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  وَأَصْحَابُهُ، وَكَانُوا لَا يَبْدَؤونَ حَتَّى يَبْتَدِئَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ،َ فَأَخَذَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  لُقْمَةً فَلَمْ يَسْتَطِعْ أَنْ يُسِيغَهَا، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : هَذِهِ شَاةٌ ذُبِحَتْ بِغَيْرِ إِذْنِ أَهْلِهَا. فَقَالَتْ المَرْأَةُ: يَا نَبِيَّ الله إِنَّا لَا نَحْتَشِمُ مِنْ آلِ سَعْدِ بْنِ مُعَاذٍ، وَلَا يَحْتَشِمُونَ مِنَّا، نَأْخُذُ مِنْهُمْ، وَيَأْخُذُونَ منّا."],"takhrij":"صحيح: رواه أحمد (14785)، والحاكم (7579) كلاهما من طريق حماد بن سلمة، عن حميد، عن أبي المتوكل، عن جابر قال: فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن المحرمات والشبهات في البيوع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (14785) and al-Ḥākim (7579).","chapter_en":"Prohibition of unlawful and doubtful matters in sales","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":1,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh reported: The Messenger of Allah ﷺ and his Companions passed by a woman. She slaughtered a sheep for them and prepared food. When they returned, she said: “O Messenger of Allah ﷺ, we have prepared food for you, so come in and eat.” The Messenger of Allah ﷺ and his Companions entered. They would not begin eating until the Prophet ﷺ began. The Prophet ﷺ took a morsel but was unable to swallow it. He said: “This sheep was slaughtered without the permission of its owners.” The woman said: “O Prophet of Allah, there is no formality between us and the family of Saʿd ibn Muʿādh, nor between them and us. We take from them, and they take from us.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (14785)، والحاكم (7579)."},{"num":5666,"demo":false,"sanad":"","matn":["عن رجلٍ مِنْ الْأَنْصَارِ أَخْبَرَهُ قَالَ: خَرَجْنَا مَعَ رَسُولِ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  فِي جِنَازَةٍ، فَلَمَّا رَجَعْنَا لَقِيَنَا دَاعِي امْرَأَةٍ مِنْ قُرَيْشٍ، فَقَالَ: يَا رَسُولَ الله، إِنَّ فُلَانَةَ تَدْعُوكَ وَمَنْ مَعَكَ إِلَى طَعَامٍ، فَانْصَرَفَ فَانْصَرَفْنَا مَعَهُ، فَجَلَسْنَا مَجَالِسَ الْغِلْمَانِ مِنْ آبَائِهِمْ بَيْنَ أَيْدِيهِمْ، ثُمَّ جِيءَ بِالطَّعَـــامِ، فَوَضَعَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  يَدَهُ، وَوَضَعَ الْقَوْمُ أَيْدِيَهُمْ، فَفَطِنَ لَهُ الْقَوْمُ، وَهُوَ يَلُوكُ لُقْمَتَهُ لَا يُجِيزُهَا، فَرَفَعُوا أَيْدِيَهُمْ، وَغَفَلُوا عَنَّا، ثُمَّ ذَكَرُوا فَأَخَذُوا بِأَيْدِينَا، فَجَعَلَ الرَّجُلُ يَضْرِبُ اللُّقْمَةَ بِيَدِهِ حَتَّى تَسْقُطَ، ثُمَّ أَمْسَكُوا بِأَيْدِينَا يَنْظُرُونَ مَا يَصْنَعُ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، فَلَفَظَهَا فَأَلْقَاهَا، فَقَالَ: أَجِدُ لحْمَ شَاةٍ أُخِذَتْ بِغَيْرِ إِذْنِ أَهْلِهَا.","فَقَامَتْ الْمَرْأَةُ فَقَالَتْ: يَا رَسُولَ الله إِنَّهُ كَانَ فِي نَفْسِي أَنْ أَجْمَعَكَ وَمَنْ مَعَكَ عَلَى طَعَامٍ، فَأَرْسَلْتُ إِلَى الْبَقِيعِ فَلَمْ أَجِدْ شَاةً تُبَاعُ، وَكَانَ عَامِرُ بْنُ أَبِي وَقَّاصٍ ابْتَاعَ شَاةً أَمْسِ مِنْ الْبَقِيعِ، فَأَرْسَلْتُ إِلَيْهِ أَنْ ابْتُغِيَ لِي شَاةٌ فِي الْبَقِيعِ فَلَمْ تُوجَدْ، فَذُكِرَ لِي أَنَّكَ اشْتَرَيْتَ شَاةً فَأَرْسِلْ بِهَا إِلَيَّ، فَلَمْ يَجِدْهُ الرَّسُولُ، وَوَجَدَ أَهْلَهُ، فَدَفَعُوهَا إِلَى رَسُولِي، فَقَالَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : أَطْعِمُوهَا الْأُسَارَى."],"takhrij":"حسن: رواه أبو داود (3332)، وأحمد (22509) عن معاوية بن عمرو، حدثنا أبو إسحاق، عن زائدة، عن عاصم بن كليب، عن أبيه ،أن رجلا من الأنصار أخبره قال: فذكره.","grade":"حسن","chapter_ar":"باب النهي عن المحرمات والشبهات في البيوع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3332) and Ahmad (22509). This wording is Ahmad’s.","chapter_en":"Prohibition of unlawful and doubtful matters in sales","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":1,"content":{"translation":{"en":["A man from the Ansar reported: We went out with the Messenger of Allah ﷺ in a funeral procession. When we returned, the messenger of a woman from Quraysh met us and said: “O Messenger of Allah ﷺ, so-and-so invites you and those with you to a meal.” So he turned aside, and we turned aside with him. We sat as children sit before their fathers. Then the food was brought. The Messenger of Allah ﷺ placed his hand in it, and the people also put their hands in it. Then the people noticed that he was chewing his morsel without being able to swallow it. So they withdrew their hands, though they forgot about us at first, then remembered and took our hands back. The man began knocking the morsel from his hand until it fell, and they kept holding our hands, watching what the Messenger of Allah ﷺ would do. Then he spat it out and said: “I find this to be the meat of a sheep taken without the permission of its owners.” The woman then stood and said: “O Messenger of Allah ﷺ, I wished to gather you and those with you for a meal, so I sent to al-Baqi, but I did not find a sheep for sale. Amir ibn Abi Waqqas had bought a sheep yesterday from al-Baqi, so I sent to him that he should buy one for me from al-Baqi, but none was found. Then I was told that you had bought a sheep, so I sent for it, but the messenger did not find him; he found his family, and they handed it to my messenger.” The Messenger of Allah ﷺ said: “Feed it to the prisoners.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3332)، وأحمد (22509)، والسياق لأحمد."},{"num":5667,"demo":false,"sanad":"","matn":["عن كاتب الْمُغِيرَةِ بن شُعْبَةَ قَالَ: كَتَبَ مُعَاوِيَةُ إِلَى الْمُغِيرَةِ بْنِ شُعْبَةَ أَنِ اكْتُبْ، إِلَىَّ بِشَىْءٍ سَمِعْتَهُ مِنَ النَّبِيِّ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَكَتَبَ إِلَيْهِ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّ اللَّهَ كَرِهَ لَكُمْ ثَلاَثًا: قِيلَ وَقَالَ، وَإِضَاعَةَ الْمَالِ، وَكَثْرَةَ السُّؤَالِ."],"takhrij":"متفق عليه: رواه البخاري في الزكاة (1477)، ومسلم في الأقضية (593: 13) كلاهما من طريق إسماعيل بن علية، عن خالد الحذاء، حدثني ابن أشوع، عن الشعبي، حدثني كاتب المغيرة بن شعبة فذكره.","grade":"متفق عليه","chapter_ar":"باب النهي عن إضاعة المال","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1477) and Muslim (593/13).","chapter_en":"Prohibition of wasting wealth","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":2,"content":{"translation":{"en":["The scribe of al-Mughirah ibn Shu‘bah said: Muawiyah wrote to al-Mughirah ibn Shu‘bah: “Write to me something you heard from the Prophet ﷺ.” So he wrote to him: I heard the Prophet ﷺ say: “Allah dislikes for you three things: gossiping back and forth, wasting wealth, and asking too much.”"]},"buhuth":{"en":["In another wording: “Allah has made three things unlawful and forbidden three things: He made unlawful disobedience to parents, burying daughters alive, and saying ‘don’t give’ while demanding ‘give me.’ And He forbade three things: gossiping back and forth, excessive questioning, and wasting wealth.” In another wording: “withholding and demanding.”","The phrase means refusing to give what one is obliged to give, while demanding what one has no right to demand."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1477)، ومسلم (593: 13)."},{"num":5668,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  إِنَّ اللَّهَ يَرْضَى لَكُمْ ثَلَاثًا، وَيَكْرَهُ لَكُمْ ثَلَاثًا؛ فَيَرْضَى لَكُمْ أَنْ تَعْبُدُوهُ، وَلَا تُشْرِكُوا بِهِ شَيْئًا، وَأَنْ تَعْتَصِمُوا بِحَبْلِ اللهِ جَمِيعًا، وَلَا تَفَرَّقُوا، وَيَكْرَهُ لَكُمْ قِيلَ وَقَالَ، وَكَثْرَةَ السُّؤَالِ، وَإِضَاعَةَ الْمَالِ."],"takhrij":"صحيح: رواه مسلم في الأقضية (1715) عن زهير بن حرب، حدثنا جرير، عن سهيل، عن أبيه، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن إضاعة المال","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1715).","chapter_en":"Prohibition of wasting wealth","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":2,"content":{"translation":{"en":["Abu Hurairah said: The Messenger of Allah ﷺ said: “Allah is pleased for you with three things and dislikes for you three things. He is pleased that you worship Him and associate nothing with Him, that you hold firmly together to the rope of Allah and do not become divided. And He dislikes for you gossiping back and forth, asking too much, and wasting wealth.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1715)."},{"num":5669,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: لَا ضَرَرَ، وَلَا ضِرَارَ."],"takhrij":"حسن: رواه مالك في الأقضية (33) عن عمرو بن يحيى المازني، عن أبيه، أن رسول الله صلى الله عليه وسلم  قال: فذكره هكذا مرسلاً.","grade":"حسن","chapter_ar":"باب لا ضررَ ولا ضِرَارَ","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Malik in al-Aqdiyah (33), al-Daraqutni (3079), al-Hakim (2345), and al-Bayhaqi (6/69).","chapter_en":"No harm and no reciprocating harm","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":3,"content":{"translation":{"en":["Abu Sa‘id al-Khudri said: The Messenger of Allah ﷺ said: “There should be neither harm nor reciprocating harm.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه مالك (33)، والدارقطني (3079)، والحاكم (2345)، والبيهقي (11384)."},{"num":5670,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ  أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَرَّ عَلَى صُبْرَةِ طَعَامٍ، فَأَدْخَلَ يَدَهُ فِيهَا، فَنَالَتْ أَصَابِعُهُ بَلَلًا، فَقَالَ: مَا هَذَا يَا صَاحِبَ الطَّعَامِ؟ قَالَ: أَصَابَتْهُ السَّمَاءُ، يَا رَسُولَ اللَّهِ. قَالَ: أَفَلَا جَعَلْتَهُ فَوْقَ الطَّعَامِ كَيْ يَرَاهُ النَّاسُ؟ مَنْ غَشَّ فَلَيْسَ مِنِّي."],"takhrij":"صحيح: رواه مسلم في الإيمان (102) من طرق عن إسماعيل بن جعفر قال: أخبرني العلاء، عن أبيه، عن أبي هريرة فذكر مثله.","grade":"صحيح","chapter_ar":"باب تحريم الغش في البيوع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (102).","chapter_en":"The prohibition of deceit in sales","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":4,"content":{"translation":{"en":["Abu Hurairah narrated that the Messenger of Allah ﷺ passed by a heap of food and put his hand into it. His fingers touched dampness, so he said: “What is this, O owner of the food?” He said: “Rain fell on it, O Messenger of Allah ﷺ.” He said: “Why did you not put it on top of the food so people could see it? Whoever deceives is not from me.”"]},"buhuth":{"en":["Ahmad (7292) and Abu Dawud (3492) also narrated it, and in one wording: he was inspired to put his hand into it, and when he found it wet, the Messenger of Allah ﷺ said: “He is not from us who deceives.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (102)."},{"num":5671,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  مَنْ حَمَلَ عَلَيْنَا السِّلَاحَ فَلَيْسَ مِنَّا، وَمَنْ غَشَّنَا فَلَيْسَ مِنَّا."],"takhrij":"صحيح: رواه مسلم في الإيمان (101) من طريق يعقوب بن عبد الرحمن القاري، وابن أبي حازم، كلاهما عن سهيل بن أبي صالح، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب تحريم الغش في البيوع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (101).","chapter_en":"The prohibition of deceit in sales","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":4,"content":{"translation":{"en":["Abu Hurairah narrated that the Messenger of Allah ﷺ said: “Whoever bears arms against us is not from us, and whoever deceives us is not from us.”"]}},"tuhfa":{},"full":1,"rep":[14117],"tks":"صحيح: رواه مسلم (101)."},{"num":5672,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ بن عَبَّاسٍ قَالَ: قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ غَشَّنَا فَلَيْسَ مِنَّا، وَمَنْ رَمَانَا بِالنَّبْلِ فَلَيْسَ مِنَّا."],"takhrij":"حسن: رواه الطبراني في الكبير (11553) عن علي بن عبد العزيز، ثنا سعيد بن منصور، عن الدراوردي، عن ثور بن زيد، عن عكرمة، عن عبـدالله بن عبـاس فذكره.","grade":"حسن","chapter_ar":"باب تحريم الغش في البيوع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Kabir (11/221).","chapter_en":"The prohibition of deceit in sales","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":4,"content":{"translation":{"en":["Ibn Abbas said: The Messenger of Allah ﷺ said: “Whoever deceives us is not from us, and whoever attacks us at night is not from us.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (11553)."},{"num":5673,"demo":false,"sanad":"","matn":["عَنْ عُقْبَةَ بْنِ عَامِرٍ، قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: الْمُسْلِمُ أَخُو الْمُسْلِمِ، وَلاَ يَحِلُّ لِمُسْلِمٍ بَاعَ مِنْ أَخِيهِ بَيْعًا فِيهِ عَيْبٌ إِلاَّ بَيَّنَهُ لَهُ."],"takhrij":"حسن: رواه ابن ماجه (2246) عن محمد بن بشار قال: حدثنا وهب بن جرير قال: حدثنا أبي قال: سمعت يحيى بن أيوب يحدث عن يزيد بن أبي حبيب، عن عبد الرحمن بن شماسة، عن عقبة بن عامر فذكره.","grade":"حسن","chapter_ar":"باب تحريم الغش في البيوع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2246), al-Hakim (2152), and al-Bayhaqi (5/320).","chapter_en":"The prohibition of deceit in sales","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":4,"content":{"translation":{"en":["Uqbah ibn Amir said: I heard the Messenger of Allah ﷺ say: “A Muslim is the brother of a Muslim, and it is not lawful for a Muslim who sells something to his brother while it has a defect except that he must make it clear to him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (2246)، والحاكم (2152)، والبيهقي (10734)."},{"num":5674,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ غَشَّنَا فَلَيْسَ مِنَّا."],"takhrij":"حسن: رواه البزار –الكشف (1256)- عن عمرو بن علي وبشر بن آدم قالا: ثنا أبو علي الحنفي، ثنا هارون الشامي، عن الحكم، عن إبراهيم، عن الأسود، عن عائشة فذكره.","grade":"حسن","chapter_ar":"باب تحريم الغش في البيوع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzar in Kashf al-Astar (1256).","chapter_en":"The prohibition of deceit in sales","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":4,"content":{"translation":{"en":["Aishah narrated that the Prophet ﷺ said: “Whoever deceives us is not from us.”"]},"buhuth":{"en":["As for the saying, “Whoever deceives us is not from us,” it means that he is not following our way and guidance, which are truthfulness and faithfulness."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار - كشف الأستار (1256)."},{"num":5675,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: الْحَلِفُ مُنَفِّقَةٌ لِلسِّلْعَةِ مُمْحِقَةٌ لِلْبَرَكَةِ."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2087)، ومسلم في المساقاة (1606) من طريق يونس، عن ابن شهاب، عن ابن المسيب أن أبا هريرة قال فذكره. واللفظ للبخاري. ولفظ مسلم ممحقة للربح.","grade":"متفق عليه","chapter_ar":"باب النهي عن الحلف في البيع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2087) and Muslim (1606). The wording is al-Bukhari’s.","chapter_en":"Prohibition of swearing in sales","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":5,"content":{"translation":{"en":["Abu Hurairah said: I heard the Messenger of Allah ﷺ say: “Swearing may make the goods sell, but it wipes out the blessing.”"]},"buhuth":{"en":["The word means that it causes the goods to move and sell, the opposite of stagnation."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2087)، ومسلم (1606)، واللفظ للبخاري."},{"num":5676,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ يَقُولُ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ثَلاَثَةٌ لاَ يَنْظُرُ اللَّهُ إِلَيْهِمْ يَوْمَ الْقِيَامَةِ وَلاَ يُزَكِّيهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ: رَجُلٌ كَانَ لَهُ فَضْلُ مَاءٍ بِالطَّرِيقِ فَمَنَعَهُ مِنِ ابْنِ السَّبِيلِ، وَرَجُلٌ بَايَعَ إِمَامًا لاَ يُبَايِعُهُ إِلاَّ لِدُنْيَا، فَإِنْ أَعْطَاهُ مِنْهَا رَضِيَ، وَإِنْ لَمْ يُعْطِهِ مِنْهَا سَخِطَ، وَرَجُلٌ أَقَامَ سِلْعَتَهُ بَعْدَ الْعَصْرِ، فَقَالَ: وَاللَّهِ الَّذِي لاَ إِلَهَ غَيْرُهُ لَقَدْ أَعْطَيْتُ بِهَا كَذَا وَكَذَا فَصَدَّقَهُ رَجُلٌ ثُمَّ قَرَأَ هَذِهِ الآيَةَ ﴿إِنَّ الَّذِينَ يَشْتَرُونَ بِعَهْدِ اللَّهِ وَأَيْمَانِهِمْ ثَمَنًا قَلِيلًا﴾ [سورة آلِ عِمْرَانَ: 77]."],"takhrij":"متفق عليه: رواه البخاري في المساقاة (2358) عن موسى بن إسماعيل، حدثنا عبدالواحد بن زياد، عن الأعمش قال: سمعت أبا صالح يقول: سمعت أبا هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب النهي عن الحلف في البيع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2358) and Muslim (108).","chapter_en":"Prohibition of swearing in sales","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":5,"content":{"translation":{"en":["Abu Hurairah said: The Messenger of Allah ﷺ said: “There are three whom Allah will not look at on the Day of Resurrection, nor purify them, and they will have a painful punishment: a man who has excess water on the road but withholds it from a traveler; a man who gives allegiance to a leader only for worldly gain — if he is given something from it he is pleased, and if he is not given he is angered; and a man who displays his goods after the Asr prayer and says: ‘By Allah, besides whom there is no god, I was offered such-and-such for it,’ and a man believes him.” Then he recited the verse: “Indeed, those who trade away the covenant of Allah and their oaths for a small price…” [Al Imran: 77]"]}},"tuhfa":{},"full":1,"dr":1,"rep":[410],"tks":"متفق عليه: رواه البخاري (2358)، ومسلم (108)."},{"num":5677,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَرْبَعَةٌ يُبْغِضُهُمُ اللَّهُ عَزَّ وَجَلَّ: الْبَيَّاعُ الْحَلاَّفُ، وَالْفَقِيرُ الْمُخْتَالُ، وَالشَّيْخُ الزَّانِي، وَالإِمَامُ الْجَائِرُ."],"takhrij":"صحيح: رواه النسائي (2576) عن أبي داود قال: حدثنا عارم قال: حدثنا حماد قال: حدثنا عبيد الله بن عمر، عن سعيد المقبري، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن الحلف في البيع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasai (2576).","chapter_en":"Prohibition of swearing in sales","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":5,"content":{"translation":{"en":["Abu Hurairah narrated that the Messenger of Allah ﷺ said: “Allah, Mighty and Majestic, hates four people: the merchant who swears frequently, the arrogant poor man, the old man who commits fornication, and the unjust ruler.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (2576)."},{"num":5678,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  ثَلَاثَةٌ لَا يُكَلِّمُهُمُ اللَّهُ يَوْمَ الْقِيَامَةِ، وَلَا يَنْظُرُ إِلَيْهِمْ، وَلَا يُزَكِّيهِمْ، وَلَهُمْ عَذَابٌ أَلِيمٌ. قَالَ: فَقَرَأَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثَلَاثَ مِرَارٍ. قَالَ أَبُو ذَرٍّ: خَابُوا وَخَسِرُوا، مَنْ هُمْ يَا رَسُولَ اللَّهِ؟ قَالَ: الْمُسْبِلُ، وَالْمَنَّانُ، وَالْمُنَفِّقُ سِلْعَتَهُ بِالْحَلِفِ الْكَاذِبِ."],"takhrij":"صحيح: رواه مسلم في الإيمان (106) من طرق عن محمد بن جعفر، عن شعبة، عن علي بن مدرك، عن أبي زرعة، عن خرشة بن الحر، عن أبي ذر فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن الحلف في البيع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (106).","chapter_en":"Prohibition of swearing in sales","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":5,"content":{"translation":{"en":["Abu Dharr narrated from the Prophet ﷺ that he said: “There are three whom Allah will not speak to on the Day of Resurrection, nor look at, nor purify, and they will have a painful punishment.” The Messenger of Allah ﷺ repeated it three times. Abu Dharr said: “They are ruined and lost — who are they, O Messenger of Allah ﷺ?” He said: “The one who lets his garment hang below his ankles, the one who reminds others of his favors, and the one who sells his goods by false oaths.”"]},"buhuth":{"en":["In another wording: “the one who promotes his goods by wicked oaths, and the one who lets his garment hang low.”","Here it means the one who makes his goods sell and circulate, the opposite of goods remaining unsold."]}},"tuhfa":{},"full":1,"dr":1,"rep":[412,7074,15375],"tks":"صحيح: رواه مسلم (106)."},{"num":5679,"demo":false,"sanad":"","matn":["عَنْ مُطَرِّفِ بْنِ عَبْدِ اللَّهِ بْنِ الشِّخِّيرِ، قَالَ: بَلَغَنِي عَنْ أَبِي ذَرٍّ، حَدِيثٌ، فَكُنْتُ أُحِبُّ أَنْ أَلْقَاهُ، فَلَقِيتُهُ، فَقُلْتُ لَهُ: يَا أَبَا ذَرٍّ، بَلَغَنِي عَنْكَ حَدِيثٌ، فَكُنْتُ أُحِبُّ أَنْ أَلْقَاكَ فَأَسْأَلَكَ عَنْهُ، فَقَالَ: قَدْ لَقِيتَ فَاسْأَلْ. قَالَ: قُلْتُ: بَلَغَنِي أَنَّكَ تَقُولُ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: ثَلَاثَةٌ يُحِبُّهُمُ اللَّهُ، وَثَلَاثَةٌ يُبْغِضُهُمُ اللَّهُ قَالَ: نَعَمْ، فَمَا أَخَالُنِي أَكْذِبُ عَلَى خَلِيلِي مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثَلَاثًا يَقُولُهَا.","قَالَ: قُلْتُ: مَنِ الثَّلَاثَةُ الَّذِينَ يُحِبُّهُمُ اللهُ عز وجل؟ قَالَ: رَجُلٌ غَزَا فِي سَبِيلِ اللهِ، فَلَقِيَ الْعَدُوَّ مُجَاهِدًا مُحْتَسِبًا، فَقَاتَلَ حَتَّى قُتِلَ، وَأَنْتُمْ تَجِدُونَ فِي كِتَابِ اللهِ عز وجل ﴿إِنَّ اللهَ يُحِبُّ الَّذِينَ يُقَاتِلُونَ فِي سَبِيلِهِ صَفًّا﴾ [سورة الصف: 4]،4]، وَرَجُلٌ لَهُ جَارٌ يُؤْذِيهِ، فَيَصْبِرُ عَلَى أَذَاهُ، وَيَحْتَسِبُهُ حَتَّى يَكْفِيَهُ اللهُ إِيَّاهُ بِمَوْتٍ أَوْ حَيَاةٍ، وَرَجُلٌ يَكُونُ مَعَ قَوْمٍ فَيَسِيرُونَ حَتَّى يَشُقَّ عَلَيْهِمُ الْكَرَى أو النعاس، فَيَنْزِلُونَ فِي آخِرِ اللَّيْلِ، فَيَقُومُ إِلَى وُضُوئِهِ وَصَلَاتِهِ.","قَالَ: قُلْتُ: مَنِ الثَّلَاثَةُ الَّذِينَ يُبْغِضُهُمُ اللهُ؟ قَالَ: الْفَخُورُ الْمُخْتَالُ، وَأَنْتُمْ تَجِدُونَ فِي كِتَابِ اللهِ عز وجل: ﴿إِنَّ اللهَ لَا يُحِبُّ كُلَّ مُخْتَالٍ فَخُورٍ﴾ [سورة لقمان: 18]،18]، وَالْبَخِيلُ الْمَنَّانُ، وَالتَّاجِرُ –أوالبياع- الْحَلَّافُ.","قَالَ: قُلْتُ: يَا أَبَا ذَرٍّ، مَا الْمَالُ؟ قَالَ: فِرْقٌ لَنَا وَذَوْدٌ -يَعْنِي بِالْفِرْقِ غَنَمًا يَسِيرَةً-. قَالَ: قُلْتُ: لَسْتُ عَنْ هَذَا أَسْأَلُ، إِنَّمَا أَسْأَلُكَ عَنْ صَامِتِ الْمَالِ. قَالَ: مَا أَصْبَحَ لَا أَمْسَى، وَمَا أَمْسَى لَا أَصْبَحَ. قَالَ: قُلْتُ: يَا أَبَا ذَرٍّ، مَا لَكَ وَلِإِخْوَتِكَ قُرَيْشٍ؟ قَالَ: وَاللهِ لَا أَسْأَلُهُمْ دُنْيَا، وَلَا أَسْتَفْتِيهِمْ عَنْ دِينِ اللهِ حَتَّى أَلْقَى اللهَ وَرَسُولَهُ. ثَلَاثًا يَقُولُهَا."],"takhrij":"صحيح: رواه أحمد (21530)، والطبراني في الكبير (2/161)، والحاكم (2/88-89)، والبيهقي (9/160) كلهم من طريق الأسود بن شيبان، عن يزيد بن أبي العلاء، عن مطرف بن عبد الله بن الشخير فذكره. واللفظ لأحمد.","grade":"صحيح","chapter_ar":"باب النهي عن الحلف في البيع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (21530), al-Tabarani in al-Kabir (2/161), and al-Hakim (2/88–89). The wording is Ahmad’s.","chapter_en":"Prohibition of swearing in sales","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":5,"content":{"translation":{"en":["Mutarrif ibn Abdullah ibn al-Shikhkhir said: A hadith from Abu Dharr reached me, and I wished to meet him. When I met him, I said: “O Abu Dharr, a hadith from you reached me, and I wanted to meet you to ask you about it.” He said: “You have met me, so ask.” I said: “I heard that you say: I heard the Messenger of Allah ﷺ say, ‘Three are loved by Allah, and three are hated by Allah.’” He said: “Yes, and I do not think I would lie about my beloved Muhammad ﷺ” — repeating that three times. I said: “Who are the three whom Allah loves?” He said: “A man who goes out fighting in the way of Allah, meets the enemy striving and seeking reward, and fights until he is killed — and you find in the Book of Allah: ‘Indeed, Allah loves those who fight in His cause in ranks’ [al-Saff: 4]; a man who has a neighbor who harms him, yet he remains patient over his harm seeking reward until Allah relieves him of him, whether by death or by life; and a man who is traveling with people until drowsiness and sleep become hard on them, so they camp at the end of the night, and he gets up for his ablution and prayer.”","I said: “Who are the three whom Allah hates?” He said: “The boastful arrogant one — and you find in the Book of Allah: ‘Indeed, Allah does not love every self-deluded boaster’ [Luqman: 18] — the stingy one who reminds others of his favors, and the trader — or seller — who swears frequently.” I said: “O Abu Dharr, what is wealth?” He said: “A small flock and a few camels for us,” meaning a little livestock. I said: “That is not what I mean; I mean stored wealth.” He said: “What is with me in the morning does not remain till evening, and what is with me in the evening does not remain till morning.” I said: “O Abu Dharr, what is there between you and your brothers from Quraysh?” He said: “By Allah, I do not ask them for worldly things, nor do I seek legal opinions from them in the religion of Allah until I meet Allah and His Messenger.” He said that three times."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (21530)، والطبراني في الكبير (2/161)، والحاكم (2/88-89)، واللفظ لأحمد."},{"num":5680,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى أَنَّ رَجُلاً أَقَامَ سِلْعَةً وَهُوَ فِي السُّوقِ، فَحَلَفَ بِاللَّهِ لَقَدْ أَعْطَى بِهَا مَا لَمْ يُعْطَ؛ لِيُوقِعَ فِيهَا رَجُلاً مِنَ الْمُسْلِمِينَ فَنَزَلَتْ: ﴿إِنَّ الَّذِينَ يَشْتَرُونَ بِعَهْدِ اللَّهِ وَأَيْمَانِهِمْ ثَمَنًا قَلِيلًا﴾ [سورة آلِ عِمْرَانَ: 77]."],"takhrij":"صحيح: رواه البخاري في البيوع (2088) عن عمرو بن محمد، حدثنا هشيم، أخبرنا العوام، عن إبراهيم بن عبد الرحمن، عن عبد الله بن أبي أوفى.","grade":"صحيح","chapter_ar":"باب النهي عن الحلف في البيع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2088).","chapter_en":"Prohibition of swearing in sales","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":5,"content":{"translation":{"en":["Abdullah ibn Abi Awfa said: A man displayed goods in the market and swore by Allah that he had been offered for them what he had not actually been offered, intending to deceive a Muslim into buying them. Then the verse was revealed: “Indeed, those who exchange the covenant of Allah and their oaths for a small price…” [Al Imran: 77]"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (2088)."},{"num":5681,"demo":false,"sanad":"","matn":["عَنْ أَبِي قَتَادَةَ الْأَنْصَارِيِّ أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ:  إِيَّاكُمْ وَكَثْرَةَ الْحَلِفِ فِي الْبَيْعِ، فَإِنَّهُ يُنَفِّقُ، ثُمَّ يَمْحَقُ."],"takhrij":"صحيح: رواه مسلم في المساقاة (1607) من طريق أبي أسامة (وهو حماد بن أسامة)، عن الوليد بن كثير، عن معبد بن كعب بن مالك، عن أبي قتادة الأنصاري فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن الحلف في البيع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1607).","chapter_en":"Prohibition of swearing in sales","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":5,"content":{"translation":{"en":["Abū Qatādah al-Anṣārī reported that he heard the Messenger of Allah ﷺ say: “Beware of excessive swearing in transactions, for it may make the merchandise sell, but afterward it erases the blessing.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1607)."},{"num":5682,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ الرَّحْمَنِ بن شِبْلٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ التُّجَّارَ هُمُ الْفُجَّارُ. قِيلَ: يَا رَسُولَ اللَّهِ، أَوْ لَيْسَ قَدْ أَحَلَّ اللَّهُ الْبَيْعَ؟ قَالَ: بَلَى، وَلَكِنَّهُمْ يُحَدِّثُونَ فَيَكْذِبُونَ، وَيَحْلِفُونَ فيأثمون."],"takhrij":"صحيح: رواه أحمد (15530)، والحاكم (2146)، وعنه البيهقي في كتاب الآداب (1100)، وشعب الإيمان (4/218) من طريق هشام الدستوائي قال: حدثني يحيى بن أبي كثير، عن أبي راشد الحبراني قال: قال عبد الرحمن بن شبل فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن الحلف في البيع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (15530), al-Hakim (2/6–7), and al-Bayhaqi in Shu‘ab al-Iman (4/218).","chapter_en":"Prohibition of swearing in sales","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":5,"content":{"translation":{"en":["Abd al-Rahman ibn Shibl reported that the Messenger of Allah ﷺ said: “Merchants are the sinful ones.” It was said: “Messenger of Allah ﷺ, has Allah not made trade lawful?” He said: “Yes, but they speak and lie, and they swear oaths and thereby sin.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (15530)، والحاكم (2146)، والبيهقي في شعب الإيمان (1100)."},{"num":5683,"demo":false,"sanad":"","matn":["عَنْ سَلْمَانَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ثَلَاثَةٌ لَا يَنْظُرُ اللَّهُ إِلَيْهِمْ يَوْمَ الْقِيَامَةِ: أُشَيْمِطٌ زَانٍ، وَعَائِلٌ مُسْتَكْبِرٌ، وَرَجُلٌ جَعَلَ اللَّهُ بِضَاعَتَهُ لَا يَشْتَرِي إِلَّا بِيَمِينِهِ، وَلَا يَبِيعُ إِلَّا بِيَمِينِهِ."],"takhrij":"صحيح: رواه الطبراني في المعجم الكبير (6111) عن محمد بن عبدالله الحضرمي، ثنا سعيد بن عمرو الأشعثي، ثنا حفص بن غياث، عن عاصم الأحول، عن أبي عثمان (النهدي)، عن سلمان فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب النهي عن الحلف في البيع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tabarani in al-Mu‘jam al-Kabir (6/301).","chapter_en":"Prohibition of swearing in sales","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":5,"content":{"translation":{"en":["Salman reported that the Messenger of Allah ﷺ said: “There are three to whom Allah will not look on the Day of Resurrection: an old man who commits fornication, a poor man who is arrogant, and a man whose trade is such that he does not buy except by swearing an oath and does not sell except by swearing an oath.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الطبراني في الكبير (6111)."},{"num":5684,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، قَالَ: مَرَّ أَعْرَابِيٌّ بِشَاةٍ، فَقُلْتُ: تَبِيعُنِيهَا بِثَلَاثَةِ دَرَاهِمَ؟ فقَالَ: لَا وَاللهِ، ثُمَّ بَاعَنِيهَا، فَذَكَرْتُ ذَلِكَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: بَاعَ آخِرَتَهُ بِدُنْيَاهُ."],"takhrij":"حسن: رواه ابن حبان (4909) عن عبد الله بن صالح البخاري ببغداد، قال: حدثنا يعقوب بن حُميد بن كاسب، قال: حدثنا ابن أبي فديك، عن ربيعة بن عثمان، عن محمد بن المنكدر، عن ربيعة بن عبد الله بن الهدير، عن أبي سعيد الخدري، فذكره.","grade":"حسن","chapter_ar":"باب النهي عن الحلف في البيع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Hibban (4909).","chapter_en":"Prohibition of swearing in sales","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":5,"content":{"translation":{"en":["Abu Sa‘id reported: A desert Arab passed by with a sheep, and I said, “Will you sell it to me for three dirhams?” He said, “No, by Allah,” then he sold it to me. I mentioned that to the Messenger of Allah ﷺ, and he said: “He sold his Hereafter for his worldly gain.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن حبان (4909)."},{"num":5685,"demo":false,"sanad":"","matn":["عَنْ قَيْسِ بْنِ أَبِي غَرَزَةَ، قَالَ: كُنَّا فِي عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نُسَمَّى السَّمَاسِرَةَ، فَمَرَّ بِنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَسَمَّانَا بِاسْمٍ هُوَ أَحْسَنُ، مِنْهُ فَقَالَ: يَا مَعْشَرَ التُّجَّارِ، إِنَّ الْبَيْعَ يَحْضُرُهُ اللَّغْوُ وَالْحَلِفُ فَشُوبُوهُ بِالصَّدَقَةِ."],"takhrij":"صحيح: رواه أبو داود (3326)، والترمذي (1208)، والنسائي (3797)، وابن ماجه (2145)، وأحمد (16134) كلهم من طرق عن أبي وائل شقيق بن سلمة، عن قيس بن أبي غرزة فذكره.","grade":"صحيح","chapter_ar":"باب التوقِّي في التجارة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3326), al-Tirmidhi (1208), al-Nasa’i (3797), Ibn Majah (2145), and Ahmad (16134).","chapter_en":"Caution and restraint in trade","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":6,"content":{"translation":{"en":["Qays ibn Abi Gharazah said: During the time of the Messenger of Allah ﷺ, we were called brokers. The Messenger of Allah ﷺ passed by us and gave us a better name. He said: “O merchants, trade is attended by idle talk and oaths, so mix it with charity.”"]},"buhuth":{"en":["His statement, “We were called brokers,” means intermediaries in trade. And his statement, “Mix it with charity,” means: accompany your trade with charity so that it may expiate what may occur in it of idle speech, swearing, and similar matters."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (3326)، والترمذي (1208)، والنسائي (3797)، وابن ماجه (2145)، وأحمد (16134)."},{"num":5686,"demo":false,"sanad":"","matn":["عَنِ الْبَرَاءِ بْنِ عَازِبٍ، قَالَ: أَتَانَا رَسُولُ اللهِ ﷺ إِلَى الْبَقِيعِ، فَقَالَ: يَا مَعْشَرَ التُّجَّارِ حَتَّى إِذَا اشْرَأَبُّوا، قَالَ: إِنَّ التُّجَّارَ يُحْشَرُونَ يَوْمَ الْقِيَامَةِ فُجَّارًا إِلَّا مَنِ اتَّقَى، وَبَرَّ، وَصَدَقَ."],"takhrij":"حسن: رواه البيهقي في شعب الإيمان (4507) عن أبي عبدالله الحافظ، حدثني مكرم بن أحمد بن مكرم القاضي، حدثنا أبو العباس أحمد بن سعيد الجمال، حدثنا عبد الله بن بكر السهمي، حدثنا حاتم بن أبي صغيرة، عن عمرو بن دينار، عن البراء، فذكره.","grade":"حسن","chapter_ar":"باب التوقِّي في التجارة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bayhaqi in Shu‘ab al-Iman (4507).","chapter_en":"Caution and restraint in trade","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":6,"content":{"translation":{"en":["Al-Bara’ ibn ‘Azib reported: The Messenger of Allah ﷺ came to us at al-Baqi‘ and said: “O merchants.” When they raised their heads to listen, he said: “Merchants will be raised on the Day of Resurrection as sinful people, except those who fear Allah, act righteously, and speak truthfully.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البيهقي في شعب الإيمان (4507)."},{"num":5687,"demo":false,"sanad":"","matn":["عَنْ عَطَاءِ بْنِ يَسَارٍ قَالَ: لَقِيتُ عَبْدَ اللَّهِ بْنَ عَمْرِو بْنِ الْعَاصِ رَضِيَ اللَّهُ عَنْهُمَا قُلْتُ: أَخْبِرْنِي عَنْ صِفَةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي التَّوْرَاةِ. قَالَ: \"أَجَلْ، وَاللَّهِ إِنَّهُ لَمَوْصُوفٌ فِي التَّوْرَاةِ بِبَعْضِ صِفَتِهِ فِي الْقُرْآنِ ﴿يَا أَيُّهَا النَّبِيُّ إِنَّا أَرْسَلْنَاكَ شَاهِدًا وَمُبَشِّرًا وَنَذِيرً﴾ [سورة الأَحْزَابِ: 45] وَحِرْزًا لِلأُمِّيِّينَ، أَنْتَ عَبْدِي وَرَسُولِي، سَمَّيْتُكَ الْمُتَوَكِّلَ، لَيْسَ بِفَظٍّ، وَلاَ غَلِيظٍ، وَلاَ سَخَّابٍ فِي الأَسْوَاقِ، وَلاَ يَدْفَعُ بِالسَّيِّئَةِ السَّيِّئَةَ، وَلَكِنْ يَعْفُو، وَيَغْفِرُ، وَلَنْ يَقْبِضَهُ اللَّهُ حَتَّى يُقِيمَ بِهِ الْمِلَّةَ الْعَوْجَاءَ بِأَنْ يَقُولُوا لاَ إِلَهَ إِلاَّ اللَّهُ، وَيَفْتَحُ بِهَا أعين عمي، وآذان صُمْ، وقلوب غُلْفٌ."],"takhrij":"صحيح: رواه البخاري في البيوع (2125) عن محمد بن سنان، حدثنا فليح، حدثنا هلال، عن عطاء بن يسار قال فذكره.","grade":"صحيح","chapter_ar":"باب كراهية السَّخَب ورفع الصوت في الأسواق","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2125).","chapter_en":"The dislike of shouting and raising the voice in marketplaces","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":7,"content":{"translation":{"en":["‘Ata’ ibn Yasar said: I met Abdullah ibn ‘Amr ibn al-‘As and said, “Tell me about the description of the Messenger of Allah ﷺ in the Torah.” He said: “Yes, by Allah, he is described in the Torah with some of the description found in the Quran: ‘O Prophet, We have sent you as a witness, a bringer of good news, and a warner.’ He is a protection for the unlettered people. You are My servant and My messenger. I have named you the Reliant One. He is neither harsh nor hard-hearted nor loud and quarrelsome in the marketplaces. He does not repay evil with evil, but rather pardons and forgives. Allah will not take him until He straightens through him the crooked religion, so that they say: There is no god but Allah, and through him He opens blind eyes, deaf ears, and sealed hearts.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (2125)."},{"num":5688,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ الشِّرَاءِ وَالْبَيْعِ فِي الْمَسْجِدِ، وَأَنْ تُنْشَدَ فِيهِ ضَالَّةٌ، وَأَنْ يُنْشَدَ فِيهِ شِعْرٌ، وَنَهَى عَنِ التَّحَلُّقِ قَبْلَ الصَّلاَةِ يَوْمَ الْجُمُعَةِ."],"takhrij":"حسن: رواه أبو داود (1079)، والترمذي (322)، والنسائي (716)، وابن ماجه (749)، وصحّحه ابن خزيمة (1306) كلهم من طرق عن محمد بن عجلان، عن عمرو بن شعيب بإسناده مثله.","grade":"حسن","chapter_ar":"باب في كراهية البيع والشراء في المساجد","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (1079), al-Tirmidhi (322), al-Nasa’i (716), and authenticated by Ibn Khuzaymah (1306).","chapter_en":"The dislike of buying and selling in mosques","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":8,"content":{"translation":{"en":["‘Amr ibn Shu‘ayb, from his father, from his grandfather, reported that the Messenger of Allah ﷺ forbade buying and selling in the mosque, announcing lost property in it, reciting poetry in it, and sitting in circles before the Friday prayer."]}},"tuhfa":{},"full":1,"dr":1,"rep":[3140,3357],"tks":"حسن: رواه أبو داود (1079)، والترمذي (322)، والنسائي (716)، وصححه ابن خزيمة (1306)."},{"num":5689,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَدِّ الأَمَانَةَ إِلَى مَنِ ائْتَمَنَكَ، وَلاَ تَخُنْ مَنْ خَانَكَ."],"takhrij":"حسن: رواه أبو داود (3535)، والترمذي (1264)، والدارقطني (2936)، والحاكم (2296) كلهم من طريق شريك وقيس، كلاهما عن أبي حصين، عن أبي صالح، عن أبي هريرة فذكر الحديث.","grade":"حسن","chapter_ar":"باب النهي عن خيانة من خانك","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3535), al-Tirmidhi (1264), who graded it Hasan, al-Daraqutni (3/35), and al-Hakim (2/46).","chapter_en":"The prohibition of betraying one who has betrayed you","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":9,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet said: “Return the trust to the one who entrusted you, and do not betray the one who betrayed you.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3535)، والترمذي (1264) وحسنه، والدارقطني (2936)، والحاكم (2296)."},{"num":5690,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: اجْتَنِبُوا السَّبْعَ الْمُوبِقَاتِ. قَالُوا: يَا رَسُولَ اللَّهِ، وَمَا هُنَّ؟ قَالَ: الشِّرْكُ بِاللَّهِ، وَالسِّحْرُ، وَقَتْلُ النَّفْسِ الَّتِي حَرَّمَ اللَّهُ إِلاَّ بِالْحَقِّ، وَأَكْلُ الرِّبَا، وَأَكْلُ مَالِ الْيَتِيمِ، وَالتَّوَلِّي يَوْمَ الزَّحْفِ، وَقَذْفُ الْمُحْصَنَاتِ الْمُؤْمِنَاتِ الْغَافِلاَتِ."],"takhrij":"متفق عليه: رواه البخاري في الوصايا (2766)، ومسلم في الإيمان (89) من طريق سليمان بن بلال، عن ثور بن زيد، عن أبي الغيث (هو سالم مولى ابن مطيع)، عن أبي هريرة قال فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الزجر عن أكل الربا وبيعه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2766) and Muslim (89).","chapter_en":"Warnings against consuming usury and dealing in it","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":10,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet said: “Avoid the seven destructive sins.” They said: “Messenger of Allah ﷺ, what are they?” He said: “Associating partners with Allah, sorcery, killing a soul that Allah has forbidden except with right, consuming usury, consuming the property of an orphan, fleeing on the day of battle, and accusing chaste, believing, unsuspecting women.”"]},"intro":{"ar":["قال اللّٰه تعالى: {يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَذَرُوا مَا بَقِيَ مِنَ الرِّبَا إِنْ كُنْتُمْ مُؤْمِنِينَ ۝ فَإِنْ لَمْ تَفْعَلُوا فَأْذَنُوا بِحَرْبٍ مِنَ اللَّهِ وَرَسُولِهِ وَإِنْ تُبْتُمْ فَلَكُمْ رُءُوسُ أَمْوَالِكُمْ لَا تَظْلِمُونَ وَلَا تُظْلَمُونَ ۝ وَإِنْ كَانَ ذُو عُسْرَةٍ فَنَظِرَةٌ إِلَىٰ مَيْسَرَةٍ وَأَنْ تَصَدَّقُوا خَيْرٌ لَكُمْ إِنْ كُنْتُمْ تَعْلَمُونَ ۝ وَاتَّقُوا يَوْمًا تُرْجَعُونَ فِيهِ إِلَى اللَّهِ ثُمَّ تُوَفَّىٰ كُلُّ نَفْسٍ مَا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ} [البقرة: ٢٧٨-٢٨١].","وقال تعالى: {الَّذِينَ يَأْكُلُونَ الرِّبَا لَا يَقُومُونَ إِلَّا كَمَا يَقُومُ الَّذِي يَتَخَبَّطُهُ الشَّيْطَانُ مِنَ الْمَسِّ…} [البقرة: ٢٧٥-٢٧٦].","والربا في اللغة: الزيادة. وفي الشرع: الزيادة في المال، ويكون في الفضل وفي الأجل."],"en":["Allah the Exalted said: “O you who believe, fear Allah and give up what remains of usury, if you are truly believers. But if you do not, then be informed of a war from Allah and His Messenger. And if you repent, then you may have your principal sums; you do not wrong, nor are you wronged. And if someone is in hardship, then let there be postponement until ease. But if you remit it as charity, that is better for you, if only you knew. And fear a Day on which you will be returned to Allah; then every soul will be paid in full for what it earned, and they will not be wronged.” [al-Baqarah: 278–281]","And He said: “Those who consume usury will not stand except as one stands who has been struck by Satan into madness…” [al-Baqarah: 275–276]","In language, usury means increase. In sacred law, it means an unlawful increase in wealth, whether through excess in exchange or through delay in repayment."]}},"tuhfa":{},"full":1,"rep":[230,6809,7001,7897,11517,12142,12362,12859],"tks":"متفق عليه: رواه البخاري (2766)، ومسلم (89)."},{"num":5691,"demo":false,"sanad":"","matn":["عَنْ عَوْنِ بْنِ أَبِي جُحَيْفَةَ قَالَ: رَأَيْتُ أَبِي اشْتَرَى عَبْدًا حَجَّامًا، فَأَمَرَ بمحاجمه، فكُسِرَتْ، فَسَأَلْتُهُ، فَقَالَ: نَهَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ ثَمَنِ الْكَلْبِ، وَثَمَنِ الدَّمِ، وَنَهَى عَنِ الْوَاشِمَةِ، وَالْمَوْشُومَةِ، وَآكِلِ الرِّبَا، ومؤكله، وَلَعَنَ الْمُصَوِّرَ."],"takhrij":"صحيح: رواه البخاري في البيوع (2238) عن حجاج بن منهال، حدثنا شعبة، قال: أخبرني عون بن أبي جحيفة، قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الزجر عن أكل الربا وبيعه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2238).","chapter_en":"Warnings against consuming usury and dealing in it","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":10,"content":{"translation":{"en":["‘Awn ibn Abi Juhayfah said: I saw my father buy a slave who performed cupping, and he ordered his instruments to be broken. I asked him, and he said: The Prophet forbade the price of a dog and the price of blood, forbade the tattooer and the one tattooed, forbade the consumer of usury and the one who pays it, and he cursed the image-maker."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (2238)."},{"num":5692,"demo":false,"sanad":"","matn":["عَنْ سَمُرَةَ بْنِ جُنْدُبٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: رَأَيْتُ اللَّيْلَةَ رَجُلَيْنِ أَتَيَانِي، فَأَخْرَجَانِي إِلَى أَرْضٍ مُقَدَّسَةٍ، فَانْطَلَقْنَا حَتَّى أَتَيْنَا عَلَى نَهَرٍ مِنْ دَمٍ، فِيهِ رَجُلٌ قَائِمٌ، وَعَلَى وَسَطِ النَّهْرِ رَجُلٌ بَيْنَ يَدَيْهِ حِجَارَةٌ، فَأَقْبَلَ الرَّجُلُ الَّذِي فِي النَّهَرِ، فَإِذَا أَرَادَ الرَّجُلُ أَنْ يَخْرُجَ رَمَى الرَّجُلُ بِحَجَرٍ فِي فِيهِ، فَرَدَّهُ حَيْثُ كَانَ، فَجَعَلَ كُلَّمَا جَاءَ لِيَخْرُجَ رَمَى فِي فِيهِ بِحَجَرٍ، فَيَرْجِعُ كَمَا كَانَ، فَقُلْتُ: مَا هَذَا؟ فَقَالَ: الَّذِي رَأَيْتَهُ فِي النَّهَرِ آكِلُ الرِّبَا."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2085) ومسلم في الفضائل (2275) كلاهما من حديث جرير بن حازم، حدثنا أبو رجاء العطاردي، عن سمرة بن جندب، فذكره، وا للفظ للبخاري، واختصره مسلم.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الزجر عن أكل الربا وبيعه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2085) and Muslim (2275). The wording is that of al-Bukhari.","chapter_en":"Warnings against consuming usury and dealing in it","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":10,"content":{"translation":{"en":["Samurah ibn Jundub reported that the Prophet said: “Last night I saw two men who came to me and took me out to a sacred land… until we came upon a river of blood, in which there was a man standing, and in the middle of the river there was another man before whom were stones… I said: What is this? They said: The one you saw in the river is the consumer of usury.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (2085)، ومسلم (2275)، واللفظ للبخاري."},{"num":5693,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ قَالَ:  لَعَنَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ آكِلَ الرِّبَا، وَمُوكِلَهُ، وَكَاتِبَهُ، وَشَاهِدَيْهِ، وَقَالَ: هُمْ سَوَاءٌ."],"takhrij":"صحيح: رواه مسلم في المساقاة (1598) من طريق هشيم، أخبرنا أبو الزبير، عن جابر قال فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الزجر عن أكل الربا وبيعه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1598).","chapter_en":"Warnings against consuming usury and dealing in it","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":10,"content":{"translation":{"en":["Jabir reported: The Messenger of Allah ﷺ cursed the one who consumes usury, the one who pays it, the one who records it, and its two witnesses. And he said: “They are all alike.”"]}},"tuhfa":{},"full":1,"rep":[12045],"tks":"صحيح: رواه مسلم (1598)."},{"num":5694,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن مَسْعُودٍ قَالَ: لَعَنَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ آكِلَ الرِّبَا، وموكله. قَالَ: قُلْتُ: وَكَاتِبَهُ، وَشَاهِدَيْهِ؟ قَالَ: إنا نُحَدِّثُ بِمَا سَمِعْنَا."],"takhrij":"صحيح: رواه مسلم في المساقاة (1597: 105) من طريق جرير، عن مغيرة قال: سأل شِباكٌ إبراهيمَ، فحدثنا عن علقمة، عن عبد الله قال فذكره. وشِباكٌ –بكسر أوله- الضبي الكوفي الأعمى.","grade":"صحيح","chapter_ar":"باب ما جاء في الزجر عن أكل الربا وبيعه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1597).","chapter_en":"Warnings against consuming usury and dealing in it","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":10,"content":{"translation":{"en":["Abdullah ibn Mas‘ud reported: The Messenger of Allah ﷺ cursed the one who consumes usury and the one who pays it. I said: “And the one who records it and its two witnesses?” He said: “We only narrate what we heard.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1597)."},{"num":5695,"demo":false,"sanad":"","matn":["عَنِ ابْنِ مَسْعُودٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَا أَحَدٌ أَكْثَرَ مِنَ الرِّبَا إِلاَّ كَانَ عَاقِبَةُ أَمْرِهِ إِلَى قِلَّةٍ."],"takhrij":"صحيح: رواه ابن ماجه (2279)، عن العباس بن جعفر قال: حدثنا عمرو بن عون، حدثنا يحيى بن أبي زائدة، عن إسرائيل، عن رُكين بن الربيع بن عميلة، عن أبيه، عن ابن مسعود فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الزجر عن أكل الربا وبيعه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Majah (2279).","chapter_en":"Warnings against consuming usury and dealing in it","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":10,"content":{"translation":{"en":["Abdullah ibn Mas‘ud reported that the Prophet said: “No one increases in usury except that the final outcome of his affair will be loss and decrease.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[12048],"tks":"صحيح: رواه ابن ماجه (2279)."},{"num":5696,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: آخِرُ آيَةٍ نَزَلَتْ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ آيَةُ الرِّبَا."],"takhrij":"صحيح: رواه البخاري في التفسير (4544) عن قبيصة بن عقبة، حدثنا سفيان، عن عاصم، عن الشعبي، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الزجر عن أكل الربا وبيعه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (4544).","chapter_en":"Warnings against consuming usury and dealing in it","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":10,"content":{"translation":{"en":["Ibn ‘Abbas said: The last verse revealed to the Prophet was the verse about usury."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (4544)."},{"num":5697,"demo":false,"sanad":"","matn":["عَنْ عُمَرَ بْنِ الْخَطَّابِ قَالَ: إِنَّ آخِرَ مَا نَزَلَ من الْقُرْآنِ آيَةُ الرِّبَا، وَإِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قُبِضَ، وَلَمْ يُفَسِّرْهَا، فَدَعُوا الرِّبَا وَالرِّيبَةَ."],"takhrij":"حسن: رواه ابن ماجه (2276) عن الخالد بن الحارث، والإمام أحمد (246) عن يحيى بن سعيد، والأصبهاني في الترغيب والترهيب (1405) عن عبدالوهاب بن عطاء، كلهم عن سعيد بن أبي عروبة، عن قتادة، عن سعيد بن المسيب، عن عمر بن الخطاب فذكره. وإسناده حسن من أجل عبد الوهاب بن عطاء الخفاف فإنه حسن الحديث إذا لم يأت بما يُنكر عليه.","grade":"حسن","chapter_ar":"باب ما جاء في الزجر عن أكل الربا وبيعه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2276) and Ahmad (246).","chapter_en":"Warnings against consuming usury and dealing in it","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":10,"content":{"translation":{"en":["Umar ibn al-Khattab said: The last part of the Quran to be revealed was the verse about usury, and the Messenger of Allah ﷺ passed away before explaining it in detail, so leave usury and whatever causes doubt."]}},"tuhfa":{},"full":1,"dr":1,"rep":[11735],"tks":"حسن: رواه ابن ماجه (2276)، وأحمد (246)."},{"num":5698,"demo":false,"sanad":"","matn":["عَنْ مَالِكِ بْنِ أَوْسٍ بْنِ الْحَدَثَانِ النصري: أَنَّهُ الْتَمَسَ صَرْفًا بِمِائَةِ دِينَارٍ. قَالَ: فَدَعَانِي طَلْحَةُ بْنُ عبيدالله، فَتَرَاوَضْنَا حَتَّى اصْطَرَفَ مِنِّي، وَأَخَذَ الذَّهَبَ يُقَلِّبُهَا فِي يَدِهِ، ثُمَّ قَالَ: حَتَّى يَأْتِينِي خَازِنِي مِنَ الْغَابَةِ، وَعُمَرُ بْنُ الْخَطَّابِ يَسْمَعُ، فَقَالَ عُمَرُ: وَاللَّهِ لاَ تُفَارِقُهُ حَتَّى تَأْخُذَ مِنْهُ، ثُمَّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الذَّهَبُ بالورق رِبًا إِلاَّ هَاءَ وَهَاءَ، وَالْبُرُّ بِالْبُرِّ رِبًا إِلاَّ هَاءَ وَهَاءَ، وَالتَّمْرُ بِالتَّمْرِ رِبًا إِلاَّ هَاءَ وَهَاءَ، وَالشَّعِيرُ بِالشَّعِيرِ رِبًا إِلاَّ هَاءَ وَهَاءَ."],"takhrij":"متفق عليه: رواه مالك في البيوع (38) عن ابن شهاب، عن مالك بن أوس فذكره. ورواه البخاري في البيوع (2174) من طريق مالك به مثله.","grade":"متفق عليه","chapter_ar":"باب جريان ربا الفضل والنسيئة في الأصناف الربوية","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon. Narrated by Malik (38), al-Bukhari (2174), and Muslim (1586).","chapter_en":"The applicability of usury of excess and usury of delay in usurious categories","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":11,"content":{"translation":{"en":["Malik ibn Aws ibn al-Hadathan al-Nasri reported that he sought to exchange one hundred dinars. Talhah ibn Ubayd Allah called him, and they negotiated until Talhah agreed to exchange with him. Talhah took the gold and turned it in his hand, then said, “Wait until my treasurer comes from the forest area.” Umar ibn al-Khattab was listening and said, “By Allah, you must not leave him until you take it from him.” Then he said: The Messenger of Allah ﷺ said, “Gold for silver is usury unless it is hand to hand, wheat for wheat is usury unless it is hand to hand, dates for dates is usury unless it is hand to hand, and barley for barley is usury unless it is hand to hand.”"]},"buhuth":{"en":["Its meaning: “We negotiated” means they discussed the amount of exchange, with increase and decrease, as each tried to gently persuade the other. It was also said that here it means describing the goods, with each one describing his item to the other.","Its meaning: “Except hand to hand” means: take and give. The meaning is that it must be exchanged on the spot, with both sides taking possession in the same sitting."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (38) والبخاري (2174) ومسلم (1586)."},{"num":5699,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لاَ تَبِيعُوا الذَّهَبَ بِالذَّهَبِ إِلاَّ مِثْلاً بِمِثْلٍ، وَلاَ تُشِفُّوا بَعْضَهَا عَلَى بَعْضٍ، وَلاَ تَبِيعُوا الْوَرِقَ بِالْوَرِقِ إِلاَّ مِثْلاً بِمِثْلٍ، وَلاَ تُشِفُّوا بَعْضَهَا عَلَى بَعْضٍ، وَلاَ تَبِيعُوا مِنْهَا غَائِبًا بِنَاجِزٍ."],"takhrij":"متفق عليه: رواه مالك في البيوع (30) عن نافع، عن أبي سعيد به.","grade":"متفق عليه","chapter_ar":"باب جريان ربا الفضل والنسيئة في الأصناف الربوية","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon. Narrated by Malik (30), al-Bukhari (2177), and Muslim (1584).","chapter_en":"The applicability of usury of excess and usury of delay in usurious categories","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":11,"content":{"translation":{"en":["Abu Saeed al-Khudri reported that the Messenger of Allah ﷺ said: “Do not sell gold for gold except equal for equal, and do not make some of it exceed some of it. Do not sell silver for silver except equal for equal, and do not make some of it exceed some of it. And do not sell any delayed amount of it for what is present and immediate.”"]},"buhuth":{"en":["Its meaning: “Do not make some of it exceed some of it” means do not give one side more than the other. The word refers to increase, and it can also be used for deficiency."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (30) والبخاري (2177)، ومسلم (1584)."},{"num":5700,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  الذَّهَبُ بِالذَّهَبِ، وَالْفِضَّةُ بِالْفِضَّةِ، وَالْبُرُّ بِالْبُرِّ، وَالشَّعِيرُ بِالشَّعِيرِ، وَالتَّمْرُ بِالتَّمْرِ، وَالْمِلْحُ بِالْمِلْحِ، مِثْلًا بِمِثْلٍ، يَدًا بِيَدٍ، فَمَنْ زَادَ أَوِ اسْتَزَادَ فَقَدْ أَرْبَى، الْآخِذُ وَالْمُعْطِي فِيهِ سَوَاءٌ."],"takhrij":"صحيح: رواه مسلم في المساقاة (1584) عن أبي بكر بن أبي شيبة، حدثنا وكيع، حدثنا إسماعيل بن مسلم العبدي، حدثنا أبو المتوكل الناجي، عن أبي سعيد الخدري قال:فذكره.","grade":"صحيح","chapter_ar":"باب جريان ربا الفضل والنسيئة في الأصناف الربوية","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Muslim (1584).","chapter_en":"The applicability of usury of excess and usury of delay in usurious categories","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":11,"content":{"translation":{"en":["Abu Saeed al-Khudri reported that the Messenger of Allah ﷺ said: “Gold for gold, silver for silver, wheat for wheat, barley for barley, dates for dates, and salt for salt must be equal for equal and hand to hand. Whoever gives more or asks for more has engaged in usury. The taker and the giver are the same in that.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1584)."},{"num":5701,"demo":false,"sanad":"","matn":["عَنْ أَبِي بَكْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لاَ تَبِيعُوا الذَّهَبَ بِالذَّهَبِ إِلاَّ سَوَاءً بِسَوَاءٍ، وَالْفِضَّةَ بِالْفِضَّةِ إِلاَّ سَوَاءً بِسَوَاءٍ، وَبِيعُوا الذَّهَبَ بِالْفِضَّةِ، وَالْفِضَّةَ بِالذَّهَبِ كَيْفَ شِئْتُمْ."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2175)، ومسلم في المساقاة (1590) من طريق يحيى بن أبي إسحاق، حدثنا عبد الرحمن بن أبي بكرة قال: قال أبو بكرة فذكره.","grade":"متفق عليه","chapter_ar":"باب جريان ربا الفضل والنسيئة في الأصناف الربوية","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon. Narrated by al-Bukhari (2175) and Muslim (1590).","chapter_en":"The applicability of usury of excess and usury of delay in usurious categories","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":11,"content":{"translation":{"en":["Abu Bakrah reported that the Messenger of Allah ﷺ said: “Do not sell gold for gold except equal for equal, and do not sell silver for silver except equal for equal. But sell gold for silver, and silver for gold, however you wish.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (2175)، ومسلم (1590)."},{"num":5702,"demo":false,"sanad":"","matn":["عَنْ أَبِي الْمِنْهَالِ قَالَ:  بَاعَ شَرِيكٌ لِي وَرِقًا بِنَسِيئَةٍ إِلَى الْمَوْسِمِ، أَوْ إِلَى الْحَجِّ، فَجَاءَ إِلَيَّ، فَأَخْبَرَنِي، فَقُلْتُ: هَذَا أَمْرٌ لَا يَصْلُحُ، قَالَ: قَدْ بِعْتُهُ فِي السُّوقِ، فَلَمْ يُنْكِرْ ذَلِكَ عَلَيَّ أَحَدٌ، فَأَتَيْتُ الْبَرَاءَ بْنَ عَازِبٍ، فَسَأَلْتُهُ، فَقَالَ: قَدِمَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمَدِينَةَ وَنَحْنُ نَبِيعُ هَذَا الْبَيْعَ، فَقَالَ: مَا كَانَ يَدًا بِيَدٍ، فَلَا بَأْسَ بِهِ، وَمَا كَانَ نَسِيئَةً، فَهُوَ رِبًا. وَائْتِ زَيْدَ بْنَ أَرْقَمَ، فَإِنَّهُ أَعْظَمُ تِجَارَةً مِنِّي، فَأَتَيْتُهُ، فَسَأَلْتُهُ، فَقَالَ مِثْلَ ذَلِكَ."],"takhrij":"متفق عليه: رواه مسلم في المساقاة (1589: 86) عن محمد بن حاتم بن ميمون، حدثنا سفيان بن عيينة، عن عمرو (وهو ابن دينار) عن أبي المنهال به.","grade":"متفق عليه","chapter_ar":"باب جريان ربا الفضل والنسيئة في الأصناف الربوية","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon. Narrated by Muslim (1589, nos. 78 and 86) and al-Bukhari (2180, 2181).","chapter_en":"The applicability of usury of excess and usury of delay in usurious categories","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":11,"content":{"translation":{"en":["Abu al-Minhal reported: A partner of mine sold silver on delayed payment until the season, or until the pilgrimage. He came and told me, and I said, “This is not right.” He said, “I sold it in the market, and no one objected to me.” So I went to al-Bara ibn Azib and asked him. He said: The Prophet came to Madinah while we used to make this type of sale, and he said, “Whatever is hand to hand is permissible, and whatever is delayed is usury.” Then he said: “Go to Zayd ibn Arqam, for he is greater than me in trade.” So I went to him and asked him, and he said the same."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مسلم (1589: 78، 86) والبخاري (2180، 2181)."},{"num":5703,"demo":false,"sanad":"","matn":["عَنْ عُبَادَةَ بْنِ الصَّامِتِ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  الذَّهَبُ بِالذَّهَبِ، وَالْفِضَّةُ بِالْفِضَّةِ، وَالْبُرُّ بِالْبُرِّ، وَالشَّعِيرُ بِالشَّعِيرِ، وَالتَّمْرُ بِالتَّمْرِ، وَالْمِلْحُ بِالْمِلْحِ، مِثْلًا بِمِثْلٍ، سَوَاءً بِسَوَاءٍ، يَدًا بِيَدٍ، فَإِذَا اخْتَلَفَتْ هَذِهِ الْأَصْنَافُ، فَبِيعُوا كَيْفَ شِئْتُمْ، إِذَا كَانَ يَدًا بِيَدٍ."],"takhrij":"صحيح: رواه مسلم في المساقاة (1587: 81) من طريق وكيع، حدثنا سفيان، عن خالد الحذاء، عن أبي قلابة، عن أبي الأشعث، عن عبادة بن الصامت فذكره.","grade":"صحيح","chapter_ar":"باب جريان ربا الفضل والنسيئة في الأصناف الربوية","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Muslim (1587, no. 81).","chapter_en":"The applicability of usury of excess and usury of delay in usurious categories","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":11,"content":{"translation":{"en":["Ubadah ibn al-Samit reported that the Messenger of Allah ﷺ said: “Gold for gold, silver for silver, wheat for wheat, barley for barley, dates for dates, and salt for salt must be equal for equal, exact and equal, hand to hand. If these categories differ, then sell as you wish, so long as it is hand to hand.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1587: 81)."},{"num":5704,"demo":false,"sanad":"","matn":["عَنْ أَبِي قِلَابَةَ قَالَ:  كُنْتُ بِالشَّامِ فِي حَلْقَةٍ فِيهَا مُسْلِمُ بْنُ يَسَارٍ، فَجَاءَ أَبُو الْأَشْعَثِ، قَالَ: قَالُوا: أَبُو الْأَشْعَثِ! أَبُو الْأَشْعَثِ! فَجَلَسَ، فَقُلْتُ لَهُ: حَدِّثْ أَخَانَا حَدِيثَ عُبَادَةَ بْنِ الصَّامِتِ، قَالَ: نَعَمْ، غَزَوْنَا غَزَاةً وَعَلَى النَّاسِ مُعَاوِيَةُ، فَغَنِمْنَا غَنَائِمَ كَثِيرَةً، فَكَانَ فِيمَا غَنِمْنَا آنِيَةٌ مِنْ فِضَّةٍ، فَأَمَرَ مُعَاوِيَةُ رَجُلًا أَنْ يَبِيعَهَا فِي أَعْطِيَاتِ النَّاسِ، فَتَسَارَعَ النَّاسُ فِي ذَلِكَ، فَبَلَغَ عُبَادَةَ بْنَ الصَّامِتِ، فَقَامَ، فَقَالَ: إِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَنْهَى عَنْ بَيْعِ الذَّهَبِ بِالذَّهَبِ، وَالْفِضَّةِ بِالْفِضَّةِ، وَالْبُرِّ بِالْبُرِّ، وَالشَّعِيرِ بِالشَّعِيرِ، وَالتَّمْرِ بِالتَّمْرِ، وَالْمِلْحِ بِالْمِلْحِ، إِلَّا سَوَاءً بِسَوَاءٍ، عَيْنًا بِعَيْنٍ، فَمَنْ زَادَ أَوِ ازْدَادَ، فَقَدْ أَرْبَى. فَرَدَّ النَّاسُ مَا أَخَذُوا، فَبَلَغَ ذَلِكَ مُعَاوِيَةَ، فَقَامَ خَطِيبًا، فَقَالَ: أَلَا مَا بَالُ رِجَالٍ يَتَحَدَّثُونَ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَحَادِيثَ قَدْ كُنَّا نَشْهَدُهُ وَنَصْحَبُهُ، فَلَمْ نَسْمَعْهَا مِنْهُ؟ فَقَامَ عُبَادَةُ بْنُ الصَّامِتِ، فَأَعَادَ الْقِصَّةَ، ثُمَّ قَالَ: لَنُحَدِّثَنَّ بِمَا سَمِعْنَا مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَإِنْ كَرِهَ مُعَاوِيَةُ (أَوْ قَالَ: وَإِنْ رَغِمَ)، مَا أُبَالِي أَنْ لَا أَصْحَبَهُ فِي جُنْدِهِ لَيْلَةً سَوْدَاءَ."],"takhrij":"صحيح: رواه مسلم في المساقاة (1587: 80) عن عبيد الله بن عمر القواريري، حدثنا حماد بن زيد، عن أيوب، عن أبي قلابة فذكره.","grade":"صحيح","chapter_ar":"باب جريان ربا الفضل والنسيئة في الأصناف الربوية","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Muslim (1587, no. 80).","chapter_en":"The applicability of usury of excess and usury of delay in usurious categories","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":11,"content":{"translation":{"en":["Abu Qilabah reported: I was in Syria in a circle that included Muslim ibn Yasar, when Abu al-Ashath came. People said, “Abu al-Ashath, Abu al-Ashath.” He sat down, and I said to him, “Tell our brother the hadith of Ubadah ibn al-Samit.” He said: Yes. We went on a military expedition while Muawiyah was over the people, and we obtained much war booty. Among what we captured were silver vessels. Muawiyah ordered a man to sell them among the people as part of their stipends, so the people rushed to that. News of this reached Ubadah ibn al-Samit, so he stood and said: “I heard the Messenger of Allah ﷺ forbid selling gold for gold, silver for silver, wheat for wheat, barley for barley, dates for dates, and salt for salt except equal for equal, item for item. Whoever gives more or takes more has dealt in usury.” So the people returned what they had taken. This reached Muawiyah, and he stood to speak and said: “What is the matter with some men narrating hadiths from the Messenger of Allah ﷺ when we were with him and accompanied him, yet we did not hear these from him?” Then Ubadah ibn al-Samit stood up, repeated the story, and said: “We will certainly narrate what we heard from the Messenger of Allah ﷺ even if Muawiyah dislikes it, or despite him. I do not care if I never accompany him in his army on a dark night.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1587: 80)."},{"num":5705,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: الدِّينَارُ بِالدِّينَارِ، وَالدِّرْهَمُ بِالدِّرْهَمِ لَا فَضْلَ بَيْنَهُمَا."],"takhrij":"صحيح: رواه مالك في البيوع (29) عن موسى بن إبراهيم، عن أبي الحُباب سعيد بن يسار، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب جريان ربا الفضل والنسيئة في الأصناف الربوية","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Malik (29) and Muslim (1588, no. 85).","chapter_en":"The applicability of usury of excess and usury of delay in usurious categories","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":11,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “A dinar for a dinar, and a dirham for a dirham, with no excess between them.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مالك (29) ومسلم (1588: 85)."},{"num":5706,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  التَّمْرُ بِالتَّمْرِ، وَالْحِنْطَةُ بِالْحِنْطَةِ، وَالشَّعِيرُ بِالشَّعِيرِ، وَالْمِلْحُ بِالْمِلْحِ، مِثْلًا بِمِثْلٍ، يَدًا بِيَدٍ، فَمَنْ زَادَ أَوِ اسْتَزَادَ فَقَدْ أَرْبَى، إِلَّا مَا اخْتَلَفَتْ أَلْوَانُهُ."],"takhrij":"صحيح: رواه مسلم في المساقاة (1588: 83) من طريق ابن فضيل بن غزوان، عن أبيه، عن أبي زرعة، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب جريان ربا الفضل والنسيئة في الأصناف الربوية","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Muslim (1588, no. 83).","chapter_en":"The applicability of usury of excess and usury of delay in usurious categories","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":11,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “Dates for dates, wheat for wheat, barley for barley, and salt for salt must be equal for equal and hand to hand. Whoever gives more or asks for more has committed usury, except when their types differ.”"]},"buhuth":{"en":["Its meaning: “Their types differ” means their different categories or kinds."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1588: 83)."},{"num":5707,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  الذَّهَبُ بِالذَّهَبِ، وَزْنًا بِوَزْنٍ، مِثْلًا بِمِثْلٍ، وَالْفِضَّةُ بِالْفِضَّةِ، وَزْنًا بِوَزْنٍ، مِثْلًا بِمِثْلٍ، فَمَنْ زَادَ أَوِ اسْتَزَادَ فَهُوَ رِبًا."],"takhrij":"صحيح: رواه مسلم في المساقاة (1588: 84) من طريق ابن فضيل بن غزوان، عن أبيه، عن ابن أبي نعم (هو عبد الرحمن)، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب جريان ربا الفضل والنسيئة في الأصناف الربوية","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Muslim (1588, no. 84).","chapter_en":"The applicability of usury of excess and usury of delay in usurious categories","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":11,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “Gold for gold must be weight for weight, equal for equal, and silver for silver must be weight for weight, equal for equal. Whoever gives more or asks for more, that is usury.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1588: 84)."},{"num":5708,"demo":false,"sanad":"","matn":["عَنْ عُثْمَانَ بْنِ عَفَّانَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  لَا تَبِيعُوا الدِّينَارَ بِالدِّينَارَيْنِ، وَلَا الدِّرْهَمَ بِالدِّرْهَمَيْنِ."],"takhrij":"صحيح: رواه مسلم في المساقاة (1585) من طريق ابن وهب، أخبرني مخرمة، عن أبيه: سمعت سليمان بن يسار يقول: إنه سمع مالك بن أبي عامر يحدث عن عثمان بن عفان فذكره.","grade":"صحيح","chapter_ar":"باب جريان ربا الفضل والنسيئة في الأصناف الربوية","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Muslim (1585).","chapter_en":"The applicability of usury of excess and usury of delay in usurious categories","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":11,"content":{"translation":{"en":["Uthman ibn Affan reported that the Messenger of Allah ﷺ said: “Do not sell one dinar for two dinars, nor one dirham for two dirhams.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1585)."},{"num":5709,"demo":false,"sanad":"","matn":["عَنْ مُجَاهِدٍ، أَنَّهُ قَالَ: كُنْتُ مَعَ عَبْدِ اللَّهِ بْنِ عُمَرَ، فَجَاءَهُ صَائِغٌ، فَقَالَ لَهُ: يَا أَبَا عَبْدِ الرَّحْمَنِ، إِنِّي أَصُوغُ الذَّهَبَ، ثُمَّ أَبِيعُ الشَّىْءَ مِنْ ذَلِكَ بِأَكْثَرَ مِنْ وَزْنِهِ، فَأَسْتَفْضِلُ مِنْ ذَلِكَ قَدْرَ عَمَلِ يَدِي. فَنَهَاهُ عَبْدُ اللَّهِ عَنْ ذَلِكَ، فَجَعَلَ الصَّائِغُ يُرَدِّدُ عَلَيْهِ الْمَسْأَلَةَ، وَعَبْدُ اللَّهِ يَنْهَاهُ حَتَّى انْتَهَى إِلَى بَابِ الْمَسْجِدِ أَوْ إِلَى دَابَّةٍ يُرِيدُ أَنْ يَرْكَبَهَا، ثُمَّ قَالَ عَبْدُ اللَّهِ بْنُ عُمَرَ: الدِّينَارُ بِالدِّينَارِ وَالدِّرْهَمُ بِالدِّرْهَمِ لاَ فَضْلَ بَيْنَهُمَا، هَذَا عَهْدُ نَبِيِّنَا إِلَيْنَا، وَعَهْدُنَا إِلَيْكُمْ."],"takhrij":"صحيح: رواه مالك في البيوع (31) عن حميد بن قيس المكي، عن مجاهد أنه قال فذكره. والصائغ اسمه: وردان الرومي كما جاء ذكره في \"السنن المأثورة\" للشافعي.","grade":"صحيح","chapter_ar":"باب جريان ربا الفضل والنسيئة في الأصناف الربوية","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Malik (31).","chapter_en":"The applicability of usury of excess and usury of delay in usurious categories","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":11,"content":{"translation":{"en":["Mujahid reported: I was with Abdullah ibn Umar when a goldsmith came to him and said: “Abu Abd al-Rahman, I work gold, then I sell what I make for more than its weight, taking the extra amount in return for the work of my hand.” Abdullah forbade him from that. The goldsmith kept repeating the question, and Abdullah kept forbidding him until he reached the door of the mosque, or his riding animal which he intended to mount. Then Abdullah ibn Umar said: “A dinar for a dinar, and a dirham for a dirham, with no excess between them. This is the covenant of our Prophet ﷺ to us, and our covenant to you.”"]},"buhuth":{"en":["Ibn Umar’s statement, “This is the covenant of our Prophet ﷺ to us,” means the Companions of the Prophet ﷺ, after this ruling had become established for him from the Prophet ﷺ through the hadith of Abu Saeed al-Khudri and others. It is established that Ibn Umar had once held the same view as Ibn Abbas regarding currency exchange, until Abu Saeed al-Khudri informed him that the Prophet ﷺ forbade selling gold for gold except equal for equal, so he accepted it and returned to that ruling."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مالك (31)."},{"num":5710,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، وَعَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اسْتَعْمَلَ رَجُلاً عَلَى خَيْبَرَ، فَجَاءَهُ بِتَمْرٍ جَنِيبٍ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَكُلُّ تَمْرِ خَيْبَرَ هَكَذَا. قَالَ لاَ، وَاللَّهِ يَا رَسُولَ اللَّهِ، إِنَّا لَنَأْخُذُ الصَّاعَ مِنْ هَذَا بِالصَّاعَيْنِ، وَالصَّاعَيْنِ بِالثَّلاَثَةِ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لاَ تَفْعَلْ، بِعِ الْجَمْعَ بِالدَّرَاهِمِ، ثُمَّ ابْتَعْ بِالدَّرَاهِمِ جَنِيبًا."],"takhrij":"متفق عليه: رواه مالك في البيوع (21) عن عبدالحميد بن سهيل بن عبدالرحمن بن عوف، عن سعيد بن المسيب، عن أبي سعيد الخدري، وعـن أبي هريرة. ورواه البخاري في البيوع (2201)، ومسلم في المساقاة (1593: 95) كلاهما عن مالك به.","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع التمر بالتمر أو الطعام بالطعام متفاضلًا","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon. Narrated by Malik (21), al-Bukhari (2201), and Muslim (1593, no. 95).","chapter_en":"The Prohibition of Selling Dates for Dates or Food for Food with Inequality","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":12,"content":{"translation":{"en":["Abu Saeed al-Khudri and Abu Hurayrah reported that the Messenger of Allah ﷺ appointed a man over Khaybar, and he came with fine quality dates. The Messenger of Allah ﷺ said to him: “Are all the dates of Khaybar like this?” He said: “No, by Allah, Messenger of Allah ﷺ. We take one measure of this in exchange for two measures, and two for three.” The Messenger of Allah ﷺ said: “Do not do that. Sell the mixed dates for silver coins, then buy the fine dates with those coins.”"]},"buhuth":{"en":["In another narration in both collections: The Messenger of Allah ﷺ appointed a man from Banu Adi of the Ansar over Khaybar, and he came with fine dates. The Messenger of Allah ﷺ said to him: “Are all the dates of Khaybar like this?” He said: “No, by Allah, Messenger of Allah ﷺ. We buy one measure of these for two measures of mixed dates.” The Messenger of Allah ﷺ said: “Do not do that. Rather, equal for equal, or sell this and buy from that with its price, and the same applies to weight.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (21) والبخاري (2201)، ومسلم (1593: 95)."},{"num":5711,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كُنَّا نُرْزَقُ تَمْرَ الْجَمْعِ، وَهْوَ الْخِلْطُ مِنَ التَّمْرِ، وَكُنَّا نَبِيعُ صَاعَيْنِ بِصَاعٍ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لاَ صَاعَيْنِ بِصَاعٍ، وَلاَ دِرْهَمَيْنِ بِدِرْهَمٍ."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2080)، ومسلم في المساقاة (1595) كلاهما من طريق شيبان، عن يحيى، عن أبي سلمة، عن أبي سعيد الخدري فذكره.","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع التمر بالتمر أو الطعام بالطعام متفاضلًا","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon. Narrated by al-Bukhari (2080) and Muslim (1595).","chapter_en":"The Prohibition of Selling Dates for Dates or Food for Food with Inequality","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":12,"content":{"translation":{"en":["Abu Saeed al-Khudri reported: We used to be given mixed dates, and we used to sell two measures for one measure. Then the Prophet ﷺ said: “Not two measures for one measure, and not two dirhams for one dirham.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (2080)، ومسلم (1595)."},{"num":5712,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ: جَاءَ بِلاَلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِتَمْرٍ بَرْنِيٍّ، فَقَالَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مِنْ أَيْنَ هَذَا؟. قَالَ بِلاَلٌ: كَانَ عِنْدِي تَمْرٌ رديء، فَبِعْتُ مِنْهُ صَاعَيْنِ بِصَاعٍ لِنُطْعِمَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عِنْدَ ذَلِكَ: أَوَّهْ، أَوَّهْ، عَيْنُ الرِّبَا، لاَ تَفْعَلْ، وَلَكِنْ إِذَا أَرَدْتَ أَنْ تَشْتَرِيَ فبِع التَّمْرَ بِبَيْعٍ آخَرَ، ثُمَّ اشتريه."],"takhrij":"متفق عليه: رواه البخاري في الوكالة (2312)، ومسلم في المساقاة (1594) من طريق معاوية بن سلام، أخبرني يحيى (هو ابن أبي كثير) قال: سمعت عقبة بن عبدالغافر أنه سمع أبا سعيد الخدري يقول فذكره.","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع التمر بالتمر أو الطعام بالطعام متفاضلًا","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon. Narrated by al-Bukhari (2312) and Muslim (1594).","chapter_en":"The Prohibition of Selling Dates for Dates or Food for Food with Inequality","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":12,"content":{"translation":{"en":["Abu Saeed al-Khudri reported: Bilal brought some high-quality dates to the Prophet ﷺ, and the Prophet ﷺ said to him: “Where is this from?” Bilal said: “I had some poor-quality dates, so I sold two measures of them for one measure so that we could feed the Prophet ﷺ.” At that the Prophet ﷺ said: “Oh, oh, this is the essence of usury. Do not do that. Rather, when you want to buy, sell the dates in a separate sale, then buy with that price.”"]},"buhuth":{"en":["Its meaning: “Oh, oh” is an expression said when showing pain or strong warning."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2312)، ومسلم (1594)."},{"num":5713,"demo":false,"sanad":"","matn":["عَنْ أَبِي صَالِحٍ، أَنَّ رَجُلاً، مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَخْبَرَهُ قَالَ: يَا رَسُولَ اللَّهِ، إِنَّا لاَ نَجِدُ الصَّيْحَانِيَّ، وَلاَ الْعِذْقَ بِجَمْعِ التَّمْرِ حَتَّى نَزِيدَهُمْ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: بِعْهُ بِالْوَرِقِ، ثُمَّ اشْتَرِ بِهِ."],"takhrij":"صحيح: رواه النسائي (4552) عن قتيبة بن سعيد قال: حدثنا أبو الأحوص، عن الأعمش، عن حبيب بن أبي ثابت، عن أبي صالح فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن بيع التمر بالتمر أو الطعام بالطعام متفاضلًا","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by al-Nasa’i (4552).","chapter_en":"The Prohibition of Selling Dates for Dates or Food for Food with Inequality","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":12,"content":{"translation":{"en":["Abu Salih reported that a man from the Companions of the Prophet ﷺ said: “Messenger of Allah ﷺ, we cannot obtain al-Sayhani dates or al-‘Idhq dates for the same amount of mixed dates unless we give them extra.” So the Messenger of Allah ﷺ said: “Sell it for silver, then buy with that.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (4552)."},{"num":5714,"demo":false,"sanad":"","matn":["عَنِ بُرَيْدَةَ بن الحصيب، أَنَّ النَّبِيَّ صلى الله عليه وسلم  اشْتَهَى تَمْرًا، فَأَرْسَلَ بَعْضَ أَزْوَاجِهِ –وَلَا أَرَاهَا إِلَّا أُمَّ سَلَمَةَ- بِصَاعَيْنِ مِنْ تَمْرٍ، فَأَتَوْا بِصَاعٍ مِنْ عَجْوَةٍ، فَلَمَّا رَآهُ النَّبِيُّ صلى الله عليه وسلم  أَنْكَرَهُ، فَقَالَ: مِنْ أَيْنَ لَكُمْ هَذَا؟ قَالُوا: بَعَثْنَا بِصَاعَيْنِ فَأَتَيْنَا بِصَاعٍ فَقَالَ: رُدُّوهُ، فَلَا حَاجَةَ لِي فِيهِ."],"takhrij":"حسن: رواه الطحاوي في شرح معاني الآثار (5761) –والسياق له-، والطبراني في الأوسط –مجمع البحرين (2026) كلاهما من طريق يحيى بن معين، حدثنا الفضل بن حبيب السراج، حدثنا حيّان أبو زهير، عن ابن بريدة، عن أبيه قال: فذكره.","grade":"حسن","chapter_ar":"باب النهي عن بيع التمر بالتمر أو الطعام بالطعام متفاضلًا","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tahawi in Sharh Ma‘ani al-Athar (4/66), and al-Tabarani in al-Awsat as cited in Majma‘ al-Bahrayn (2026).","chapter_en":"The Prohibition of Selling Dates for Dates or Food for Food with Inequality","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":12,"content":{"translation":{"en":["Buraydah ibn al-Husayb reported that the Prophet ﷺ desired some dates, so one of his wives, and I think it was Umm Salamah, sent out two measures of dates, and they brought back one measure of fine dates. When the Prophet ﷺ saw it, he disapproved and said: “Where did you get this?” They said: “We sent two measures and brought back one.” He said: “Return it. I have no need for it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطحاوي في شرح معاني الآثار (5761)، والطبراني في الأوسط - مجمع البحرين (2026)."},{"num":5715,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أُتِيَ بِتَمْرٍ رَيَّانٍ، فَقَالَ: أَنَّى لَكُمْ هَذَا؟ فَقَالُوا: كَانَ عِنْدَنَا تَمْرُ بَعْلٍ، فَبِعْنَا صَاعَيْنِ بِصَاعٍ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: رُدُّوهُ عَلَى صَاحِبِهِ، فَبِيعُوهُ بِعَيْنٍ، ثُمَّ ابْتَاعُوا التَّمْرَ."],"takhrij":"حسن: رواه البزار (6886)، والطبراني في الأوسط –مجمع البحرين (2027) كلاهما من طريق روح بن عبادة، حدثنا أبو الفضل كثير بن يسار، حدثنا ثابت البناني، حدثنا أنس بن مالك قال: فذكره. والسياق للطبراني.","grade":"حسن","chapter_ar":"باب النهي عن بيع التمر بالتمر أو الطعام بالطعام متفاضلًا","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzar (6886), and al-Tabarani in al-Awsat as cited in Majma‘ al-Bahrayn (2027).","chapter_en":"The Prohibition of Selling Dates for Dates or Food for Food with Inequality","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":12,"content":{"translation":{"en":["Anas ibn Malik reported that the Messenger of Allah ﷺ was brought well-watered, plump dates, and he said: “How did you get this?” They said: “We had ba‘l dates from palms that did not require ordinary irrigation, so we sold two measures for one measure.” The Messenger of Allah ﷺ said: “Return it to its owner. Sell the other dates for money, then buy the dates.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار (6886)، والطبراني في الأوسط - مجمع البحرين (2027)."},{"num":5716,"demo":false,"sanad":"","matn":["عَنْ مَعْمَرِ بْنِ عَبْدِ اللَّهِ  أَنَّهُ أَرْسَلَ غُلَامَهُ بِصَاعِ قَمْحٍ، فَقَالَ: بِعْهُ، ثُمَّ اشْتَرِ بِهِ شَعِيرًا، فَذَهَبَ الْغُلَامُ، فَأَخَذَ صَاعًا وَزِيَادَةَ بَعْضِ صَاعٍ، فَلَمَّا جَاءَ مَعْمَرًا أَخْبَرَهُ بِذَلِكَ، فَقَالَ لَهُ مَعْمَرٌ: لِمَ فَعَلْتَ ذَلِكَ؟ انْطَلِقْ، فَرُدَّهُ، وَلَا تَأْخُذَنَّ إِلَّا مِثْلًا بِمِثْلٍ، فَإِنِّي كُنْتُ أَسْمَعُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: الطَّعَامُ بِالطَّعَامِ مِثْلًا بِمِثْلٍ. قَالَ: وَكَانَ طَعَامُنَا يَوْمَئِذٍ الشَّعِيرَ، قِيلَ لَهُ: فَإِنَّهُ لَيْسَ بِمِثْلِهِ؟ قَالَ: إِنِّي أَخَافُ أَنْ يُضَارِعَ."],"takhrij":"صحيح: رواه مسلم في المساقاة (1592) من طريق ابن وهب، عن عمرو بن الحارث، أن أبا النضر حدثه، أن بسر بن سعيد حدثه عن معمر بن عبد الله فذكره.","grade":"صحيح","chapter_ar":"باب من يرى أن البر والشعير صنفًا واحدًا","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Muslim (1592).","chapter_en":"The View of Those Who Consider Wheat and Barley to Be One Category","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":13,"content":{"translation":{"en":["Ma‘mar ibn Abdullah sent his servant with one measure of wheat and said: “Sell it, then buy barley with it.” The servant went and took one measure plus some extra. When he came back and informed Ma‘mar, Ma‘mar said: “Why did you do that? Go and return it, and do not take except equal for equal, for I used to hear the Messenger of Allah ﷺ say: ‘Food for food must be equal for equal.’” He said: Their food at that time was barley. It was said to him: “But it is not the same as wheat.” He said: “I fear that it is similar enough to fall under the same ruling.”"]},"buhuth":{"en":["Its meaning: “Is similar” means resembles it. The meaning is: I fear that it may fall under the same legal meaning as its like."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1592)."},{"num":5717,"demo":false,"sanad":"","matn":["عَنْ أُسَامَةَ بْنِ زَيْدٍ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  لَا رِبًا فِيمَا كَانَ يَدًا بِيَدٍ."],"takhrij":"صحيح: رواه مسلم في المساقاة (1596: 103) من طرق عن وهيب، حدثنا ابن طاوس، عن أبيه، عن ابن عباس، عن أسامة بن زيد فذكره.","grade":"صحيح","chapter_ar":"باب من قال: إنما الربا في النسيئة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1596, no. 103).","chapter_en":"Those Who Said That Usury Applies Only in Delayed Exchange","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":14,"content":{"translation":{"en":["Usamah ibn Zayd reported that the Messenger of Allah ﷺ said: “There is no usury when it is hand to hand.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1596: 103)."},{"num":5718,"demo":false,"sanad":"","matn":["عَنْ أَبِي صَالِحٍ قَالَ: سَمِعْتُ أَبَا سَعِيدٍ الْخُدْرِيَّ يَقُولُ:  الدِّينَارُ بِالدِّينَارِ وَالدِّرْهَمُ بِالدِّرْهَمِ، مِثْلًا بِمِثْلٍ، مَنْ زَادَ أَوِ ازْدَادَ فَقَدْ أَرْبَى، فَقُلْتُ لَهُ: إِنَّ ابْنَ عَبَّاسٍ يَقُولُ غَيْرَ هَذَا، فَقَالَ: لَقَدْ لَقِيتُ ابْنَ عَبَّاسٍ، فَقُلْتُ: أَرَأَيْتَ هَذَا الَّذِي تَقُولُ، أَشَيْءٌ سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَوْ وَجَدْتَهُ فِي كِتَابِ اللَّهِ عَزَّ وَجَلَّ؟ فَقَالَ: لَمْ أَسْمَعْهُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَلَمْ أَجِدْهُ فِي كِتَابِ اللَّهِ، وَلَكِنْ حَدَّثَنِي أُسَامَةُ بْنُ زَيْدٍ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: الرِّبَا فِي النَّسِيئَةِ."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2178-2179)، ومسلم في المساقاة (1596: 101) كلاهما من طريق عمرو بن دينار، عن أبي صالح قال: سمعت أبا سعيد الخدري يقول فذكره. واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب من قال: إنما الربا في النسيئة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon. Narrated by al-Bukhari (2178–2179) and Muslim (1596, no. 101). The wording here is from Muslim. In a wording in al-Bukhari: “There is no usury except in delayed exchange.”","chapter_en":"Those Who Said That Usury Applies Only in Delayed Exchange","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":14,"content":{"translation":{"en":["Abu Salih reported: I heard Abu Saeed al-Khudri say, “A dinar for a dinar and a dirham for a dirham must be equal for equal. Whoever gives more or takes more has engaged in usury.” I said to him, “Ibn Abbas says something different from this.” He said, “I met Ibn Abbas and said to him: Is this statement of yours something you heard from the Messenger of Allah ﷺ, or something you found in the Book of Allah, the Mighty and Majestic? He replied: I did not hear it from the Messenger of Allah ﷺ, nor did I find it in the Book of Allah, but Usamah ibn Zayd told me that the Prophet ﷺ said: ‘Usury is in delayed exchange.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2178-2179)، ومسلم (1596: 101). واللفظ لمسلم. وفي لفظ للبخاري قال: (( لا ربا إلا في النسيئة ))."},{"num":5719,"demo":false,"sanad":"","matn":["عن عطاء بْنِ أَبِي رَبَاحٍ أَنَّ أَبَا سَعِيدٍ الْخُدْرِيَّ لَقِيَ ابْنَ عَبَّاسٍ، فَقَالَ لَهُ: أَرَأَيْتَ قَوْلَكَ فِي الصَّرْفِ، أَشَيْئًا سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَمْ شَيْئًا وَجَدْتَهُ فِي كِتَابِ اللَّهِ عَزَّ وَجَلَّ؟ فَقَالَ ابْنُ عَبَّاسٍ: كَلَّا، لَا أَقُولُ، أَمَّا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَنْتُمْ أَعْلَمُ بِهِ، وَأَمَّا كِتَابُ اللَّهِ فَلَا أَعْلَمُهُ، وَلَكِنْ حَدَّثَنِي أُسَامَةُ بْنُ زَيْدٍ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَلَا إِنَّمَا الرِّبَا فِي النَّسِيئَةِ."],"takhrij":"صحيح: رواه مسلم في المساقاة (1596: 104) عن الحكم بن موسى، حدثنا هقل، عن الأوزاعى قال: حدثنى عطاء بن أبي رباح فذكره.","grade":"صحيح","chapter_ar":"باب من قال: إنما الربا في النسيئة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Muslim (1596, no. 104).","chapter_en":"Those Who Said That Usury Applies Only in Delayed Exchange","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":14,"content":{"translation":{"en":["Ata ibn Abi Rabah reported that Abu Saeed al-Khudri met Ibn Abbas and said to him: “This opinion of yours regarding currency exchange, is it something you heard from the Messenger of Allah ﷺ, or something you found in the Book of Allah, the Mighty and Majestic?” Ibn Abbas replied: “Neither. I do not claim that. As for the Messenger of Allah ﷺ, you know more about him than I do, and as for the Book of Allah, I do not know it there. But Usamah ibn Zayd told me that the Messenger of Allah ﷺ said: ‘Indeed, usury is only in delayed exchange.’”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1596: 104)."},{"num":5720,"demo":false,"sanad":"","matn":["عَنْ أَبِي نَضْرَةَ قَالَ:  سَأَلْتُ ابْنَ عُمَرَ وَابْنَ عَبَّاسٍ عَنِ الصَّرْفِ، فَلَمْ يَرَيَا بِهِ بَأْسًا، فَإِنِّي لَقَاعِدٌ عِنْدَ أَبِي سَعِيدٍ الْخُدْرِيِّ، فَسَأَلْتُهُ عَنِ الصَّرْفِ، فَقَالَ: مَا زَادَ فَهُوَ رِبًا، فَأَنْكَرْتُ ذَلِكَ لِقَوْلِهِمَا، فَقَالَ: لَا أُحَدِّثُكَ إِلَّا مَا سَمِعْتُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، جَاءَهُ صَاحِبُ نَخْلِهِ بِصَاعٍ مِنْ تَمْرٍ طَيِّبٍ، وَكَانَ تَمْرُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ هَذَا اللَّوْنَ، فَقَالَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَّى لَكَ هَذَا؟ قَالَ: انْطَلَقْتُ بِصَاعَيْنِ، فَاشْتَرَيْتُ بِهِ هَذَا الصَّاعَ، فَإِنَّ سِعْرَ هَذَا فِي السُّوقِ كَذَا، وَسِعْرَ هَذَا كَذَا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: وَيْلَكَ، أَرْبَيْتَ، إِذَا أَرَدْتَ ذَلِكَ فَبِعْ تَمْرَكَ بِسِلْعَةٍ، ثُمَّ اشْتَرِ بِسِلْعَتِكَ أَيَّ تَمْرٍ شِئْتَ. قَالَ أَبُو سَعِيدٍ: فَالتَّمْرُ بِالتَّمْرِ أَحَقُّ أَنْ يَكُونَ رِبًا أَمِ الْفِضَّةُ بِالْفِضَّةِ؟ قَالَ: فَأَتَيْتُ ابْنَ عُمَرَ بَعْدُ، فَنَهَانِي، وَلَمْ آتِ ابْنَ عَبَّاسٍ، قَالَ: فَحَدَّثَنِي أَبُو الصَّهْبَاءِ أَنَّهُ سَأَلَ ابْنَ عَبَّاسٍ عَنْهُ بِمَكَّةَ، فَكَرِهَهُ."],"takhrij":"صحيح: رواه مسلم في المساقاة (1594: 100) عن إسحاق بن إبراهيم، أخبرنا عبد الأعلى، أخبرنا داود، عن أبي نضرة فذكره.","grade":"صحيح","chapter_ar":"باب من قال: إنما الربا في النسيئة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Muslim (1594, no. 100).","chapter_en":"Those Who Said That Usury Applies Only in Delayed Exchange","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":14,"content":{"translation":{"en":["Abu Nadrah reported: I asked Ibn Umar and Ibn Abbas about currency exchange, and they saw no problem with it. Then while I was sitting with Abu Saeed al-Khudri, I asked him about exchange, and he said, “Any excess is usury.” I found that strange because of what those two had said. He replied, “I will tell you only what I heard from the Messenger of Allah ﷺ. The owner of a date orchard came to him with one measure of fine dates, and the dates of the Prophet ﷺ were not of that kind. So the Prophet ﷺ said to him: ‘How did you get this?’ He said: I went with two measures and bought this one measure, because the price of this kind in the market is such-and-such, and the price of that kind is such-and-such. The Messenger of Allah ﷺ said: ‘Woe to you, you have dealt in usury! If you want that, then sell your dates for another commodity, then buy whichever dates you wish with that commodity.’” Abu Saeed then said: “If dates for dates are usury, then silver for silver is even more deserving of being called usury.” So afterwards I went to Ibn Umar, and he forbade me from it, and I did not go to Ibn Abbas. Then Abu al-Sahba told me that he asked Ibn Abbas about it in Makkah, and he also disliked it."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1594: 100)."},{"num":5721,"demo":false,"sanad":"","matn":["عَنْ أَبِي نَضْرَةَ قَالَ:  سَأَلْتُ ابْنَ عَبَّاسٍ عَنِ الصَّرْفِ، فَقَالَ: أَيَدًا بِيَدٍ؟ قُلْتُ: نَعَمْ. قَالَ: فَلَا بَأْسَ بِهِ. فَأَخْبَرْتُ أَبَا سَعِيدٍ، فَقُلْتُ: إِنِّي سَأَلْتُ ابْنَ عَبَّاسٍ عَنِ الصَّرْفِ، فَقَالَ: أَيَدًا بِيَدٍ؟ قُلْتُ: نَعَمْ. قَالَ: فَلَا بَأْسَ بِهِ. قَالَ: أَوَقَالَ ذَلِكَ؟ إِنَّا سَنَكْتُبُ إِلَيْهِ، فَلَا يُفْتِيكُمُوهُ. قَالَ: فَوَاللهِ لَقَدْ جَاءَ بَعْضُ فِتْيَانِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِتَمْرٍ، فَأَنْكَرَهُ، فَقَالَ: كَأَنَّ هَذَا لَيْسَ مِنْ تَمْرِ أَرْضِنَا. قَالَ: كَانَ فِي تَمْرِ أَرْضِنَا (أَوْ فِي تَمْرِنَا) الْعَامَ بَعْضُ الشَّيْءِ، فَأَخَذْتُ هَذَا، وَزِدْتُ بَعْضَ الزِّيَادَةِ، فَقَالَ: أَضْعَفْتَ، أَرْبَيْتَ، لَا تَقْرَبَنَّ هَذَا، إِذَا رَابَكَ مِنْ تَمْرِكَ شَيْءٌ فَبِعْهُ، ثُمَّ اشْتَرِ الَّذِي تُرِيدُ مِنَ التَّمْرِ."],"takhrij":"صحيح: رواه مسلم في المساقاة (1594: 99) عن عمرو الناقد، حدثنا إسماعيل بن إبراهيم، عن سعيد الجريري، عن أبي نضرة قال فذكره.","grade":"صحيح","chapter_ar":"باب من قال: إنما الربا في النسيئة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Muslim (1594, no. 99).","chapter_en":"Those Who Said That Usury Applies Only in Delayed Exchange","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":14,"content":{"translation":{"en":["Abu Nadrah reported: I asked Ibn Abbas about exchange, and he said, “Is it hand to hand?” I said, “Yes.” He said, “Then there is no problem with it.” I informed Abu Saeed and said, “I asked Ibn Abbas about exchange, and he said: Is it hand to hand? I said yes. He said: Then there is no problem with it.” Abu Saeed said, “Did he really say that? We will write to him so that he does not continue giving you that ruling.” Then he said: “By Allah, one of the young men of the Messenger of Allah ﷺ once brought dates, and he disapproved of them and said: ‘It seems this is not from the dates of our land.’ The man said: There was something wrong with our land’s dates this year, so I took these and added some extra. The Prophet ﷺ said: ‘You doubled it? You have engaged in usury? Do not come near this. If something about your dates troubles you, then sell them, and then buy whatever kind of dates you want.’”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1594: 99)."},{"num":5722,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ أَبَا سَعِيدٍ، حَدَّثَهُ مِثْلَ، ذَلِكَ حَدِيثًا عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَلَقِيَهُ عَبْدُ اللَّهِ بْنُ عُمَرَ، فَقَالَ: يَا أَبَا سَعِيدٍ، مَا هَذَا الَّذِي تُحَدِّثُ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ فَقَالَ أَبُو سَعِيدٍ: فِي الصَّرْفِ؟ سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: الذَّهَبُ بِالذَّهَبِ مِثْلاً بِمِثْلٍ، وَالْوَرِقُ بِالْوَرِقِ مِثْلاً بِمِثْلٍ."],"takhrij":"صحيح: رواه البخاري في البيوع (2176) عن عبيدالله بن سعيد، حدثنا عمي، حدثنا ابن أخي الزهري، عن عمه قال: حدثني سالم بن عبد الله، عن عبد الله بن عمر فذكره.","grade":"صحيح","chapter_ar":"باب من قال: إنما الربا في النسيئة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by al-Bukhari (2176).","chapter_en":"Those Who Said That Usury Applies Only in Delayed Exchange","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":14,"content":{"translation":{"en":["Abdullah ibn Umar reported that Abu Saeed al-Khudri narrated to him a similar hadith from the Messenger of Allah ﷺ. Then Abdullah ibn Umar met him and said: “Abu Saeed, what is this that you narrate from the Messenger of Allah ﷺ?” Abu Saeed replied: “About exchange? I heard the Messenger of Allah ﷺ say: ‘Gold for gold must be equal for equal, and silver for silver must be equal for equal.’”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (2176)."},{"num":5723,"demo":false,"sanad":"","matn":["عن أَبِي الجوزاء قَالَ: سَمِعْتُ ابْنَ عَبَّاسٍ يُفْتِي فِي الصَّرْفِ، قَالَ: فَأَفْتَيْتُ بِهِ زَمَانًا، قَالَ: ثُمَّ لَقِيتُهُ، فَرَجَعَ عَنْهُ. قَالَ: فَقُلْتُ لَهُ: وَلِمَ؟ فَقَالَ: إِنَّمَا هُوَ رَأْيٌ رَأَيْتُهُ. حَدَّثَنِي أَبُو سَعِيدٍ الْخُدْرِيُّ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْهُ."],"takhrij":"صحيح: رواه الإمام أحمد (11447) عن وكيع، حدثنا سليمان بن علي الربعي قال: سمعت أبا الجوزاء فذكره.","grade":"صحيح","chapter_ar":"باب من قال: إنما الربا في النسيئة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Imam Ahmad (11447). Ahmad also narrated it (11479) with the wording: “I asked Ibn Abbas about hand-to-hand exchange, and he said: there is no problem with two for one, more than that or less. Then I performed Hajj another time while the shaykh was still alive, and I came to him and asked him about exchange, and he said: weight for weight. I said: You had given me the ruling of two for one, and I kept giving verdicts with it since you told me that. He said: That was from my own opinion, but now Abu Saeed al-Khudri narrates from the Messenger of Allah ﷺ, so I abandoned my opinion for the hadith of the Messenger of Allah ﷺ.” Its chain is authentic.","chapter_en":"Those Who Said That Usury Applies Only in Delayed Exchange","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":14,"content":{"translation":{"en":["Abu al-Jawza reported: I heard Ibn Abbas giving legal rulings allowing currency exchange in that way, and I gave verdicts with it for some time. Then I met him again, and he had gone back from that view. I said to him: “Why?” He replied: “It was only an opinion I had formed. Abu Saeed al-Khudri informed me that the Messenger of Allah ﷺ forbade it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (11447). ورواه أيضا ahmad(11479) وجاء فيه: سألت ابن عباس عن الصرف يدا بيد، فقال: لا بأس بذلك، اثنين بواحد، أكثر من ذلك وأقل. قال: ثم حججت مرة أخرى، والشيخ حي، فأتيته، فسألته عن الصرف، فقال: وزنا بوزن. قال: فقلت: إنك قد أفتيتني اثنين بواحد، فلم أزل أفتي به منذ أفتيتني. فقال: إن ذلك كان عن رأيي، وهذا أبو سعيد الخدري يحدث عن رسول الله ﷺ، فتركت رأيي إلى حديث رسول الله ﷺ. وإسناده صحيح."},{"num":5724,"demo":false,"sanad":"","matn":["عَنْ أَبِي الزُّبَيْرِ الْمَكِّيِّ، قَالَ: سَمِعْتُ أَبَا سَعِيدٍ السَّاعِدِيَّ، وَابْنَ عَبَّاسٍ يُفْتِي الدِّينَارُ بِالدِّينَارَيْنِ. فَقَالَ لَهُ أَبُو أُسَيْدٍ السَّاعِدِيُّ وَأَغْلَظَ لَهُ، قَالَ: فَقَالَ ابْنُ عَبَّاسٍ: مَا كُنْتُ أَظُنُّ أَنَّ أَحَدًا يَعْرِفُ قَرَابَتِي مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ لِي مِثْلَ هَذَا يَا أَبَا أُسَيْدٍ، فَقَالَ أَبُو أُسَيْدٍ: أَشْهَدُ لَسَمِعْتُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: الدِّينَارُ بِالدِّينَارِ، وَالدِّرْهَمُ بِالدِّرْهَمِ، وَصَاعُ حِنْطَةٍ بِصَاعِ حِنْطَةٍ، وَصَاعُ شَعِيرٍ بِصَاعِ شَعِيرٍ، وَصَاعُ مِلْحٍ بِصَاعِ مِلْحٍ، لَا فَضْلَ بَيْنَهُمَا فِي شَيْءٍ مِنْ ذَلِكَ، فَقَالَ ابْنُ عَبَّاسٍ: إِنَّمَا هَذَا شَيْءٌ كُنْتُ أَقُولُهُ، وَلَمْ أَسْمَعْ فِيهِ بِشَيْءٍ."],"takhrij":"حسن: رواه ابنُ أبي خيثمة في التاريخ الكبير (3444)، والطبراني في الكبير (19/ح 595)، والحاكم (2193) كلهم من طريق عتيق بن يعقوب الزبيري، ثنا عبدالعزيز بن محمد، حدثني إبراهيم بن طهمان، عن أبي الزبير المكي قال: سمعت أبا سعيد الساعدي و ابن عباس يفتي فذكره.","grade":"حسن","chapter_ar":"باب من قال: إنما الربا في النسيئة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Abi Khaythamah in al-Tarikh al-Kabir (3444), al-Tabarani in al-Kabir (19/268), and al-Hakim (2193).","chapter_en":"Those Who Said That Usury Applies Only in Delayed Exchange","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":14,"content":{"translation":{"en":["Abu al-Zubayr al-Makki reported: I heard Abu Usayd al-Saidi while Ibn Abbas was giving the ruling that one dinar may be exchanged for two dinars. Abu Usayd spoke sternly to him. Ibn Abbas then said: “I never expected that anyone who knew my closeness to the Messenger of Allah ﷺ would speak to me like this, Abu Usayd.” Abu Usayd said: “I testify that I heard from the Messenger of Allah ﷺ: ‘A dinar for a dinar, a dirham for a dirham, one measure of wheat for one measure of wheat, one measure of barley for one measure of barley, and one measure of salt for one measure of salt, with no excess in any of that.’” So Ibn Abbas said: “This was only something I used to say, and I had heard nothing on it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن أبي خيثمة في التاريخ الكبير (3444)، والطبراني في الكبير (19/ح 595)، والحاكم (2193)."},{"num":5725,"demo":false,"sanad":"","matn":["عَنْ أَبِي الْمِنْهَالِ قَالَ: سَأَلْتُ الْبَرَاءَ بْنَ عَازِبٍ وَزَيْدَ بْنَ أَرْقَمَ عَنِ الصَّرْفِ، وكل وَاحِدٍ مِنْهُمَا يَقُولُ: هَذَا خَيْرٌ مِنِّي، فَكِلاَهُمَا يَقُولُ: \"نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ بَيْعِ الذَّهَبِ بِالْوَرِقِ دَيْنًا\"."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2180، 2181)، ومسلم في المساقاة (1589) كلاهما من حديث شعبة، عن حبيب بن أبي ثابت قال: سمعت أبا المنهال فذكره.","grade":"متفق عليه","chapter_ar":"باب جواز بيع الذهب بالفضة أو العكس إذا كان يدًا بيد","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon. Narrated by al-Bukhari (2180, 2181) and Muslim (1589).","chapter_en":"The Permissibility of Selling Gold for Silver, or Silver for Gold, If It Is Hand to Hand","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":15,"content":{"translation":{"en":["Abu al-Minhal reported: I asked al-Bara ibn Azib and Zayd ibn Arqam about exchange, and each one of them said, “This one is better than me.” Yet both of them said: “The Messenger of Allah ﷺ forbade selling gold for silver on delayed payment.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (2180، 2181)، ومسلم (1589)."},{"num":5726,"demo":false,"sanad":"","matn":["عَنْ عَمْرٍو، سَمِعَ أَبَا الْمِنْهَالِ عَبْدَ الرَّحْمَنِ بْنَ مُطْعِمٍ، قَالَ: بَاعَ شَرِيكٌ لِي دَرَاهِمَ فِي السُّوقِ نَسِيئَةً، فَقُلْتُ: سُبْحَانَ اللَّهِ! أَيَصْلُحُ هَذَا؟ فَقَالَ: سُبْحَانَ اللَّهِ، وَاللَّهِ لَقَدْ بِعْتُهَا فِي السُّوقِ فَمَا عَابَهُ أَحَدٌ، فَسَأَلْتُ الْبَرَاءَ بْنَ عَازِبٍ، فَقَالَ قَدِمَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَنَحْنُ نَتَبَايَعُ هَذَا الْبَيْعَ، فَقَالَ: مَا كَانَ يَدًا بِيَدٍ فَلَيْسَ بِهِ بَأْسٌ، وَمَا كَانَ نَسِيئَةً فَلاَ يَصْلُحُ. وَالْقَ زَيْدَ بْنَ أَرْقَمَ، فَاسْأَلْهُ؛ فَإِنَّهُ كَانَ أَعْظَمَنَا تِجَارَةً، فَسَأَلْتُ زَيْدَ بْنَ أَرْقَمَ، فَقَالَ مِثْلَهُ."],"takhrij":"متفق عليه: رواه البخاري في المناقب (3939، 3940) عن علي ابن المديني، ومسلم في المساقاة (1589) عن محمد بن حاتم بن ميمون - كلاهما عن سفيان بن عيينة، عن عمرو، سمع أبا المنهال قال فذكره. ولفظهما سواء.","grade":"متفق عليه","chapter_ar":"باب جواز بيع الذهب بالفضة أو العكس إذا كان يدًا بيد","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon. Narrated by al-Bukhari (3939, 3940) and Muslim (1589). Their wording is nearly the same. This is understood to refer to exchanging two different categories.","chapter_en":"The Permissibility of Selling Gold for Silver, or Silver for Gold, If It Is Hand to Hand","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":15,"content":{"translation":{"en":["Abu al-Minhal Abd al-Rahman ibn Mutim reported: A partner of mine sold silver coins in the market on delayed payment. I said: “Glory be to Allah, can this be valid?” He said: “Glory be to Allah, by Allah, I sold it in the market and no one criticized it.” So I asked al-Bara ibn Azib, and he said: “The Prophet ﷺ came to Madinah while we were doing this kind of transaction, and he said: ‘What is hand to hand is permissible, but what is delayed is not valid.’” Then he said: “Go to Zayd ibn Arqam and ask him, for he was greater than us in trade.” So I asked Zayd ibn Arqam, and he said the same."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3939، 3940)، ومسلم (1589). ولفظهما سواء. ويحمل هذا على بيع الجنسين."},{"num":5727,"demo":false,"sanad":"","matn":["عَنْ أَبِي الْمِنْهَالِ قَالَ: كُنْتُ أَتَّجِرُ فِي الصَّرْفِ، فَسَأَلْتُ الْبَرَاءَ بْنَ عَازِبٍ، وَزَيْدَ بْنَ أَرْقَمَ عَنِ الصَّرْفِ، فَقَالاَ: كُنَّا تَاجِرَيْنِ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، فَسَأَلْنَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الصَّرْفِ، فَقَالَ: إِنْ كَانَ يَدًا بِيَدٍ فَلاَ بَأْسَ. وَإِنْ كَانَ نَسَاءً فَلاَ يَصْلُحُ."],"takhrij":"صحيح: رواه البخاري في البيوع (2060، 2061) من طريقين عن ابن جريج قال: أخبرني عمرو بن دينار، عن أبي المنهال فذكره.","grade":"صحيح","chapter_ar":"باب جواز بيع الذهب بالفضة أو العكس إذا كان يدًا بيد","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by al-Bukhari (2060, 2061).","chapter_en":"The Permissibility of Selling Gold for Silver, or Silver for Gold, If It Is Hand to Hand","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":15,"content":{"translation":{"en":["Abu al-Minhal reported: I used to trade in currency exchange, so I asked al-Bara ibn Azib and Zayd ibn Arqam about exchange. They said: “We were traders in the time of the Messenger of Allah ﷺ, so we asked the Messenger of Allah ﷺ about exchange, and he said: ‘If it is hand to hand, there is no problem, but if it is delayed, it is not valid.’”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (2060، 2061)."},{"num":5728,"demo":false,"sanad":"","matn":["عَنْ أَبِي الْمِنْهَالِ، أَنَّ زَيْدَ بْنَ أَرْقَمَ، وَالْبَرَاءَ بْنَ عَازِبٍ رَضِيَ اللَّهُ عَنْهُمْ، كَانَا شَرِيكَيْنِ، فَاشْتَرَيَا فِضَّةً بِنَقْدٍ وَنَسِيئَةً، فَبَلَغَ ذَلِكَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَمَرَهُمَا أَنَّ مَا كَانَ بِنَقْدٍ فَأَجِيزُوهُ، وَمَا كَانَ بِنَسِيئَةٍ فَرُدُّوهُ."],"takhrij":"صحيح: رواه الإمام أحمد (19307) عن يحيى بن أبي بكير، حدثنا إبراهيم بن نافع قال: سمعت عمرو بن دينار يذكر عن أبي المنهال فذكر الحديث.","grade":"صحيح","chapter_ar":"باب جواز بيع الذهب بالفضة أو العكس إذا كان يدًا بيد","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Imam Ahmad (19307).","chapter_en":"The Permissibility of Selling Gold for Silver, or Silver for Gold, If It Is Hand to Hand","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":15,"content":{"translation":{"en":["Abu al-Minhal reported that Zayd ibn Arqam and al-Bara ibn Azib were partners, and they bought silver both for immediate payment and on delayed payment. That reached the Prophet ﷺ, so he ordered them to approve what had been done with immediate payment, and to return what had been done on delayed payment."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (19307)."},{"num":5729,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، وَأَبِي سَعِيدٍ، وَجَابِرٍ، اثْنَيْنِ مِنْ هَؤُلَاءِ الثَّلَاثَةِ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، نَهَى عَنِ الصَّرْفِ."],"takhrij":"صحيح: رواه أحمد (9638) عن يحيى، عن أشعث، عن محمد، عن أبي صالح ذكوان، عن هؤلاء فذكروا الحديث.","grade":"صحيح","chapter_ar":"باب جواز بيع الذهب بالفضة أو العكس إذا كان يدًا بيد","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Ahmad (9638).","chapter_en":"The Permissibility of Selling Gold for Silver, or Silver for Gold, If It Is Hand to Hand","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":15,"content":{"translation":{"en":["It is reported from Abu Hurayrah, Abu Saeed, and Jabir, from two of these three, that the Prophet ﷺ forbade exchange."]},"buhuth":{"en":["Explanation:","His saying, “He forbade exchange,” means exchange with delay, or with increase when the two items are of the same kind."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (9638). وقوله: (( نهى عن الصرف )) أي نسيئة أو زيادة مع اتحاد الجنسين."},{"num":5730,"demo":false,"sanad":"","matn":["عن فَضَالَةَ بن عبيد الأنصاري يَقُولُ:  أُتِيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ بِخَيْبَرَ بِقِلَادَةٍ فِيهَا خَرَزٌ وَذَهَبٌ، وَهِيَ مِنَ الْمَغَانِمِ تُبَاعُ، فَأَمَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالذَّهَبِ الَّذِي فِي الْقِلَادَةِ، فَنُزِعَ وَحْدَهُ، ثُمَّ قَالَ لَهُمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الذَّهَبُ بِالذَّهَبِ وَزْنًا بِوَزْنٍ."],"takhrij":"صحيح: رواه مسلم في المساقاة (1591) عن أبي الطاهر أحمد بن عمرو بن سرح، أخبرنا ابن وهب، أخبرنى أبو هانئ الخولانى، أنه سمع على بن رباح اللخمى يقول: سمعت فضالة بن عبيدالأنصاري فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن بيع القلادة فيها ذهب وخرز","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Muslim (1591).","chapter_en":"The Prohibition of Selling a Necklace That Contains Gold and Beads","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":16,"content":{"translation":{"en":["Fadalah ibn Ubayd al-Ansari reported: A necklace containing beads and gold, from the spoils of war, was brought to the Messenger of Allah ﷺ at Khaybar to be sold. The Messenger of Allah ﷺ ordered that the gold in the necklace be removed and separated, then he said to them: “Gold for gold must be weight for weight.”"]},"buhuth":{"en":["In another narration from Fadalah ibn Ubayd: “On the day of Khaybar I bought a necklace for twelve dinars. It contained gold and beads. I separated it and found that the gold in it was worth more than twelve dinars. I mentioned that to the Prophet ﷺ, and he said: ‘It should not be sold until it is separated.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1591). ورواه من وجه آخر عن فضالة بن عبيد قال: اشتريت يوم خيبر قلادة باثني عشر دينارا، فيها ذهب وخرز، ففصلتها فوجدت فيها أكثر من اثني عشر دينارا، فذكرت ذلك للنبي ﷺ، فقال: (( لا تباع حتى تفصل ))."},{"num":5731,"demo":false,"sanad":"","matn":["عَنْ حَنَشٍ أَنَّهُ قَالَ:  كُنَّا مَعَ فَضَالَةَ بْنِ عُبَيْدٍ فِي غَزْوَةٍ، فَطَارَتْ لِي وَلِأَصْحَابِي قِلَادَةٌ فِيهَا ذَهَبٌ وَوَرِقٌ وَجَوْهَرٌ، فَأَرَدْتُ أَنْ أَشْتَرِيَهَا، فَسَأَلْتُ فَضَالَةَ بْنَ عُبَيْدٍ، فَقَالَ: انْزِعْ ذَهَبَهَا، فَاجْعَلْهُ فِي كِفَّةٍ، وَاجْعَلْ ذَهَبَكَ فِي كِفَّةٍ، ثُمَّ لَا تَأْخُذَنَّ إِلَّا مِثْلًا بِمِثْلٍ، فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ كَانَ يُؤْمِنُ بِاللهِ وَالْيَوْمِ الْآخِرِ فَلَا يَأْخُذَنَّ إِلَّا مِثْلًا بِمِثْلٍ."],"takhrij":"صحيح: رواه مسلم في المساقاة (1591: 92) عن أبي الطاهر، أخبرنا ابن وهب، عن قرة بن عبد الرحمن المعافري وعمرو بن الحارث وغيرهما، أن عامر بن يحيى المعافري أخبرهم عن حنش أنه قال فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن بيع القلادة فيها ذهب وخرز","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Muslim (1591, no. 92).","chapter_en":"The Prohibition of Selling a Necklace That Contains Gold and Beads","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":16,"content":{"translation":{"en":["Hanash reported: We were with Fadalah ibn Ubayd on a military expedition when a necklace containing gold, silver, and jewels was allotted to me and my companions from the booty. I wanted to buy it, so I asked Fadalah ibn Ubayd. He said: “Remove its gold, put it in one scale, and put your gold in another scale, then do not take except equal for equal, for I heard the Messenger of Allah ﷺ say: ‘Whoever believes in Allah and the Last Day must not take except equal for equal.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1591: 92)."},{"num":5732,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله قال: خطب النبي صلى الله عليه وسلم يوم عرفة ببطن الوادي، فمما قال: وربا الجاهلية موضوع، وأول ربا أضع ربانا ربا عباس بن عبدالمطلب، فإنه موضوع كله."],"takhrij":"صحيح: رواه مسلم في الحج، صفة حجة النبي صلى الله عليه وسلم (1218) عن أبي بكر بن أبي شيبة، حدثنا حاتم بن إسماعيل المدني، عن جعفر بن محمد، عن أبيه، عن جابر بن عبدالله فذكره بطوله.","grade":"صحيح","chapter_ar":"باب وضع الربا","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Muslim (1218).","chapter_en":"The Cancellation of Usury","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":17,"content":{"translation":{"en":["Jabir ibn Abdullah reported: The Prophet ﷺ delivered a sermon on the Day of Arafah in the valley, and among what he said was: “The usury of the pre-Islamic period is abolished, and the first usury that I abolish is our usury, the usury of al-Abbas ibn Abd al-Muttalib. It is all abolished.”"]},"buhuth":{"en":["The meaning of cancelling usury is that a person takes back only the principal amount and gives up the usurious increase if the deal was between him and another individual, so he does not take more than the original capital. If the matter is with commercial institutions, then he may take it but should not spend it on himself or his children. Rather, he should direct it to public welfare or to non-Muslims whose hearts may be inclined toward good."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1218)."},{"num":5733,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ الأحوص قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي حَجَّةِ الْوَدَاعِ يَقُولُ: أَلاَ أن كُلَّ رِبًا مِنْ رِبَا الْجَاهِلِيَّةِ مَوْضُوعٌ، لَكُمْ رؤوس أَمْوَالِكُمْ لاَ تَظْلِمُونَ، وَلاَ تُظْلَمُونَ."],"takhrij":"حسن: رواه أبو داود (3334)، والترمذي (3087)، وابن ماجه (1851)، وأحمد (15507) كلهم من طريق شبيب بن غرقدة البارقي، عن سليمان بن عمرو بن الأحوص، عن أبيه فذكره.","grade":"حسن","chapter_ar":"باب وضع الربا","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3334), al-Tirmidhi (3087), and Ahmad (15507). Al-Tirmidhi said: Hasan Sahih.","chapter_en":"The Cancellation of Usury","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":17,"content":{"translation":{"en":["Amr ibn al-Ahwas reported: I heard the Messenger of Allah ﷺ say during the Farewell Pilgrimage: “Indeed, every form of usury from the pre-Islamic period is abolished. You shall have your principal sums. You will neither wrong nor be wronged.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3334)، والترمذي (3087)، وأحمد (15507). قال الترمذي: حسن صحيح."},{"num":5734,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ الْمُزَابَنَةِ. وَالْمُزَابَنَةُ اشْتِرَاءُ الثَّمَرِ بِالتَّمْرِ كَيْلاً، وَبَيْعُ الْكَرْمِ بِالزَّبِيبِ كَيْلاً."],"takhrij":"متفق عليه: رواه مالك في البيوع (23) عن نافع، عـن عبد الله بن عمر فذكره. ورواه البخاري في البيوع (2185)، ومسلم في البيوع (1542) كلاهما من طريق مالك به مثله.","grade":"متفق عليه","chapter_ar":"باب في النهي عن بيع المزابنة والمحاقلة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon. Narrated by Malik (23), al-Bukhari (2185), and Muslim (1542).","chapter_en":"The Prohibition of al-Muzabanah and al-Muhaqalah","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":19,"content":{"translation":{"en":["Abdullah ibn Umar reported that the Messenger of Allah ﷺ forbade al-muzabanah. Al-muzabanah is selling fresh fruit for dried dates by measure, and selling grapes on the vine for raisins by measure."]},"buhuth":{"en":["In another narration by Muslim: “The Messenger of Allah ﷺ forbade al-muzabanah. Al-muzabanah is selling the fruit of date palms for dates by measure, and selling raisins for grapes by measure, and every fruit according to estimation.”","The word muzabanah comes from a root meaning forceful pushing. War is sometimes described with this root because of the force and struggle in it. This type of sale was called muzabanah because each side, in a sense, pushes the other away from his proper right."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (23) والبخاري (2185)، ومسلم (1542). ورواه مسلم من وجه آخر: (( نهى رسول الله ﷺ عن المزابنة. والمزابنة بيع ثمر النخل بالتمر كيلا، وبيع الزبيب بالعنب كيلا، وعلى كل ثمر بخرصه ))."},{"num":5735,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ الْمُزَابَنَةِ وَالْمُحَاقَلَةِ. وَالْمُزَابَنَةُ اشْتِرَاءُ الثَّمَرِ بِالتَّمْرِ فِي رُءُوسِ النَّخْلِ. وَالْمُحَاقَلَةُ كِرَاءُ الأَرْضِ بِالْحِنْطَةِ."],"takhrij":"متفق عليه: رواه مالك في البيوع (24) عن داود بن الحصين، عن أبي سفيان مولى ابن أبي أحمد، عن أبي سعيد الخدري فذكره.","grade":"متفق عليه","chapter_ar":"باب في النهي عن بيع المزابنة والمحاقلة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon. Narrated by Malik (24), al-Bukhari (2186), and Muslim (1546).","chapter_en":"The Prohibition of al-Muzabanah and al-Muhaqalah","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":19,"content":{"translation":{"en":["Abu Saeed al-Khudri reported that the Messenger of Allah ﷺ forbade al-muzabanah and al-muhaqalah. Al-muzabanah is buying fruit on the trees in exchange for dried dates. Al-muhaqalah is renting land in exchange for wheat."]}},"tuhfa":{},"full":1,"dr":1,"rep":[5554],"tks":"متفق عليه: رواه مالك (24) والبخاري (2186)، ومسلم (1546)."},{"num":5736,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: نَهَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْمُحَاقَلَةِ، وَالْمُزَابَنَةِ."],"takhrij":"صحيح: رواه البخاري في البيوع (2187) عن مسدد، حدثنا أبو معاوية، عن الشيباني، عن عكرمة، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب في النهي عن بيع المزابنة والمحاقلة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by al-Bukhari (2187).","chapter_en":"The Prohibition of al-Muzabanah and al-Muhaqalah","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":19,"content":{"translation":{"en":["Ibn Abbas reported: The Prophet ﷺ forbade al-muhaqalah and al-muzabanah."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (2187)."},{"num":5737,"demo":false,"sanad":"","matn":["عَنْ جابر بْنِ عَبْدِ اللَّهِ أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَنْهَى عَنِ الْمُزَابَنَةِ وَالْحُقُولِ، فَقَالَ جَابِرُ بْنُ عَبْدِ اللَّهِ: الْمُزَابَنَةُ الثَّمَرُ بِالتَّمْرِ. وَالْحُقُولُ كِرَاءُ الْأَرْضِ."],"takhrij":"صحيح: رواه مسلم في البيوع (1536/103) عن الحسن الحلواني، حدثنا أبو توبة، حدثنا معاوية، عن يحيى بن أبي كثير، أن يزيد بن نُعيم أخبره أن جابر بن عبدالله أخبره فذكره.قال ابن شهاب: وحدثني سالم بن عبد الله بن عمر، عن أبيه، عن النبي صلى الله عليه وسلم مثله سواء.","grade":"صحيح","chapter_ar":"باب في النهي عن بيع المزابنة والمحاقلة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Muslim (1536, no. 103).","chapter_en":"The Prohibition of al-Muzabanah and al-Muhaqalah","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":19,"content":{"translation":{"en":["Jabir ibn Abdullah reported that he heard the Messenger of Allah ﷺ forbid al-muzabanah and al-haqul. Jabir said: al-muzabanah is fruit for dates, and al-haqul means renting land."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1536/103)."},{"num":5738,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  نَهَى عَنِ الْمُحَاقَلَةِ، وَالْمُزَابَنَةِ، وَالْمُخَابَرَةِ، وَأَنْ تُشْتَرَى النَّخْلُ حَتَّى تُشْقِهَ. وَالْإِشْقَاهُ: أَنْ يَحْمَرَّ، أَوْ يَصْفَرَّ، أَوْ يُؤْكَلَ مِنْهُ شَيْءٌ. وَالْمُحَاقَلَةُ: أَنْ يُبَاعَ الْحَقْلُ بِكَيْلٍ مِنَ الطَّعَامِ مَعْلُومٍ. وَالْمُزَابَنَةُ: أَنْ يُبَاعَ النَّخْلُ بِأَوْسَاقٍ مِنَ التَّمْرِ. وَالْمُخَابَرَةُ: الثُّلُثُ وَالرُّبُعُ وَأَشْبَاهُ ذَلِكَ."],"takhrij":"صحيح: رواه مسلم (1536: 83) من طرق عن زكريا بن عدي، أخبرنا عبيدالله، عن زيد بن أبى أنيسة، حدثنا أبو الوليد المكي -وهو جالس عند عطاء بن أبى رباح- عن جابر بن عبد الله فذكره.","grade":"صحيح","chapter_ar":"باب في النهي عن بيع المزابنة والمحاقلة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Muslim (1536, no. 83).","chapter_en":"The Prohibition of al-Muzabanah and al-Muhaqalah","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":19,"content":{"translation":{"en":["Jabir ibn Abdullah reported that the Messenger of Allah ﷺ forbade al-muhaqalah, al-muzabanah, and al-mukhabarah, and that palm trees should not be sold until their fruit becomes sound. Becoming sound means that it turns red or yellow, or that some of it is edible. Al-muhaqalah is selling a field for a known measured amount of food. Al-muzabanah is selling date palms for fixed measures of dates. Al-mukhabarah is an arrangement involving one-third, one-fourth, and similar shares."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1536: 83)."},{"num":5739,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ:  نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْمُحَاقَلَةِ وَالْمُزَابَنَةِ."],"takhrij":"صحيح: رواه مسلم في البيوع (1545) عن قتيبة بن سعيد، حدثنا يعقوب (يعني ابن عبد الرحمن القاري)، عن سهيل بن أبي صـالح، عن أبيه، عن أبي هريرة.","grade":"صحيح","chapter_ar":"باب في النهي عن بيع المزابنة والمحاقلة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Muslim (1545).","chapter_en":"The Prohibition of al-Muzabanah and al-Muhaqalah","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":19,"content":{"translation":{"en":["Abu Hurayrah reported: The Messenger of Allah ﷺ forbade al-muhaqalah and al-muzabanah."]}},"tuhfa":{},"full":1,"rep":[5546],"tks":"صحيح: رواه مسلم (1545)."},{"num":5740,"demo":false,"sanad":"","matn":["عَنْ رَافِعِ بْنِ خَدِيجٍ، قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْمُحَاقَلَةِ وَالْمُزَابَنَةِ."],"takhrij":"حسن: رواه أبو داود (3400)، وابن ماجه (2267)، والنسائي (3890) كلهم من حديث أبي الأحوص، عن طارق بن عبدالرحمن، عن سعيد بن المسيب، عن رافع بن خديج فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الرخصة في بيع العرايا","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (3400), Ibn Mājah (2267), and al-Nasāʾī (3890).","chapter_en":"What has come regarding the concession for selling the araya","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":20,"content":{"translation":{"en":["Rāfiʿ ibn Khadīj reported: The Messenger of Allah ﷺ prohibited muḥāqalah and muzābanah."]},"buhuth":{"en":["They also added after the statement that the Messenger of Allah ﷺ prohibited muḥāqalah and muzābanah:","“Only three types of people cultivate land: a man who owns land and cultivates it; a man who has been granted land and cultivates what he was granted; and a man who rents land for gold or silver.”","The correct view is that this statement is an explanation from Saʿīd ibn al-Musayyib."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3400)، وابن ماجه (2267)، والنسائي (3890)."},{"num":5741,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بْنِ ثَابِتٍ رَضِيَ اللَّهُ عَنْهُمْ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَرْخَصَ لِصَاحِبِ الْعَرِيَّةِ أَنْ يَبِيعَهَا بِخَرْصِهَا."],"takhrij":"متفق عليه: رواه مالك في البيوع (14) عن نافع، عن عبد الله بن عمر، عن زيد بن ثابت فذكره. ورواه البخاري في البيوع (2188) ومسلم في البيوع (1539: 60) كلاهما من طريق مالك به مثله، وزاد مسلم: \"من التمر\".","grade":"متفق عليه","chapter_ar":"باب ما جاء في الرخصة في بيع العرايا","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (14), al-Bukhari (2188), and Muslim (1539/60). Muslim added: “for dates.”","chapter_en":"What has come regarding the concession for selling the araya","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":20,"content":{"translation":{"en":["Zayd ibn Thabit reported that the Messenger of Allah ﷺ gave permission to the owner of an ariyah to sell it according to its estimated measure."]},"buhuth":{"en":["Al-Bukhari also narrated through another chain with the wording: “The Messenger of Allah ﷺ allowed the araya to be sold according to their estimated measure by dry measure.”","Musa ibn ‘Uqbah said: “Araya are specific palm trees; one comes to buy them.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (14) والبخاري (2188) ومسلم (1539: 60)، وزاد مسلم: ((من التمر))."},{"num":5742,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بْنِ ثَابِتٍ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَخَّصَ فِي بَيْعِ الْعَرَايَا أَنْ تُبَاعَ بِخَرْصِهَا، وَلَمْ يُرَخِّصْ فِي غَيْرِ ذَلِكَ."],"takhrij":"صحيح: رواه الإمام أحمد (21581)، والدارمي (2600)، وابن حبان (5009) كلهم من حديث الأوزاعي، عن الزهري، عن سالم، عن أبيه، عن زيد بن ثابت فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الرخصة في بيع العرايا","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: narrated by Ahmad (21581), al-Darimi (2600), and Ibn Hibban (5009).","chapter_en":"What has come regarding the concession for selling the araya","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":20,"content":{"translation":{"en":["Zayd ibn Thabit reported that the Messenger of Allah ﷺ permitted the sale of the araya according to estimate, and he did not permit that in anything else."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (21581)، والدارمي (2600)، وابن حبان (5009)."},{"num":5743,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْمُحَاقَلَةِ، وَالْمُزَابَنَةِ، وَالْمُعَاوَمَةِ، وَالْمُخَابَرَةِ، وَعَنِ الثُّنْيَا، وَرَخَّصَ فِي الْعَرَايَا."],"takhrij":"صحيح: رواه مسلم في البيوع (1536: 85) من طرق عن حماد بن زيد، حدثنا أيوب، عن أبي الزبير، وسعيد بن ميناء، عن جابر بن عبد الله فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الرخصة في بيع العرايا","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1536/85).","chapter_en":"What has come regarding the concession for selling the araya","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":20,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: The Messenger of Allah ﷺ forbade selling standing crops for a measured amount of grain, the sale of fresh produce for dried produce by estimate, multi-year fruit sales, sharecropping, and undefined exceptions in a sale, but he allowed the araya."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1536: 85)."},{"num":5744,"demo":false,"sanad":"","matn":["عن سهل بْنِ أَبِي حَثْمَةَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  نَهَى عَنْ بَيْعِ الثَّمَرِ بِالتَّمْرِ، وَقَالَ: ذَلِكَ الرِّبَا، تِلْكَ الْمُزَابَنَةُ. إِلَّا أَنَّهُ رَخَّصَ فِي بَيْعِ الْعَرِيَّةِ، النَّخْلَةِ وَالنَّخْلَتَيْنِ، يَأْخُذُهَا أَهْلُ الْبَيْتِ بِخَرْصِهَا تَمْرًا، يَأْكُلُونَهَا رُطَبًا."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2191)، ومسلم في البيوع (1540: 67) كلاهما من طريق يحيى بن سعيد (هو الأنصاري)، عن بُشير بن يسار، عن بعض أصحـاب رسول الله صلى الله عليه وسلم من أهل دارهم، منهم سهل بن أبى حثمة فذكره. واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الرخصة في بيع العرايا","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (2191) and Muslim (1540/67). The wording is Muslim’s.","chapter_en":"What has come regarding the concession for selling the araya","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":20,"content":{"translation":{"en":["Sahl ibn Abi Hathmah reported that the Messenger of Allah ﷺ forbade selling fresh dates for dried dates and said: “That is usury; that is the forbidden exchange.” But he permitted the sale of an ariyah: one or two palm trees whose estimated amount is taken in dried dates by a household so they may eat them fresh."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (2191)، ومسلم (1540: 67). واللفظ لمسلم."},{"num":5745,"demo":false,"sanad":"","matn":["عن رَافِعَ بْنَ خَدِيجٍ، وَسَهْلَ بْنَ أَبِي حَثْمَةَ حدثا أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم نَهَى عَنِ الْمُزَابَنَةِ، بَيْعِ الثَّمَرِ بِالتَّمْرِ إِلاَّ أَصْحَابَ الْعَرَايَا، فَإِنَّهُ أَذِنَ لَهُمْ."],"takhrij":"متفق عليه: رواه البخاري في المساقاة (2383، 2384)، ومسلم في البيوع (1540: 70) كلاهما من حديث أبي أسامة قال: أخبرني الوليد بن كثير قال: أخبرني بُشير بن يسار مولى بني حارثة أن رافع بن خديج وسهل بن أبي حثمة حدثاه فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الرخصة في بيع العرايا","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari in the chapter of irrigation-share contracts (2383, 2384) and Muslim in sales (1540/70).","chapter_en":"What has come regarding the concession for selling the araya","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":20,"content":{"translation":{"en":["Rafi‘ ibn Khadij and Sahl ibn Abi Hathmah reported that the Messenger of Allah ﷺ forbade the sale of fruit for dried dates, except for the people of the araya, for he gave them permission."]},"buhuth":{"en":["His statement “ariyah” and “araya” refers to the sale of the fruit of specific palm trees, after its ripeness has appeared, estimated against dried dates measured on the ground. The Lawgiver exempted it from the general prohibition because people needed it. It is called ariyah because it was excluded from the general ruling of prohibition. The word carries the sense of “set apart.”","The forms of this transaction are many. Among what Ibn Hajar mentioned in al-Fath are:","One form is that a man says to the owner of an orchard: Sell me the fruit of certain named palm trees for an estimated amount of dried dates. The amount is estimated, the sale is concluded, the dried dates are received from him, and the trees are handed over by making them available.","Another form is that the orchard owner gifts a man certain palm trees, or the fruit of certain palm trees, from his orchard, then becomes inconvenienced by his repeated entry. So he estimates them and buys back their fresh fruit for the amount of dried dates corresponding to the estimate, paid immediately.","Another form is that a man sells the dates of his orchard after ripeness has appeared, but excludes certain known palm trees for himself and his family. These are the ones exempted from estimation in charity. So needy people who have no cash, but do have surplus dried dates for food, were allowed to buy the fresh fruit of those trees with dried dates according to estimate."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2384 ،2383)، ومسلم (1540: 70)."},{"num":5746,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ  أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَخَّصَ فِي بَيْعِ الْعَرَايَا بِخَرْصِهَا فِيمَا دُونَ خَمْسَةِ أَوْسُقٍ، أَوْ فِي خَمْسَةِ، (يَشُكُّ."],"takhrij":"متفق عليه: رواه مالك في البيوع (14) عن داود بن الحصين، عن أبي سفيان مولى ابن أبي أحمد، عن أبي هريرة فذكره. ورواه البخاري في البيوع (2190)، ومسلم في البيوع (1541) كلاهما من طريق مالك به مثله.","grade":"متفق عليه","chapter_ar":"باب جواز العرايا فيما دون خمسة أوسق","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (14), al-Bukhari (2190), and Muslim (1541).","chapter_en":"The permissibility of araya in amounts under five wasqs","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":21,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ permitted the sale of the araya according to estimate in amounts less than five wasqs, or up to five wasqs."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (14) والبخاري (2190)، ومسلم (1541)."},{"num":5747,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ الْأَنْصَارِيِّ، قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ أَذِنَ لِأَصْحَابِ الْعَرَايَا أَنْ يَبِيعُوهَا بِخَرْصِهَا، يَقُولُ: الْوَسْقَ، وَالْوَسْقَيْنِ، وَالثَّلَاثَةَ، وَالْأَرْبَعَةَ."],"takhrij":"حسن: رواه الإمام أحمد (14868)، وأبو يعـلى (1780)، وصحّحه ابن حبان (5008)، وابن خزيمة (2469) كلهم من حديث محمد بن إسحاق قال: حدثني محمد بن يحيى بن حبان، عن عمه واسع بن حَبان، عن جابر فذكره.","grade":"حسن","chapter_ar":"باب جواز العرايا فيما دون خمسة أوسق","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (14868), Abu Ya‘la (1780), and authenticated by Ibn Hibban (5008) and Ibn Khuzaymah (2469).","chapter_en":"The permissibility of araya in amounts under five wasqs","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":21,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah al-Ansari said: I heard the Messenger of Allah ﷺ, when he permitted the people of the araya to sell them by estimate, say: “One wasq, two wasqs, three, and four.”"]},"buhuth":{"en":["A wasq is sixty sa‘s. A sa‘ is five and one-third Iraqi pounds. The total comes to three hundred sa‘s, which is approximately 700 kilograms today."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (14868)، وأبو يعلى (1780)، وصححه ابن حبان (5008)، وابن خزيمة (2469)."},{"num":5748,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ أَبِي عَيَّاشٍ أَنَّهُ سَأَلَ سَعْدَ بْنَ أَبِي وَقَّاصٍ عَنِ الْبَيْضَاءِ بِالسُّلْتِ، فَقَالَ لَهُ سَعْدٌ: أيتهما أَفْضَلُ؟ قَالَ: الْبَيْضَاءُ. فَنَهَاهُ عَنْ ذَلِكَ. وَقَالَ سعد: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُسْأَلُ عَنْ اشتراء التَّمْرِ بِالرُّطَبِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَيَنْقُصُ الرُّطَبُ إِذَا يَبِسَ؟ فَقَالُوا: نَعَمْ، فنهى عَنْ ذَلِكَ."],"takhrij":"حسن: رواه مالك في البيوع (22) عن عبد الله بن يزيد أن زيدا أبا عياش أخبره فذكره.","grade":"حسن","chapter_ar":"باب النهي عن بيع الرطب بالتمر","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Malik (22), Abu Dawud (3359), al-Tirmidhi (1225), al-Nasa’i (4549), and Ibn Majah (2264).","chapter_en":"The prohibition of selling fresh dates for dried dates","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":22,"content":{"translation":{"en":["Zayd Abu ‘Ayyash asked Sa‘d ibn Abi Waqqas about trading white grain for sult grain. Sa‘d said to him: “Which of them is better?” He replied: “The white one.” So Sa‘d forbade him from that. Sa‘d then said: I heard the Messenger of Allah ﷺ being asked about buying dried dates with fresh dates, and the Messenger of Allah ﷺ said: “Do the fresh dates decrease when they dry?” They said: “Yes.” So he forbade that."]},"buhuth":{"en":["“Al-bayda” is a type of wheat that is white in color. “Al-sult” is another type, different from wheat, with finer grain. Some said that “al-bayda” here means the fresh form of sult, and that fits the meaning of the hadith better, since it is compared to fresh dates versus dried dates. If the category were different, the comparison would not hold."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه مالك (22) وأبو داود (3359)، والترمذي (1225)، والنسائي (4549)، وابن ماجه (2264)."},{"num":5749,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عُمَرَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ بَيْعِ الثِّمَارِ حَتَّى يَبْدُوَ صَلاَحُهَا، نَهَى الْبَائِعَ والمشتري."],"takhrij":"متفق عليه: رواه مالك في البيوع (10) عن نافع، عن ابن عمر فذكره.","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع الثمار حتى يبدو صلاحها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (10), al-Bukhari (2194), and Muslim (1534/49).","chapter_en":"The prohibition of selling fruits until their ripeness appears","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":23,"content":{"translation":{"en":["Ibn ‘Umar reported that the Messenger of Allah ﷺ forbade selling fruits until their ripeness appears. He forbade both the seller and the buyer."]},"buhuth":{"en":["Al-Bukhari (1486) added: “When he was asked about their ripeness, he said: ‘Until their blight is gone.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (10) والبخاري (2194)، ومسلم (49 :1534)."},{"num":5750,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  نَهَى عَنْ بَيْعِ النَّخْلِ حَتَّى يَزْهُوَ، وَعَنِ السُّنْبُلِ حَتَّى يَبْيَضَّ وَيَأْمَنَ الْعَاهَةَ، نَهَى الْبَائِعَ وَالْمُشْتَرِيَ."],"takhrij":"صحيح: رواه مسلم في البيوع (1535) من طرق عن إسماعيل، عن أيوب، عن نافع، عن ابن عمر فذكره. ومن هذا الوجه رواه كل من أبي داود (3368)، والترمذي (1226)، والنسائي (4551).","grade":"صحيح","chapter_ar":"باب النهي عن بيع الثمار حتى يبدو صلاحها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1535).","chapter_en":"The prohibition of selling fruits until their ripeness appears","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":23,"content":{"translation":{"en":["Ibn ‘Umar reported that the Messenger of Allah ﷺ forbade selling dates on the palm until they show ripeness, and grain in the ear until it turns white and is safe from blight. He forbade both the seller and the buyer."]},"buhuth":{"en":["Ripeness in dates means that they turn red or yellow. That is a sign that they have ripened and evidence that they are safe from damage.","His statement regarding grain “until it turns white” apparently refers to selling grain while still in the ear once it hardens and whitens."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1535)."},{"num":5751,"demo":false,"sanad":"","matn":["عَنْ عُثْمَانَ بْنِ عَبْدِ اللَّهِ بْنِ سُرَاقَةَ قَالَ: كُنَّا فِي سَفَرٍ، وَمَعَنَا ابْنُ عُمَرَ، فَسَأَلْتُهُ، فَقَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَا يُسَبِّحُ فِي السَّفَرِ قَبْلَ الصَّلَاةِ، وَلَا بَعْدَهَا. قَالَ: وَسَأَلْتُ ابْنَ عُمَرَ عَنْ بَيْعِ الثِّمَارِ، فَقَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ بَيْعِ الثِّمَارِ حَتَّى تَذْهَبَ الْعَاهَةُ، قُلْتُ: أَبَا عَبْدِ الرَّحْمَنِ، وَمَا تَذْهَبُ الْعَاهَةُ، مَا الْعَاهَةُ؟ قَالَ: طُلُوعُ الثُّرَيَّا."],"takhrij":"صحيح: رواه الإمام أحمد (5012، 5015)، والطبراني في الكبير (13287)، والبيهقي (5/300) كلهم من طريق ابن أبي ذئب، عن عثمان بن عبد الله بن سراقة فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن بيع الثمار حتى يبدو صلاحها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: narrated by Ahmad (5012, 5015), al-Tabarani in al-Kabir (13287), and al-Bayhaqi (5/300).","chapter_en":"The prohibition of selling fruits until their ripeness appears","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":23,"content":{"translation":{"en":["‘Uthman ibn ‘Abd Allah ibn Suraqah said: We were on a journey with Ibn ‘Umar, and I asked him. He said: I saw the Messenger of Allah ﷺ not perform voluntary prayer before the prescribed prayer while traveling, nor after it. He said: And I asked Ibn ‘Umar about selling fruits, so he said: The Messenger of Allah ﷺ forbade selling fruits until the blight is gone. I said: O Abu ‘Abd al-Rahman, what does it mean for the blight to be gone? What is the blight? He said: The rising of the Pleiades."]},"buhuth":{"en":["The rising of the Pleiades is a sign that the blight affecting fruits has passed. The same will also come from Zayd ibn Thabit."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (5015 ،5012)، والطبراني في الكبير (13287)، والبيهقي (5/300)."},{"num":5752,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  نَهَى عَنْ بَيْعِ ثَمَرِ النَّخْلِ حَتَّى تَزْهُوَ. فَقُلْنَا لِأَنَسٍ: مَا زَهْوُهَا؟ قَالَ: تَحْمَرُّ، وَتَصْفَرُّ، أَرَأَيْتَكَ إِنْ مَنَعَ اللهُ الثَّمَرَةَ، بِمَ تَسْتَحِلُّ مَالَ أَخِيكَ."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2208)، ومسلم في المساقاة (1555) كلاهما عن قتيبة، حدثنا إسماعيل بن جعفر، عن حميد، عن أنس فذكره. واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع الثمار حتى يبدو صلاحها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (2208) and Muslim (1555). The wording is Muslim’s.","chapter_en":"The prohibition of selling fruits until their ripeness appears","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":23,"content":{"translation":{"en":["Anas ibn Malik reported that the Prophet ﷺ forbade selling the fruit of date palms until it shows ripeness. We asked Anas: What is its ripeness? He said: It turns red and yellow. “If Allah withholds the fruit, then by what right would one of you take his brother’s wealth?”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (2208)، ومسلم (1555). واللفظ لمسلم."},{"num":5753,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ بَيْعِ الثِّمَارِ حَتَّى تُزهِيَ. فَقِيلَ لَهُ: يَا رَسُولَ اللَّهِ، وَمَا تُزْهِي؟. فَقَالَ: حِينَ تَحْمَرَّ. وَقَالَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَرَأَيْتَ إِذَا مَنَعَ اللَّهُ الثَّمَرَةَ فبم يَأْخُذُ أَحَدُكُمْ مَالَ أَخِيهِ."],"takhrij":"متفق عليه: رواه مالك في البيوع (11) عن حميد الطويل، عن أنس بن مالك فذكره.","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع الثمار حتى يبدو صلاحها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (11), al-Bukhari (2198), and Muslim (1555).","chapter_en":"The prohibition of selling fruits until their ripeness appears","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":23,"content":{"translation":{"en":["Anas ibn Malik reported that the Messenger of Allah ﷺ forbade selling fruits until they show ripeness. It was said to him: O Messenger of Allah ﷺ, what is their ripeness? He said: “When they turn red.” And the Messenger of Allah ﷺ said: “If Allah withholds the fruit, then by what right would one of you take his brother’s wealth?”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (11) والبخاري (2198)، ومسلم (1555)."},{"num":5754,"demo":false,"sanad":"","matn":["عَنْ جابر بْنِ عَبْدِ اللَّهِ يَقُولُ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَوْ بِعْتَ مِنْ أَخِيهِ تَمْرًا، فَأَصَابَتْهُ جَائِحَةٌ، فَلَا يَحِلُّ لَكَ أَنْ تَأْخُذَ مِنْهُ شَيْئًا، بِمَ تَأْخُذُ مَالَ أَخِيكَ بِغَيْرِ حَقٍّ؟."],"takhrij":"صحيح: رواه مسلم في المساقاة (1554) عن أبي الطاهر، أخبرنا ابن وهب، عن ابن جريج، أن أبا الزبير أخبره عن جابر بن عبد الله فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن بيع الثمار حتى يبدو صلاحها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1554).","chapter_en":"The prohibition of selling fruits until their ripeness appears","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":23,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: The Messenger of Allah ﷺ said: “If you sold fruit to your brother and then a calamity struck it, it is not lawful for you to take anything from him. By what right would you take your brother’s wealth without due right?”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1554)."},{"num":5755,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ: نَهَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ تُبَاعَ الثَّمَرَةُ حَتَّى تُشَقِّحَ. فَقِيلَ مَا تُشَقِّحُ؟ قَالَ: تَحْمَارُّ، وَتَصْفَارُّ، وَيُؤْكَلُ مِنْهَا."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2196)، ومسلم في البيوع (1536: 84) من طريق سليم بن حيان، حدثنا سعيد بن ميناء قال: سمعت جابر بن عبد الله قال فذكره.","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع الثمار حتى يبدو صلاحها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (2196) and Muslim (1536/84).","chapter_en":"The prohibition of selling fruits until their ripeness appears","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":23,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: The Prophet ﷺ forbade fruit from being sold until it ripens. I said to Sa‘id: What does ripening mean? He said: It becomes red, becomes yellow, and some of it is eaten."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (2196)، ومسلم (1536: 84).","voc":["bukhari",2196]},{"num":5756,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: نَهَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ بَيْعِ الثَّمَرِ حَتَّى يَطِيبَ، وَلاَ يُبَاعُ شَىْءٌ مِنْهُ إِلاَّ بِالدِّينَارِ وَالدِّرْهَمِ إِلاَّ الْعَرَايَا."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2189) من طريق ابن جريج، عن عطاء، وأبي الزبير، عن جابر فذكره.","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع الثمار حتى يبدو صلاحها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (2189) and Muslim (1536/53). In another wording: The Messenger of Allah ﷺ forbade selling fruit until its ripeness appears.","chapter_en":"The prohibition of selling fruits until their ripeness appears","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":23,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: The Prophet ﷺ forbade selling fruit until it becomes wholesome, and nothing from it is to be sold except for gold and silver, except in the case of the araya."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2189) ومسلم (53 :1536). وفي لفظ: نهى رسول الله عن بيع الثمر حتى يبدو صلاحه."},{"num":5757,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  لَا تَبْتَاعُوا الثِّمَارَ حَتَّى يَبْدُوَ صَلَاحُهَا."],"takhrij":"صحيح: رواه مسلم في البيوع (1538) عن أبي كريب محمد بن العلاء، حدثنا محمد بن فضيل، عن أبيه، عن ابن أبي نُعم، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن بيع الثمار حتى يبدو صلاحها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1538). Another chain adds: “And do not buy fruit with dried dates.”","chapter_en":"The prohibition of selling fruits until their ripeness appears","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":23,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “Do not buy fruits until their ripeness appears.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1538). ورواه من وجه آخر، وزاد فيه: ((ولا تبتاعوا الثمر بالتمر))."},{"num":5758,"demo":false,"sanad":"","matn":["عَنْ أَبِي الْبَخْتَرِيِّ قَالَ:  سَأَلْتُ ابْنَ عَبَّاسٍ عَنْ بَيْعِ النَّخْلِ، فَقَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ بَيْعِ النَّخْلِ حَتَّى يَأْكُلَ مِنْهُ، أَوْ يُؤْكَلَ، وَحَتَّى يُوزَنَ. قَالَ: فَقُلْتُ: مَا يُوزَنُ؟ فَقَالَ رَجُلٌ عِنْدَهُ: حَتَّى يُحْزَرَ."],"takhrij":"متفق عليه: رواه البخاري في السلم (2246)، ومسلم في البيوع (1537) كلاهما من طريق شعبة، أخبرنا عمرو بن مرة قال: سمعت أبا البختري الطائي فذكره. واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع الثمار حتى يبدو صلاحها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (2246) and Muslim (1537). The wording is Muslim’s.","chapter_en":"The prohibition of selling fruits until their ripeness appears","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":23,"content":{"translation":{"en":["Abu al-Bakhtari said: I asked Ibn ‘Abbas about selling date palms, and he said: The Messenger of Allah ﷺ forbade selling the dates on the palm until one may eat from them, or they are eaten, and until they are weighed. I said: What does “weighed” mean? A man beside him said: Until they can be estimated."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2246)، ومسلم (1537). واللفظ لمسلم."},{"num":5759,"demo":false,"sanad":"","matn":["عن ابْنِ عَبَّاسٍ كَانَ يَقُولُ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا يُبَاعُ الثَّمَرُ حَتَّى يُطْعَمَ."],"takhrij":"صحيح: رواه أحمد (2247)، والطبراني في الكبير (1187، 1188)، وصحّحه ابن حبان (4988) كلهم من طريق عمرو بن دينار، عن طاوس، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن بيع الثمار حتى يبدو صلاحها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: narrated by Ahmad (2247), al-Tabarani in al-Kabir (1187, 1188), and authenticated by Ibn Hibban (4988).","chapter_en":"The prohibition of selling fruits until their ripeness appears","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":23,"content":{"translation":{"en":["Ibn ‘Abbas used to say: The Messenger of Allah ﷺ said: “Fruit is not to be sold until it can be eaten.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (2247)، والطبراني في الكبير (1187 ،1188)، وصححه ابن حبان (4988)."},{"num":5760,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بن ثَابِتٍ قَالَ: كَانَ النَّاسُ فِي عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَتَبَايَعُونَ الثِّمَارَ، فَإِذَا جذ النَّاسُ وَحَضَرَ تَقَاضِيهِمْ قَالَ الْمُبْتَاعُ: إِنَّهُ أَصَابَ الثَّمَرَ الدُّمَانُ، أَصَابَهُ مرض، أَصَابَهُ قُشَامٌ –عَاهَاتٌ يَحْتَجُّونَ بِهَا-، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمَّا كَثُرَتْ عِنْدَهُ الْخُصُومَةُ فِي ذَلِكَ: فَأَمَّا لَا فَلَا تتبايعوا حَتَّى يَبْدُوَ صَلَاحُ الثَّمَرِ كَالْمَشُورَةِ يُشِيرُ بِهَا لِكَثْرَةِ خُصُومَتِهِمْ."],"takhrij":"صحيح: رواه أبو داود (3372)، وأحمد (216662)، والبيهقي (10605) كلهم من حديث يونس بن محمد قال: سألت أبا الزناد عن بيع الثمر قبل أن يبدو صلاحه، وما ذكر في ذلك، فقال: كان عروة بن الزبير يحدث عن سهل بن أبي حثمة، عن زيد بن ثابت قال فذكر الحديث نحوه. هكذا قال أبو داود.","grade":"صحيح","chapter_ar":"باب النهي عن بيع الثمار حتى يبدو صلاحها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (3372), Ahmad (21662), and al-Bayhaqi (5/301-302).","chapter_en":"The prohibition of selling fruits until their ripeness appears","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":23,"content":{"translation":{"en":["Zayd ibn Thabit said: In the time of the Messenger of Allah ﷺ, people used to buy and sell fruits. When the people harvested them and the time for settlement came, the buyer would say: The fruit was struck by blight, or disease, or damage — defects they used as excuses. So when disputes over that became frequent before him, the Messenger of Allah ﷺ said: “Then, if you insist, do not trade in fruits until their ripeness appears,” as advice from him because of how much they were disputing."]},"buhuth":{"en":["“Jadhdha” means the people cut the fruit from the date palms. “Jadhadh” means harvesting the date fruit by cutting and taking it from the tree.","“Al-daman” was explained as damage to the flower cluster, its decay, and blackening.","“Qusham” was explained in one narration as something that affects it so that it never becomes ripe. It was also said to mean that the fruit decreases before becoming firm unripe dates.","The phrase “fa imma la” means: if you do not do such-and-such, then do this instead.","The mention of the rising of the Pleiades means at dawn at the beginning of summer, when the heat intensifies in the Hijaz. What really matters is ripeness, and the rising of the Pleiades is simply a sign for it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (3372)، وأحمد (216662)، والبيهقي (10605)."},{"num":5761,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَا تَبِيعُوا ثِمَارَكُمْ حَتَّى يَبْدُوَ صَلَاحُهَا، وَتَنْجُوَ مِنَ الْعَاهَةِ."],"takhrij":"حسن: رواه الإمام أحمد (24407) والحارث في مسنده –\"بغية الباحث\" (ص 470)- من حديث عبد الرحمن بن أبي الرجال، عن أبيه، عن عمرة، عن عائشة فذكرته.","grade":"حسن","chapter_ar":"باب النهي عن بيع الثمار حتى يبدو صلاحها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: narrated by Ahmad (24407) and al-Harith in his Musnad, Bughyat al-Bahith (p. 470).","chapter_en":"The prohibition of selling fruits until their ripeness appears","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":23,"content":{"translation":{"en":["The Mother of the Believers, ‘A’ishah, reported that the Prophet ﷺ said: “Do not sell your fruits until their ripeness appears and they are safe from blight.”"]},"buhuth":{"en":["Understanding of this chapter:","The scholars act upon this and do not allow selling fruits before signs of ripeness appear, for the reason mentioned in the hadiths.","But if someone sells them on condition that they be cut immediately, then it is permissible by agreement of the scholars, because cutting removes the risk of destruction by blight or defect. In that case, the reason for the prohibition is no longer present.","The appearance of ripeness differs according to the type of fruit. In fresh dates, it is when they become unripe ripe dates and signs of red or black dots appear. In peaches, pears, apricots, and apples, it is when they become good enough to eat. In melons, it is when signs of ripeness appear. In cucumbers and eggplants, it is when they are usually ready to be picked.","The rising of the star — meaning the Pleiades — is a sign of the beginning of summer and the start of fruit ripening. What really matters is ripeness itself, and the rising of the star is only a sign of it, as came in the hadith: “until the yellow becomes distinct from the red.”","If ripeness appears in part of the crop, then selling all of it is allowed if it is all one kind. If the kinds differ, then each kind is judged by the appearance of ripeness in itself, unless cutting is stipulated for what has not yet ripened, in which case selling everything is allowed.","Likewise, it is not allowed to sell crops before the grain hardens in the ear, as came in the hadith of Ibn Umar."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (24407)، والحارث في مسنده “بغية الباحث” (ص 470)."},{"num":5762,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ  أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَرَ بِوَضْعِ الْجَوَائِحِ."],"takhrij":"صحيح: رواه مسلم في المساقاة (1554: 17) من طريق سفيان بن عيينة، عن حميد الأعرج، عن سليمان بن عتيق، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في وضع الجائحة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1554/17). Al-Shafi‘i also narrated it in al-Umm (3/56), and in it is: “The Messenger of Allah ﷺ forbade selling for future years and ordered remission in cases of blight.”","chapter_en":"What has come regarding remission in the case of a blight or calamity","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":24,"content":{"translation":{"en":["Jabir reported that the Prophet ﷺ ordered that losses caused by blight be remitted."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1554: 17). ورواه الشافعي في الأم (163) وفيه: (( أن رسول الله ﷺ نهى عن بيع السنين، وأمر بوضع الجوائح))."},{"num":5763,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ بَيْعِ السِّنِينَ، وَوَضَعَ الْجَوَائِحَ."],"takhrij":"صحيح: رواه أبو داود (3374) عـن أحمد بن حنبل ويحيى بن معين قالا: حدثنا سفيان، عن حميدالأعرج، عن سليمان بن عتيق، عن جابر بن عبدالله فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في وضع الجائحة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3374).","chapter_en":"What has come regarding remission in the case of a blight or calamity","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":24,"content":{"translation":{"en":["Jabir reported that the Prophet ﷺ forbade selling fruit for future years and ruled that losses caused by blight be remitted."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (3374)."},{"num":5764,"demo":false,"sanad":"","matn":["عن جابر بْنِ عَبْدِ اللَّهِ يَقُولُ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  لَوْ بِعْتَ مِنْ أَخِيكَ ثَمَرًا فَأَصَابَتْهُ جَائِحَةٌ، فَلَا يَحِلُّ لَكَ أَنْ تَأْخُذَ مِنْهُ شَيْئًا، بِمَ تَأْخُذُ مَالَ أَخِيكَ بِغَيْرِ حَقٍّ."],"takhrij":"صحيح رواه مسلم في المساقاة (1554: 14) عن أبي الطاهر، أخبرنا ابن وهب، عن ابن جريج أن أبا الزبير أخبره عن جابر بن عبد الله فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في وضع الجائحة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1554/14).","chapter_en":"What has come regarding remission in the case of a blight or calamity","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":24,"content":{"translation":{"en":["Jabir ibn Abd Allah said: The Messenger of Allah ﷺ said, “If you sold fruit to your brother and then it was struck by a calamity, it is not lawful for you to take anything from him. With what right would you take your brother’s wealth without right?”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1554: 14)."},{"num":5765,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ:  أُصِيبَ رَجُلٌ فِي عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي ثِمَارٍ ابْتَاعَهَا، فَكَثُرَ دَيْنُهُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: تَصَدَّقُوا عَلَيْهِ. فَتَصَدَّقَ النَّاسُ عَلَيْهِ، فَلَمْ يَبْلُغْ ذَلِكَ وَفَاءَ دَيْنِهِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِغُرَمَائِهِ: خُذُوا مَا وَجَدْتُمْ، وَلَيْسَ لَكُمْ إِلَّا ذَلِكَ."],"takhrij":"صحيح: رواه مسلم في المساقاة (1556) عن قتيبة بن سعيد، حدثنا الليث، عن بكير، عن عياض بن عبد الله ، عن أبي سعيد الخدري فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في وضع الجائحة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1556).","chapter_en":"What has come regarding remission in the case of a blight or calamity","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":24,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī reported: A man during the lifetime of the Messenger of Allah ﷺ suffered a loss in fruits that he had purchased, and his debts became numerous. The Messenger of Allah ﷺ said: “Give charity to him.” The people gave charity to him, but it was not enough to repay his debt fully. The Messenger of Allah ﷺ then said to his creditors: “Take whatever you find, and you are entitled to nothing beyond that.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[4254,5634,12484],"tks":"صحيح: رواه مسلم (1556)."},{"num":5766,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ:  نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ بَيْعِ الْحَصَاةِ، وَعَنْ بَيْعِ الْغَرَرِ."],"takhrij":"صحيح: رواه مسلم في البيوع (1513) من طرق عن عبيدالله، حدثني أبو الزناد، عن الأعرج، عن أبي هريرة قال فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن بيع الغرر، وبيع الحصاة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1513).","chapter_en":"The prohibition of uncertain sales and pebble sales","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":25,"content":{"translation":{"en":["Abū Hurayrah reported: The Messenger of Allah ﷺ prohibited the pebble sale and transactions involving excessive uncertainty."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1513)."},{"num":5767,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عُمَرَ، قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ بَيْعِ الْغَرَرِ."],"takhrij":"حسن: رواه الإمام أحمـد (6307) عن يعلى ومحمد قالا: حدثنا محمد -يعني ابن إسحاق-، حدثني نافع، عن ابن عمر فذكره.","grade":"حسن","chapter_ar":"باب النهي عن بيع الغرر، وبيع الحصاة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (6307) and Ibn Hibban in his Sahih (4972).","chapter_en":"The prohibition of uncertain sales and pebble sales","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":25,"content":{"translation":{"en":["Ibn Umar said: The Messenger of Allah ﷺ forbade uncertain sale."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (6307)، وابن حبان في صحيحه (4972)."},{"num":5768,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ بَيْعِ حَبَلِ الْحَبَلَةِ، وَكَانَ بَيْعًا يَتَبَايَعُهُ أَهْلُ الْجَاهِلِيَّةِ، كَانَ الرَّجُلُ يَبْتَاعُ الْجَزُورَ إِلَى أَنْ تُنْتَجَ النَّاقَةُ، ثُمَّ تُنْتَجُ الَّتِي فِي بَطْنِهَا."],"takhrij":"متفق عليه: رواه مـالك في البيوع (62) عن نافـع، عن عبد الله بن عمر فذكره. ورواه البخاري في البيوع (2143) من طريق مالك به مثله.","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع حبل الحبلة، والمضامين، والملاقيح","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (62), al-Bukhari (2143), and Muslim (1514).","chapter_en":"The prohibition of selling habal al-habalah, unborn offspring, and what is still in the wombs","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":26,"content":{"translation":{"en":["Abd Allah ibn Umar reported that the Messenger of Allah ﷺ forbade the sale of habal al-habalah. This was a sale practiced by the people of the pre-Islamic era: a man would buy a camel on delayed terms until a she-camel gave birth, and then until the one in her womb gave birth."]},"buhuth":{"en":["Explanation: Al-Nawawi said that scholars differed over what exactly is meant by habal al-habalah. Some said it means a sale with payment delayed until the she-camel gives birth and then its offspring gives birth. Others said it means selling the offspring of a pregnant she-camel immediately, and this is closer to the language. Ibn al-Athir said the first “habal” refers to the pregnancy in the bellies of the camels, and the second to the pregnancy of what is in those bellies. It was forbidden for two reasons: first, because it is uncertainty and the sale of something not yet created; second, because it may also refer to an unknown time limit, and that is invalid."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (62) والبخاري (2143) ومسلم (1514)."},{"num":5769,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ، عَـنَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: فِي السَّلَفِ فِي حَبَلِ الْحَبَلِ رِبًا."],"takhrij":"صحيح: رواه النسائي (4622)، وأحمد (2145) كلاهما من حديث محمد بن جعفر، حدثنا شعبة، عن أيوب، عن سعيد بن جبير، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن بيع حبل الحبلة، والمضامين، والملاقيح","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (4622) and Ahmad (2145).","chapter_en":"The prohibition of selling habal al-habalah, unborn offspring, and what is still in the wombs","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":26,"content":{"translation":{"en":["Abd Allah ibn Abbas reported that the Prophet ﷺ said: “There is usury in an advance sale involving habal al-habal.”"]},"buhuth":{"en":["Explanation: Here, salaf means that the buyer pays the price in advance to a man who has a pregnant she-camel and says: when this camel gives birth, and then the one in her womb gives birth, I have bought that offspring from you for this price. This resembles usury in the sense that it is forbidden like usury, because the seller is selling what he does not possess and cannot deliver, so it contains uncertainty."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (4622)، وأحمد (2145)."},{"num":5770,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ قَالَ:  نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْمُحَاقَلَةِ، وَالْمُزَابَنَةِ، وَالْمُعَاوَمَةِ، وَالْمُخَابَرَةِ، (قَالَ أَحَدُهُمَا: بَيْعُ السِّنِينَ هِيَ الْمُعَاوَمَةُ). وَعَنِ الثُّنْيَا، وَرَخَّصَ فِي الْعَرَايَا."],"takhrij":"صحيح: رواه مسلم في البيوع (1536: 85) من طريق حماد بن زيد، حدثنا أيوب، عن أبي الزبير وسعيد بن ميناء، عن جابر بن عبد الله قال فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن بيع المعاومة والسنين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1536/85). In another chain (1536/86), the wording is: “The Messenger of Allah ﷺ forbade renting land, selling it for years, and selling dates until they become ripe.”","chapter_en":"The prohibition of multi-year fruit sales","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":27,"content":{"translation":{"en":["Jabir ibn Abd Allah said: The Messenger of Allah ﷺ forbade selling standing crops for a measured amount of grain, fresh produce for dried produce by estimate, multi-year fruit sales, sharecropping, and undefined exceptions, and he allowed the araya. One of the narrators said: selling for years is the same as multi-year sale."]},"buhuth":{"en":["“Selling for years” means selling the fruit of a date palm for two or three years ahead. It is invalid by consensus because it is selling something that does not yet exist at the time of contract, and it contains uncertainty, ignorance, and inability to deliver if blight strikes."]}},"tuhfa":{},"full":1,"dr":1,"rep":[5882],"tks":"صحيح: رواه مسلم (1536: 85)، ورواه من طريق آخر (86) بلفظ: ((نهى رسول الله ﷺ عن كراء الأرض، وعن بيعها السنين، وعن بيع التمر حتى يرطب))."},{"num":5771,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ الْمُلاَمَسَةِ وَالْمُنَابَذَةِ."],"takhrij":"متفق عليه: رواه مالك في البيوع (76) عن محمد بن يحيى بن حَبان، عن أبي الزناد، عن الأعرج، عن أبي هريرة. ورواه البخاري في البيوع (2146)، ومسلم في البيوع (1511) كلاهما من طريق مالك به مثله.","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع الملامسة والمنابذة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (76), al-Bukhari (2146), and Muslim (1511).","chapter_en":"The prohibition of touch-sale and throw-sale","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":28,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ forbade touch-sale and throw-sale."]},"buhuth":{"en":["Al-Bukhari (368) and Muslim also narrated through another chain with the wording: “The Prophet ﷺ forbade two sales: touching and throwing, and he also forbade wrapping oneself tightly in one garment and sitting with one garment wrapped around the body.” Another wording says: “He forbade the two sales of touch-sale and throw-sale.”","Explanation: Touch-sale means that each of the two parties merely touches the other’s garment without careful inspection. Throw-sale means that each one throws his garment to the other, and neither one examines the other’s item."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (76) والبخاري (2146)، ومسلم (1511)."},{"num":5772,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ: نَهَانَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ بَيْعَتَيْنِ وَلِبْسَتَيْنِ: نَهَى عَنِ الْمُلَامَسَةِ وَالْمُنَابَذَةِ فِي الْبَيْعِ. وَالْمُلَامَسَةُ: لَمْسُ الرَّجُلِ ثَوْبَ الْآخَرِ بِيَدِهِ بِاللَّيْلِ أَوْ بِالنَّهَارِ، وَلَا يَقْلِبُهُ إِلَّا بِذَلِكَ. وَالْمُنَابَذَةُ: أَنْ يَنْبِذَ الرَّجُلُ إِلَى الرَّجُلِ بِثَوْبِهِ، وَيَنْبِذَ الْآخَرُ إِلَيْهِ ثَوْبَهُ، وَيَكُونُ ذَلِكَ بَيْعَهُمَا مِنْ غَيْرِ نَظَرٍ وَلَا تَرَاضٍ."],"takhrij":"متفق عليه: رواه البخاري في اللباس (5820)، ومسلم في البيوع (1512) كلاهما من طريق يونس، عن ابن شهاب (الزهري)، أخبرني عامر بن سعد بن أبي وقاص، أن أبا سعيد الخدري قال فذكره. واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع الملامسة والمنابذة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5820) and Muslim (1512). The wording is Muslim’s.","chapter_en":"The prohibition of touch-sale and throw-sale","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":28,"content":{"translation":{"en":["Abu Sa‘id al-Khudri said: The Messenger of Allah ﷺ forbade us from two sales and two styles of dress. He forbade touch-sale and throw-sale in transactions. Touch-sale is when a man touches the garment of another with his hand at night or day and does not inspect it except by that. Throw-sale is when one man throws his garment to another, and the other throws his garment to him, and that becomes their sale without inspection and without mutual satisfaction."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5820)، ومسلم (1512). واللفظ لمسلم."},{"num":5773,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ أَنَّهُ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْمُحَاقَلَةِ، وَالْمُخَاضَرَةِ، وَالْمُلاَمَسَةِ، وَالْمُنَابَذَةِ، وَالْمُزَابَنَةِ."],"takhrij":"صحيح: رواه البخاري في البيوع (2207) عن إسحاق بن وهب، حدثنا عمر بن يونس قال: حدثنا أبي قال: حدثني إسحاق بن أبي طلحة الأنصاري، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن بيع الملامسة والمنابذة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2207).","chapter_en":"The prohibition of touch-sale and throw-sale","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":28,"content":{"translation":{"en":["Anas ibn Malik said: The Messenger of Allah ﷺ forbade selling standing crops for a measured amount of grain, selling green produce before ripeness, touch-sale, throw-sale, and fresh produce for dried produce by estimate."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (2207)."},{"num":5774,"demo":false,"sanad":"","matn":["عن جابر بْنِ عَبْدِ اللَّهِ يَقُولُ:  نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ بَيْعِ الصُّبْرَةِ مِنَ التَّمْرِ، لَا يُعْلَمُ مَكِيلَتُهَا بِالْكَيْلِ الْمُسَمَّى مِنَ التَّمْرِ."],"takhrij":"صحيح: رواه مسلم في البيوع (1530) عن أبي الطاهر أحمد بن عمرو بن سرح، أخبرنا ابن وهب، حدثني ابن جريج، أن أبا الزبير أخبره أنه سمع جابر بن عبد الله يقول فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن بيع صبرة التمر","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1530).","chapter_en":"The prohibition of selling a heap of dates","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":29,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh reported: “The Messenger of Allah ﷺ prohibited selling a heap of dates whose measure is unknown in exchange for a specified measured quantity of dates.”"]},"buhuth":{"en":["Al-Nasāʾī (4548) narrated through another route:","“A heap of food is not to be sold for another heap of food, nor is a heap of food to be sold for a specified measured quantity of food.”","A ṣubrah is a pile or heap. To purchase something ṣubrah means to buy it without weighing or measuring it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1530)."},{"num":5775,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ عَامَ الْفَتْحِ، وَهُوَ بِمَكَّةَ إِنَّ اللَّهَ وَرَسُولَهُ حَرَّمَ بَيْعَ الْخَمْرِ وَالْمَيْتَةِ وَالْخِنْزِيرِ وَالأَصْنَامِ. فَقِيلَ: يَا رَسُولَ اللَّهِ، أَرَأَيْتَ شُحُومَ الْمَيْتَةِ؛ فَإِنَّهَا يُطْلَى بِهَا السُّفُنُ، وَيُدْهَنُ بِهَا الْجُلُودُ، وَيَسْتَصْبِحُ بِهَا النَّاسُ. فَقَالَ: لاَ، هُوَ حَرَامٌ. ثُمَّ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عِنْدَ ذَلِكَ: قَاتَلَ اللَّهُ الْيَهُودَ، إِنَّ اللَّهَ لَمَّا حَرَّمَ شُحُومَهَا جَمَلُوهُ، ثُمَّ بَاعُوهُ، فَأَكَلُوا ثَمَنَهُ."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2236)، ومسلم في المساقاة (1581) كلاهما عن قتيبة بن سعيد، حدثنا الليث، عن يزيد بن أبي حبيب، عن عطاء بن أبي رباح، عن جابر بن عبد الله فذكره.","grade":"متفق عليه","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2236) and Muslim (1581).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Jabir ibn Abd Allah reported that he heard the Messenger of Allah ﷺ say in Makkah during the Year of the Conquest: “Allah and His Messenger have forbidden the sale of wine, carrion, pork, and idols.” It was said: O Messenger of Allah ﷺ, what about the fat of carrion, for ships are coated with it, skins are greased with it, and people use it for lamps? He said: “No, it is forbidden.” Then the Messenger of Allah ﷺ said: “May Allah destroy the Jews. When Allah forbade their fats, they melted them, then sold them, and consumed their price.”"]},"intro":{"ar":["قال اللّه تعالى: ( حُرِّمَتْ عَلَيْكُمُ الْمَيْتَةُ وَالدَّمُ وَلَحْمُ الْخِنزِيرِ وَمَا أُهِلَّ لِغَيْرِ اللَّهِ بِهِ وَالْمُنْخَنِقَةُ وَالْمَوْقُوذَةُ وَالْمُتَرَدِّيَةُ وَالنَّطِيحَةُ وَمَا أَكَلَ السَّبُعُ إِلَّا مَا ذَكَّيْتُمْ وَمَا ذُبِحَ عَلَى النُّصُبِ وَأَن تَسْتَقْسِمُوا بِالْأَزْلَامِ ذَلِكُمْ فِسْقٌ ۗ الْيَوْمَ يَئِسَ الَّذِينَ كَفَرُوا مِن دِينِكُمْ فَلَا تَخْشَوْهُمْ وَاخْشَوْنِ ۚ الْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِي وَرَضِيتُ لَكُمُ الْإِسْلَامَ دِينًا ۚ فَمَنِ اضْطُرَّ فِي مَخْمَصَةٍ غَيْرَ مُتَجَانِفٍ لِإِثْمٍ فَإِنَّ اللَّهَ غَفُورٌ رَّحِيمٌ )","[سورة المائدة: ٣]"],"en":["Allah the Exalted said: “Forbidden to you are carrion, blood, the flesh of swine, that which has been dedicated to other than Allah, the strangled animal, the beaten animal, the fallen animal, the gored animal, and that which has been eaten by a beast — except what you are able to slaughter properly — and that which is sacrificed on stone altars, and that you seek decision by divining arrows. That is grave disobedience. Today those who disbelieve have despaired of your religion, so do not fear them, but fear Me. Today I have perfected for you your religion, completed My favor upon you, and chosen submission to Allah as your religion. But whoever is forced by severe hunger, without inclining to sin, then indeed Allah is Forgiving and Merciful.”","[Surat al-Ma’idah: 3]"]}},"tuhfa":{},"full":1,"rep":[9177,12319],"tks":"متفق عليه: رواه البخاري (2236)، ومسلم (1581)."},{"num":5776,"demo":false,"sanad":"","matn":["عن ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا يَقُولُ بَلَغَ عُمَرَ أَنَّ فُلاَنًا بَاعَ خَمْرًا، فَقَالَ: قَاتَلَ اللَّهُ فُلاَنًا، أَلَمْ يَعْلَمْ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: قَاتَلَ اللَّهُ الْيَهُودَ، حُرِّمَتْ عَلَيْهِمُ الشُّحُومُ، فَجَمَلُوهَا، فَبَاعُوهَا."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2223)، ومسلم في المساقاة (1582) من طريق سفيان بن عيينة، حدثنا عمرو بن دينار، أخبرني طاوس، أنه سمع ابن عباس يقول فذكره. واللفظ للبخاري، وجاء فلان مصرحا باسمه عند مسلم أنه سمرة بن جندب رضي الله عنه.","grade":"متفق عليه","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2223) and Muslim (1582). This wording is from al-Bukhari.","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Ibn Abbas said: Umar was informed that a certain man had sold wine, so he said: May Allah destroy that man. Does he not know that the Messenger of Allah ﷺ said: “May Allah destroy the Jews. Fat was forbidden to them, so they melted it and sold it.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[12321],"tks":"متفق عليه: رواه البخاري (2223)، ومسلم (1582). واللفظ للبخاري."},{"num":5777,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَالِسًا عِنْدَ الرُّكْنِ، - قَالَ: - فَرَفَعَ بَصَرَهُ إِلَى السَّمَاءِ، فَضَحِكَ، فَقَالَ: لَعَنَ اللَّهُ الْيَهُودَ. ثَلاَثًا، إِنَّ اللَّهَ حَرَّمَ عَلَيْهِمُ الشُّحُومَ، فَبَاعُوهَا، وَأَكَلُوا أَثْمَانَهَا، وَإِنَّ اللَّهَ إِذَا حَرَّمَ عَلَى قَوْمٍ أَكْلَ شَىْءٍ حَرَّمَ عَلَيْهِمْ ثَمَنَهُ."],"takhrij":"صحيح: رواه أبو داود (3488)، وأحمد (2221)، وابن حبان (4938)، والبيهقي (11051) كلهم من طريق خالد الحذاء، عن بركة أبي الوليد، أخبرنا ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3488), Ahmad (2221), Ibn Hibban (4938), and al-Bayhaqi (6/13).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Ibn Abbas said: I saw the Messenger of Allah ﷺ sitting by the corner of the Ka‘bah. He raised his sight to the sky and smiled, then said: “May Allah curse the Jews three times. Allah forbade fat to them, but they sold it and consumed its price. When Allah forbids a people from eating something, He forbids them from taking its price as well.”"]},"buhuth":{"en":["Explanation: His statement, “When Allah forbids a people from eating something, He forbids them from taking its price as well,” is not taken in a fully unrestricted sense. The scholars agreed that some things may not be eaten but may still be sold, such as human beings, donkeys, and similar matters. People also traded manure for farming use throughout the ages. See al-Minnah al-Kubra (5/228) for more detail."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (3488)، وأحمد (2221)، وابن حبان (4938)، والبيهقي (11051)."},{"num":5778,"demo":false,"sanad":"","matn":["عن ابْنِ عَبَّاسٍ أَهْدَى رَجُلٌ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَاوِيَةَ خَمْرٍ، فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَا عَلِمْتَ أَنَّ اللَّهَ حَرَّمَهَا. قَالَ: لاَ. فَسَارَّهُ رَجُلٌ إِلَى جَنْبِهِ. فَقَالَ لَهُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِمَ سَارَرْتَهُ. فَقَالَ: أَمَرْتُهُ أَنْ يَبِيعَهَا. فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِنَّ الَّذِي حَرَّمَ شُرْبَهَا حَرَّمَ بَيْعَهَا. فَفَتَحَ الرَّجُلُ الْمَزَادَتَيْنِ حَتَّى ذَهَبَ مَا فِيهِمَا."],"takhrij":"صحيح: رواه مالك في الأشربة (12) عن زيد بن اسلم، عن ابن وَعْلة المصـري، أنه سأل عبد الله بن عباس عما يُعصر من العنب، فقـال ابن عباس فذكره. ورواه مسلم في المساقاة (1579) من طريق مالك وغيره، عن زيد بن أسلم به.","grade":"صحيح","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (12) and Muslim (1579).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Ibn Abbas said: A man gave the Messenger of Allah ﷺ a wineskin of wine. The Messenger of Allah ﷺ said to him: “Did you not know that Allah has forbidden it?” He said: No. A man next to him whispered to him, and the Prophet ﷺ said: “What did you whisper to him?” He said: I told him to sell it. The Messenger of Allah ﷺ said: “The One who forbade drinking it also forbade selling it.” So the man opened the two skins until all that was in them was poured out."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مالك (12) ومسلم (1579)."},{"num":5779,"demo":false,"sanad":"","matn":["عن ابْنِ عَبَّاسٍ يَقُولُ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: أَتَانِي جِبْرِيلُ، فَقَالَ: يَا مُحَمَّدُ، إِنَّ اللَّهَ عَزَّ وَجَلَّ لَعَنَ الْخَمْرَ، وَعَاصِرَهَا، وَمُعْتَصِرَهَا، وَشَارِبَهَا، وَحَامِلَهَا، وَالْمَحْمُولَةَ إِلَيْهِ، وَبَائِعَهَا، وَمُبْتَاعَهَا، وَسَاقِيَهَا، وَمُسْتَقِيَهَا."],"takhrij":"حسن: رواه أحمد (2897)، والطبراني في الكبير 12976)، وابن حبان (5356)، والحاكم (2234) كلهم من طرق عن مالك بن خير الزيادي، أن مالك بن سعد التجيبي حدثه، أنه سمع ابن عباس يقول فذكره.","grade":"حسن","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (2897), al-Tabarani in al-Kabir (12976), Ibn Hibban (5356), and al-Hakim (2/31).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Ibn Abbas said: I heard the Messenger of Allah ﷺ say: “Gabriel came to me and said: O Muhammad, Allah has cursed wine, the one who presses it, the one for whom it is pressed, the one who drinks it, the one who carries it, the one to whom it is carried, the one who sells it, the one who buys it, the one who serves it, and the one who asks for it to be served.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (2897)، والطبراني في الكبير (12976)، وابن حبان (5356)، والحاكم (2234)."},{"num":5780,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عَبَّاسٍ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ اللَّهَ حَرَّمَ عَلَيْكُمِ الْخَمْرَ، وَالْمَيْسِرَ، وَالْكُوبَةَ، وَقَالَ: كُلُّ مُسْكِرٍ حَرَامٌ."],"takhrij":"صحيح: رواه الإمام أحمد (2625)، والطحاوي في شرحه (4/216)، والبيهقي (20943) كلهم من حديث عبد الله بن عمرو، عن عبد الكريم، عن قيس بن حَبْتر، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (2625), al-Tahawi in his commentary (4/216), and al-Bayhaqi (10/221).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Ibn Abbas reported that the Messenger of Allah ﷺ said: “Allah has forbidden for you wine, gambling, and the drum.” And he said: “Every intoxicant is forbidden.”"]},"buhuth":{"en":["Explanation: The word used here has been explained as backgammon, and it has also been explained as a drum, and others said it means a stringed musical instrument. This is mentioned in al-Nihayah."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (2625)، والطحاوي في شرحه (4/216)، والبيهقي (20943)."},{"num":5781,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: قَاتَلَ اللَّهُ يَهُودًا، حُرِّمَتْ عَلَيْهِمُ الشُّحُومُ، فَبَاعُوهَا، وَأَكَلُوا أَثْمَانَهَا."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2224)، ومسلم في المساقاة (1583) من طريق يونس (هو: ابن يزيد الأيلي)، عن ابن شهاب، سمعت سعيد بن المسيب، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2224) and Muslim (1583).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “May Allah destroy the Jews. Fat was forbidden to them, yet they sold it and consumed its price.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2224)، ومسلم (1583)."},{"num":5782,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ اللَّهَ حَرَّمَ الْخَمْرَ وَثَمَنَهَا، وَحَرَّمَ الْمَيْتَةَ وَثَمَنَهَا، وَحَرَّمَ الْخِنْزِيرَ وَثَمَنَهُ."],"takhrij":"حسن: رواه أبو داود (3485) عن أحمد بن صالح، حدثنا عبد الله بن وهب، حدثنا معاوية بن صالح، عن عبدالوهاب بن بخت، عن أبي الزناد، عن الأعرج، عن أبي هريرة فذكره. ورواه البيهقي (11049) من طريق أبي داود.","grade":"حسن","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3485).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “Allah has forbidden wine and its price, carrion and its price, and pork and its price.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3485)."},{"num":5783,"demo":false,"sanad":"","matn":["عَنْ عَوْنِ بْنِ أَبِي جُحَيْفَةَ قَالَ: رَأَيْتُ أَبِي اشْتَرَى حَجَّامًا، فَأَمَرَ بمحاجمه، فكسرت، فَسَأَلْتُهُ عَنْ ذَلِكَ، فَقَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ ثَمَنِ الدَّمِ، وَثَمَنِ الْكَلْبِ، وَكَسْبِ الأَمَةِ. وَلَعَنَ الْوَاشِمَةَ وَالْمُسْتَوْشِمَةَ، وَآكِلَ الرِّبَا ومؤكله، وَلَعَنَ الْمُصَوِّرَ."],"takhrij":"صحيح: رواه البخاري في البيوع (2238) عن حجاج بن منهال، حدثنا شعبة قال: أخبرني عون أبي جحيفة فذكره.","grade":"صحيح","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2238).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Awn ibn Abi Juhayfah said: I saw my father buy a cupper, then he ordered that his instruments be broken. I asked him about that, and he said: The Messenger of Allah ﷺ forbade the price of blood, the price of a dog, and the earnings of a slave woman. He also cursed the woman who tattoos and the one who seeks tattooing, the one who consumes usury and the one who pays it, and he cursed the image-maker."]},"buhuth":{"ar":["قوله:  نهى عن ثمن الدم  قيل: معناه أجرة الحجامة، والصحيح هو بيع الدم نفسه؛ لأن أهل الجاهلية كانوا يجمدون الدم ويأكلونه، كما هو موجود إلى الآن في بعض المجتمعات الوثنية، وأما أجرة الحجامة فليست حراما، وأكثر ما قيل فيها إنها مكروهة."],"en":["Explanation: His saying, “He forbade the price of blood,” has been explained by some as the fee of cupping, but the sounder meaning is the sale of blood itself, because the people of the pre-Islamic period used to congeal blood and eat it. As for the wage of cupping, it is not forbidden; at most some scholars considered it disliked."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (2238)."},{"num":5784,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ:  لَمَّا أُنْزِلَتِ الْآيَاتُ مِنْ آخِرِ سُورَةِ الْبَقَرَةِ فِي الرِّبَا قَالَتْ: خَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى الْمَسْجِدِ، فَحَرَّمَ التِّجَارَةَ فِي الْخَمْرِ."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2226)، ومسلم في المساقاة (1580) من طريق الأعمش، عن أبي الضحى مسلم (هو ابن صَبيح)، عن مسروق، عن عائشة فذكرته.","grade":"متفق عليه","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2226) and Muslim (1580). This wording is from Muslim.","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Aishah said: When the verses at the end of Surat al-Baqarah concerning usury were revealed, the Messenger of Allah ﷺ went out to the mosque and forbade trade in wine."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2226)، ومسلم (1580). واللفظ لمسلم."},{"num":5785,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ:  سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ بِالْمَدِينَةِ قَالَ: يَا أَيُّهَا النَّاسُ، إِنَّ اللَّهَ تَعَالَى يُعَرِّضُ بِالْخَمْرِ، وَلَعَلَّ اللَّهَ سَيُنْزِلُ فِيهَا أَمْرًا، فَمَنْ كَانَ عِنْدَهُ مِنْهَا شَيْءٌ فَلْيَبِعْهُ، وَلْيَنْتَفِعْ بِهِ. قَالَ: فَمَا لَبِثْنَا إِلَّا يَسِيرًا حَتَّى قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ اللَّهَ تَعَالَى حَرَّمَ الْخَمْرَ، فَمَنْ أَدْرَكَتْهُ هَذِهِ الْآيَةُ، وَعِنْدَهُ مِنْهَا شَيْءٌ فَلَا يَشْرَبْ وَلَا يَبِعْ. قَالَ: فَاسْتَقْبَلَ النَّاسُ بِمَا كَانَ عِنْدَهُ مِنْهَا فِي طَرِيقِ الْمَدِينَةِ، فَسَفَكُوهَا."],"takhrij":"صحيح: رواه مسلم في المساقاة (1578) عن عبيدالله بن عمر القواريري، حدثنا عبدالأعلى بن عبدالأعلى أبو همام، حدثنا سعيد الجريري، عن أبي نضرة، عن أبي سعيد الخدري قال فذكره.","grade":"صحيح","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1578).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Abu Sa‘id al-Khudri said: I heard the Messenger of Allah ﷺ giving a sermon in Madinah and saying: “O people, Allah is indicating that wine will be forbidden, and perhaps Allah will soon reveal a command about it. Whoever has any of it should sell it and benefit from it.” We only waited a short while before the Prophet ﷺ said: “Allah has now forbidden wine. Whoever is reached by this verse while he still has any of it should neither drink it nor sell it.” The people then took what they had of it to the streets of Madinah and poured it out."]},"buhuth":{"en":["Explanation: His statement, “Allah is indicating concerning wine,” means He was hinting at its prohibition before the final explicit ruling. The verse referred to is: “They ask you about wine and gambling. Say: in them is great sin and some benefit for people, but their sin is greater than their benefit.”","[Surat al-Baqarah: 219]","And his saying, “Whoever is reached by this verse,” refers to the verse: “O you who believe, indeed wine, gambling, sacrificial stones, and divining arrows are filth from the work of Satan, so avoid them that you may succeed.”","[Surat al-Ma’idah: 90]"]}},"tuhfa":{},"full":1,"dr":1,"rep":[7442],"tks":"صحيح: رواه مسلم (1578)."},{"num":5786,"demo":false,"sanad":"","matn":["عَنْ عبدالرحمن بن غَنْمٍ أَنَّ الدَّارِيَّ كَانَ يُهْدِي لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كُلَّ عَامٍ رَاوِيَةً خَمْرٍ، فَلَمَّا كَانَ عَامَ حُرِّمَتْ جَاءَ بِرَاوِيَةٍ، فَلَمَّا نَظَرَ إليـــه نبي اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ضَحِكَ، قَالَ: هَلْ شَعَرْتَ أَنَّهَا قَدْ حُرِّمَتْ بَعْدَكَ؟. قَالَ: يَا رَسُولَ اللَّهِ، أَفَلَا أَبِيعُهَا فانتفع بِثَمَنِهَا؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : لَعَنَ اللَّهُ الْيَهُودَ، انْطَلَقُوا إِلَى مَا حُرِّمَ عَلَيْهِمْ مِنْ شُحُومِ الْبَقَرِ وَالْغَنَمِ، فَأَذَابُوهُ، فَجَعَلُوهُ ثَمَنًا لَهُ، فَبَاعُوا بِهِ مَا يَأْكُلُونَ، وَإِنَّ الْخَمْرَ حَرَامٌ، وَثَمَنَهَا حَرَامٌ، وَإِنَّ الْخَمْرَ حَرَامٌ، وَثَمَنَهَا حَرَامٌ، وَإِنَّ الْخَمْرَ حَرَامٌ، وَثَمَنَهَا حَرَامٌ."],"takhrij":"حسن: رواه أحمد (17995) عن روح، حدثنا عبدالحميد بن بهرام قال: سمعت شهر بن حوشب قال: حدثني عبد الرحمن بن غَنْم فذكره.","grade":"حسن","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (17995).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Abd al-Rahman ibn Ghanm reported that al-Dari used to gift the Messenger of Allah ﷺ a skin of wine every year. When the year came in which it was forbidden, he brought one again. When the Prophet ﷺ saw it, he smiled and said: “Did you realize that it has been forbidden after your last visit?” He said: O Messenger of Allah ﷺ, may I not sell it and benefit from its price? The Messenger of Allah ﷺ said: “May Allah curse the Jews. They went to the fats of cattle and sheep that had been forbidden to them, melted them down, turned them into a saleable commodity, and used the money to buy what they ate. Wine is forbidden, and its price is forbidden.” He repeated that three times."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (17995)."},{"num":5787,"demo":false,"sanad":"","matn":["عن عَامِرِ بن رَبِيعَةَ عَنْ أَبِيهِ، أَنَّ رَجُلًا، مِنْ ثَقِيفٍ يُكْنَى أَبَا تَمَامٍ أَهْدَى إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَاوِيَةَ خَمْرٍ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّهَا قَدْ حُرِّمَتْ يَا أَبَا تَمَامٍ، فَقَالَ لَهُ: يَا رَسُولَ اللَّهِ، فأَسْتَنْفِقُ ثَمَنَهَا؟ فَقَالَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ الَّذِي حَرَّمَ شُرْبَهَا حَرَّمَ ثَمَنَهَا."],"takhrij":"صحيح: رواه الطبراني في الأوسط (439) عن أحمد بن خليد، قال: حدثنا عبد الله بن جعفر الرقي، قال: حدثنا عبيد الله بن عمرو، عن زيد بن أبي أنيسة، عن أبي بكر بن حفص، عن عبد الله بن عامر بن ربيعة، عن أبيه، فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tabarani in al-Awsat (439).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Amir ibn Rabi‘ah reported that a man from Thaqif, known as Abu Tammam, gave the Messenger of Allah ﷺ a skin of wine. The Messenger of Allah ﷺ said: “It has indeed been forbidden, O Abu Tammam.” He said: O Messenger of Allah ﷺ, may I at least spend its price? The Prophet ﷺ said: “The One who forbade drinking it also forbade its price.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الطبراني في الأوسط (439)."},{"num":5788,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَامَ الْفَتْحِ، وَهُوَ بِمَكَّةَ يَقُولُ: إِنَّ اللَّهَ وَرَسُولَهُ حَرَّمَ بَيْعَ الْخَمْرِ وَالْمَيْتَةَ وَالْخِنْزِيرَ، فَقِيلَ: يَا رَسُولَ اللَّهِ، أَرَأَيْتَ شُحُومَ الْمَيْتَةِ؟ فَإِنَّهُ يُدْهَنُ بِهَا السُّفُنُ، وَيُدْهَنُ بِهَا الْجُلُودُ، وَيَسْتَصْبِحُ بِهَا النَّاسُ؟ فَقَالَ: لَا، هِيَ حَرَامٌ، ثُمَّ قَالَ: قَاتَلَ اللَّهُ الْيَهُودَ، إِنَّ اللَّهَ لَمَّا حَرَّمَ عَلَيْهِمُ الشُّحُومَ، جَمَلُوهَا، ثُمَّ بَاعُوهَا، وَأَكَلُوا أَثْمَانَهَا."],"takhrij":"حسن: رواه أحمد (6997)، والبيهقي (19631) كلاهما من حديث أسامة بن زيد، عن عمرو بن شعيب بإسناده مثله.","grade":"حسن","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (6997) and al-Bayhaqi (9/355).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Amr ibn Shu‘ayb, from his father, from his grandfather, said: I heard the Prophet ﷺ say in Makkah during the Year of the Conquest: “Allah and His Messenger have forbidden the sale of wine, carrion, and pork.” It was said: O Messenger of Allah ﷺ, what about the fat of carrion, for ships are coated with it, skins are greased with it, and people use it for lamps? He said: “No, it is forbidden.” Then he said: “May Allah destroy the Jews. When Allah forbade fat to them, they melted it, sold it, and consumed its price.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (6997)، والبيهقي (19631)."},{"num":5789,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ الْوَاحِدِ الْبُنَانِيِّ قَالَ: كُنْتُ مَعَ ابْنِ عُمَرَ، فَجَاءَهُ رَجُلٌ، فَقَالَ: يَا أَبَا عَبْدِ الرَّحْمَنِ، إِنِّي أَشْتَرِي هَذِهِ الْحِيطَانَ تَكُونُ فِيهَا الْأَعْنَابُ، وَلَا نَسْتَطِيعُ أَنْ نَبِيعَهَا كُلَّهَا عِنَبًا حَتَّى نَعْصِرَهُ، قَالَ: فَعَنْ ثَمَنِ الْخَمْرِ تَسْأَلُنِي؟ سَأُحَدِّثُكَ حَدِيثًا سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، كُنَّا جُلُوسًا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذْ رَفَعَ رَأْسَهُ إِلَى السَّمَاءِ، ثُمَّ أَكَبَّ، وَنَكَتَ فِي الْأَرْضِ، وَقَالَ: الْوَيْلُ لِبَنِي إِسْرَائِيلَ. فَقَالَ لَهُ عُمَرُ: يَا نَبِيَّ اللَّهِ، لَقَدْ أَفْزَعَنَا قَوْلُكَ لِبَنِي إِسْرَائِيلَ، فَقَالَ: لَيْسَ عَلَيْكُمْ مِنْ ذَلِكَ بَأْسٌ، إِنَّهُمْ لَمَّا حُرِّمَتْ عَلَيْهِمُ الشُّحُومُ، فَتَوَاطَئُوهُ، فَيَبِيعُونَهُ، فَيَأْكُلُونَ ثَمَنَهُ، وَكَذَلِكَ ثَمَنُ الْخَمْرِ عَلَيْكُمْ حَرَامٌ."],"takhrij":"حسن: رواه أحمد (5982) عن عبد الصمد، حدثني أبي، ثنا عبد العزيز بن صهيب، عن عبدالواحد البناني قال فذكره.","grade":"حسن","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (5982).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Abd al-Wahid al-Banani said: I was with Ibn Umar when a man came to him and said: O Abu Abd al-Rahman, I buy vineyards with grapes on them, and we cannot sell all of them as grapes until we press them. He said: Are you asking me about the price of wine? I will tell you a hadith I heard from the Messenger of Allah ﷺ. We were sitting with the Prophet ﷺ when he raised his head to the sky, then lowered it and scratched the ground and said: “Woe to the Children of Israel.” Umar said: O Prophet ﷺ of Allah, your statement about the Children of Israel has alarmed us. He said: “That is not your issue. When fat was forbidden to them, they manipulated it, sold it, and consumed its price. Likewise, the price of wine is forbidden for you.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (5982)."},{"num":5790,"demo":false,"sanad":"","matn":["عن ابْنِ عُمَرَ يَقُولُ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لُعِنَتِ الْخَمْرُ عَلَى عَشَرَةِ أَوْجُهٍ: بِعَيْنِهَا، وَعَاصِرِهَا، وَمُعْتَصِرِهَا، وَبَائِعِهَا، وَمُبْتَاعِهَا، وَحَامِلِهَا، وَالْمَحْمُولَةِ إِلَيْهِ، وَآكِلِ ثَمَنِهَا، وَشَارِبِهَا، وَسَاقِيهَا."],"takhrij":"حسن: رواه أبو داود (3674)، وابن ماجه (3380)، وأحمد (4787)، وابن أبي شيبة (21625)، والبيهقي (5/327) كلهم من طريق عبد العزيز بن عمر بن عبد العزيز، عن عبد الرحمن بن عبد الله الغافقي وأبي طعمة مولاهم أنهما سمعا ابن عمر يقول فذكره.","grade":"حسن","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3674), Ibn Majah (3380), Ahmad (4787), and Ibn Abi Shaybah (6/447).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Abd Allah ibn Umar reported that the Messenger of Allah ﷺ said: “Wine has been cursed in ten ways: in itself, the one who presses it, the one for whom it is pressed, the one who sells it, the one who buys it, the one who carries it, the one to whom it is carried, the one who consumes its price, the one who drinks it, and the one who serves it.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[7584],"tks":"حسن: رواه أبو داود (3674)، وابن ماجه (3380)، وأحمد (4787)، وابن أبي شيبة (21625)."},{"num":5791,"demo":false,"sanad":"","matn":["عن عَبْدِ الرَّحْمَنِ بن شريح الخولاني: أَنَّهُ كَانَ لَهُ عَمٌّ يَبِيعُ الْخَمْرَ، وَكَانَ يَتَصَدَّقُ بِثَمَنِهِ، فَنَهَيْتُهُ عَنْهَا، فَلَمْ يَنْتَهِ، فَقَدِمْتُ الْمَدِينَةَ، فَلَقِيتُ ابْنَ عَبَّاسٍ، فَسَأَلْتُهُ عَنِ الْخَمْرِ وَثَمَنِهَا، فَقَالَ: هِيَ حَرَامٌ، وَثَمَنُهَا حَرَامٌ، ثُمَّ قَالَ: يَا مَعْشَرَ أُمَّةِ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِنَّهُ لَوْ كَانَ كِتَابٌ بَعْدَ كِتَابِكُمْ، أَوْ نَبِيٌّ بَعْدَ نَبِيِّكُمْ لَأُنْزِلَ فِيكُمْ، كَمَا أُنْزِلَ فِيمَنْ كَانَ قَبْلَكُمْ، وَلَكِنْ أُخِّرَ ذَلِكَ مِنْ أَمْرِكُمْ إِلَى يَوْمِ الْقِيَامَةِ، وَلَعَمْرِي لَهُوَ أَشَدُّ عَلَيْكُمْ.","قال: ثم لقيت عبد الله بن عمر، فسألته عن ثمن الخمر، فقال: سأخبرك عن الخمر: أني كنت عند رسول الله صلى الله عليه وسلم  في المسجد، فبينما هو محتبي حل حبوته، ثم قال: من كان عنده من الخمر شيء فليؤذني به. فجعل الناس يأتونه، فيقول أحدهم: عندي راوية خمر، ويقول الآخر: عندي راوية، و يقول الآخر: عندي زق، أو ما شاء الله أن يكون عنده، فقال رسول الله صلى الله عليه وسلم : اجمعوه ببقيع كذا و كذا ثم آذنوني، ففعلوا، ثم آذنوه. قال: فقمت، فمشيت -و هو متكئ علي-، فلحقنا أبو بكر رضي الله عنه، فأخذني رسول الله صلى الله عليه وسلم ، فجعلني عن يساره، وجعل أبا بكر مكاني، ثم لحقنا عمر، فأخذني، وجعلني عن يساره، فمشى بينهما حتى إذا وقف على الخمر قال للناس: أتعرفون هذه؟ قالوا: نعم يا رسول الله، هذه الخمر. قال: صدقتم. ثم قال: إن الله تعالى لعن الخمر، وعاصرها، ومعتصرها، وشاربها، وساقيها، وحاملها، والمحمولة إليه، وبائعها، ومشتريها، وآكل ثمنها. ثم دعا بسكين، فقال: اشحذوها. ففعلوا، ثم أخذها رسول الله صلى الله عليه وسلم  يخرق بها الزقاق. فقال الناس: إن في هذه الزقاق لمنفعة، فقال: أجل، و لكن إنما أفعل غضبا لله لما فيها من سخطه. فقال عمر: أنا أكفيك يا رسول الله. قال: لا. و بعضهم يزيد على بعض في الحديث."],"takhrij":"صحيح: رواه الحاكم (7228) عن أبي العباس محمد بن يعقوب، أنبأ محمد بن عبد الله بن عبدالحكم، أنبأ ابن وهب، أخبرني عبد الرحمن بن شريح الخولاني قال:فذكره.","grade":"صحيح","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Hakim (7228).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Abd al-Rahman ibn Shurayh al-Khawlani said: I had an uncle who sold wine, and he used to give its price in charity. I forbade him from that, but he did not stop. Then I came to Madinah and met Ibn Abbas and asked him about wine and its price. He said: It is forbidden, and its price is forbidden. Then he said: O nation of Muhammad, if there had been another scripture after your scripture, or another prophet after your prophet, something like what was sent down upon those before you would have been sent down upon you. But there is no scripture after your scripture and no prophet after your prophet. Then I met Abd Allah ibn Umar and asked him about the price of wine. He said: I will tell you about wine. I was with the Messenger of Allah ﷺ in the mosque. While he was sitting with his knees drawn up, he untied his posture and said: “Whoever has any wine should inform me of it.” People began coming to him. One said: I have a skin of wine. Another said: I have a container. Another said: I have a wineskin, or whatever Allah willed one of them to have. The Messenger of Allah ﷺ said: “Gather it in such-and-such place in the cemetery area, then inform me.” They did that and then informed him. I stood and walked while he was leaning on me. Abu Bakr joined us, so the Messenger of Allah ﷺ moved me to his left and put Abu Bakr in my place. Then Umar joined us, so he moved me to his left, and he walked between them until he stopped at the wine and said to the people: “Do you know what this is?” They said: Yes, O Messenger of Allah ﷺ, this is wine. He said: “You have spoken the truth.” Then he said: “Allah has cursed wine, the one who presses it, the one for whom it is pressed, the one who drinks it, the one who serves it, the one who carries it, the one to whom it is carried, the one who sells it, the one who buys it, and the one who consumes its price.” Then he asked for a knife and said: “Sharpen it.” They did so, and the Messenger of Allah ﷺ began cutting the wineskins open with it. The people said: There is some use in these skins. He said: “Yes, but I am only doing this out of anger for Allah because of what they contain of His displeasure.” Umar said: I will take care of it for you, O Messenger of Allah ﷺ. He said: “No.” Some narrators add more than others in this hadith."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الحاكم (7228)."},{"num":5792,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ: لَعَنَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْخَمْرِ عَشَرَةً: عَاصِرَهَا، وَمُعْتَصِرَهَا، وَشَارِبَهَا، وَحَامِلَهَا، وَالْمَحْمُولَةَ إِلَيْهِ، وَسَاقِيَهَا وَبَائِعَهَا، وَآكِلَ ثَمَنِهَا، وَالْمُشْتَرِيَ لَهَا، وَالْمُشْتَرَاةَ لَهُ."],"takhrij":"حسن: رواه الترمذي (1295)، وابن ماجه (3381) كلاهما من حديث أبي عاصم، عن شبيب بن بشر، عن أنس بن مالك فذكره.","grade":"حسن","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1295) and Ibn Majah (3381). Al-Tirmidhi said: “This is a singularly transmitted hadith.”","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Anas said: The Messenger of Allah ﷺ cursed ten connected to wine: the one who presses it, the one for whom it is pressed, the one who drinks it, the one who carries it, the one to whom it is carried, the one who serves it, the one who sells it, the one who consumes its price, the one who buys it, and the one for whom it is bought."]}},"tuhfa":{},"full":1,"dr":1,"rep":[7585],"tks":"حسن: رواه الترمذي (1295)، وابن ماجه (3381). وقال الترمذي: “هذا حديث غريب”."},{"num":5793,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ: لَمَّا حُرِّمَتِ الْخَمْرُ قَالَ: إِنِّي يَوْمَئِذٍ لَأَسْقِيهِمْ، لَأَسْقِي أَحَدَ عَشَرَ رَجُلًا، فَأَمَرُونِي، فَكَفَأْتُهَا، وَكَفَأَ النَّاسُ آنِيَتَهُمْ بِمَا فِيهَا حَتَّى كَادَتِ السِّكَكُ أَنْ تُمْتَنَعَ مِنْ رِيحِهَا.","قَالَ أَنَسٌ: وَمَا خَمْرُهُمْ يَوْمَئِذٍ إِلَّا الْبُسْرُ وَالتَّمْرُ مَخْلُوطَيْنِ.","قَالَ: فَجَاءَ رَجُلٌ إِلَى النَّبِيِّ صلى الله عليه وسلم ، فَقَالَ: إِنَّهُ كَانَ عِنْدِي مَالُ يَتِيمٍ فَاشْتَرَيْتُ بِهِ خَمْرًا، أَفَتَأْذَنُ لِي أَنْ أَبِيعَهُ، فَأَرُدَّ عَلَى الْيَتِيمِ مَالَهُ، فَقَالَ النَّبِيُّ صلى الله عليه وسلم :: قَاتَلَ اللهُ الْيَهُودَ، حُرِّمَتْ عَلَيْهِمُ الثُّرُوبُ، فَبَاعُوهَا، وَأَكَلُوا أَثْمَانَهَا. وَلَمْ يَأْذَنْ لَهُمُ النَّبِيُّ صلى الله عليه وسلم  فِي بَيْعِ الْخَمْرِ."],"takhrij":"صحيح: رواه أحمد (13275) عن عبدالرزاق– وهو في مصنفه (16970)- قال: أخبرنا معمر، عن ثابت وقتادة، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (13275), Abd al-Razzaq in his Musannaf (16970), and Ibn Hibban (4945).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Anas said: When wine was forbidden, I was at that time serving it to them, serving eleven men. So I overturned it, and the people overturned their vessels with what was in them, until the streets almost became filled with its smell. Anas said: Their wine that day was only a mixture of unripe dates and dried dates. Then a man came to the Prophet ﷺ and said: I had the wealth of an orphan, and I bought wine with it. Will you allow me to sell it so that I may return the orphan’s money? The Prophet ﷺ said: “May Allah destroy the Jews. Fat was forbidden to them, but they sold it and made its price lawful for themselves.” And the Prophet ﷺ did not permit them to sell wine."]},"buhuth":{"en":["Explanation: The word “al-thurub” refers to thin fat."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (13275)، وعبد الرزاق في مصنفه (16970)، وابن حبان (4945)."},{"num":5794,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّ أَبَا طَلْحَةَ سَأَلَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ أَيْتَامٍ وَرِثُوا خَمْرًا، فَقَالَ: أَهْرِقْهَا قَالَ: أَفَلَا نَجْعَلُهَا خَلًّا؟ قَالَ: لَا."],"takhrij":"حسن: رواه أبو داود (3675)، والترمذي (1293) معلقا، وأحمد (12189)، والطحاوي في مشكله (3337)، والبيهقي (6/37) كلهم من حديث سفيان الثوري، عن السدي، عن أبي هبيرة، عن أنس بن مالك فذكره.","grade":"حسن","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3675), al-Tirmidhi (1293, suspended), Ahmad (12189), and al-Tahawi in Mushkil al-Athar (3337).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Anas ibn Malik reported that Abu Talhah asked the Prophet ﷺ about orphans who had inherited wine. He said, “Pour it out.” He asked, “May we not turn it into vinegar?” He said, “No.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3675)، والترمذي (1293) معلقا، وأحمد (12189)، والطحاوي في مشكل الآثار (3337)."},{"num":5795,"demo":false,"sanad":"","matn":["عَنْ أُسَامَةَ بْنِ زَيْدٍ رضي الله عنهما قَالَ: دَخَلْنَا عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  نَعُودُهُ، وَهُوَ مَرِيضٌ، فَوَجَدْنَاهُ نَائِمًا، قَدْ غَطَّى وَجْهَهُ بِبُرْدٍ عَدَنِيٍّ، فَكَشَفَ عَنْ وَجْهِهِ، ثُمَّ قَالَ: لَعَنَ اللَّهُ الْيَهُودَ، يُحَرِّمُونَ شُحُومَ الْغَنَمِ، وَيَأْكُلُونَ أَثْمَانَهَا."],"takhrij":"صحيح: رواه الحارث بن أبي أسامة –بغية الباحث (433)-، وأبو نعيم في معرفة الصحابة (771)، والحاكم (7414) كلهم من حديث الأعمش، عن جامع بن شداد، عن كلثوم الخزاعي، عن أسامة فذكره.","grade":"صحيح","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Harith ibn Abi Usamah in Bughyat al-Bahith (433), and Abu Nu‘aym in Ma‘rifat al-Sahabah (2/183–184).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Usamah ibn Zayd said: We entered upon the Messenger of Allah ﷺ to visit him while he was ill. We found him sleeping, with his face covered by an Adeni cloak. He uncovered his face and then said, “May Allah curse the Jews. They make the fat of sheep unlawful, yet they consume its price.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الحارث بن أبي أسامة -بغية الباحث (433)-، وأبو نعيم في معرفة الصحابة (771)."},{"num":5796,"demo":false,"sanad":"","matn":["عَنْ أَبِي مَسْعُودٍ الأَنْصَارِيِّ ـ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ ثَمَنِ الْكَلْبِ، وَمَهْرِ الْبَغِيِّ، وَحُلْوَانِ الْكَاهِنِ."],"takhrij":"متفق عليه: رواه مالك في البيوع (68) عن ابن شهاب، عن أبي بكر بن عبد الرحمن بن الحارث بن هشام، عن أبي مسعود الأنصاري فذكره.","grade":"متفق عليه","chapter_ar":"باب النهي عن ثمن الكلب، ومهر البغي، وحلوان الكاهن، وأجر الحجام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (68), al-Bukhari (2237), and Muslim (1567: 39).","chapter_en":"The prohibition of taking the price of a dog, the payment of a prostitute, the fee of a fortune-teller, and the wage of a cupper","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":31,"content":{"translation":{"en":["Abu Mas‘ud al-Ansari reported that the Messenger of Allah ﷺ forbade the price of a dog, the payment given to a prostitute, and the fee of a fortune-teller."]},"buhuth":{"en":["Explanation: “The fee of a fortune-teller” refers to money taken easily and wrongfully, without lawful effort. By analogy, this includes any unlawful payment taken without right."]}},"tuhfa":{},"full":1,"dr":1,"rep":[12882],"tks":"متفق عليه: رواه مالك (68) والبخاري (2237)، ومسلم (1567: 39)."},{"num":5797,"demo":false,"sanad":"","matn":["عَنْ رَافِعِ بْنِ خَدِيجٍ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ:  شَرُّ الْكَسْبِ مَهْرُ الْبَغِيِّ، وَثَمَنُ الْكَلْبِ، وَكَسْبُ الْحَجَّامِ."],"takhrij":"صحيح: رواه مسلم في المساقاة (1568) عن محمد بن حاتم، حدثنا يحيى بن سعيد القطان، عن محمد بن يوسف قال: سمعت السائب بن يزيد يحدث عن رافع بن خديج قال:فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن ثمن الكلب، ومهر البغي، وحلوان الكاهن، وأجر الحجام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1568). In another wording: “The price of a dog is filthy, the payment of a prostitute is filthy, and the earnings of a cupper are filthy.”","chapter_en":"The prohibition of taking the price of a dog, the payment of a prostitute, the fee of a fortune-teller, and the wage of a cupper","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":31,"content":{"translation":{"en":["Rafi‘ ibn Khadij reported that he heard the Messenger of Allah ﷺ say, “The worst earnings are the payment of a prostitute, the price of a dog, and the earnings of a cupper.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[5831],"tks":"صحيح: رواه مسلم (1568). وفي رواية: (( ثمن الكلب خبيث، ومهر البغي خبيث، وكسب الحجام خبيث ))."},{"num":5798,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ، قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ ثَمَنِ الْكَلْبِ وَإِنْ جَاءَ يَطْلُبُ ثَمَنَ الْكَلْبِ فَامْلأْ كَفَّهُ تُرَابًا."],"takhrij":"صحيح: رواه أبو داود (3482) عن الربيع بن نافع أبي توبة، حدثنا عبيدالله –يعني ابن عمرو-، عن عبد الكريم، عن قيس بن حَبْتَر، عن عبد الله بن عباس فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن ثمن الكلب، ومهر البغي، وحلوان الكاهن، وأجر الحجام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3482), Ahmad (2626, 2512), and al-Bayhaqi (6/6).","chapter_en":"The prohibition of taking the price of a dog, the payment of a prostitute, the fee of a fortune-teller, and the wage of a cupper","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":31,"content":{"translation":{"en":["Abdullah ibn Abbas said: The Messenger of Allah ﷺ forbade the price of a dog, and if its owner comes demanding its price, then fill his hands with dust."]},"buhuth":{"en":["In another wording: “The Messenger of Allah ﷺ forbade the price of wine, the payment of a prostitute, and the price of a dog.” He said: “If its owner comes asking for its price, then fill his hands with dust.”","Explanation: The mention of dust means disappointment and deprivation."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (3482)، وأحمد (2626، 2512)، والبيهقي (11009)."},{"num":5799,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: نَهَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ كَسْبِ الإِمَاءِ."],"takhrij":"صحيح: رواه البخاري في الإجارة (2283) عن مسلم بن إبراهيم، حدثنا شعبة، عن محمد بن جحادة، عن أبي حازم، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن ثمن الكلب، ومهر البغي، وحلوان الكاهن، وأجر الحجام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2283).","chapter_en":"The prohibition of taking the price of a dog, the payment of a prostitute, the fee of a fortune-teller, and the wage of a cupper","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":31,"content":{"translation":{"en":["Abu Hurayrah said: The Prophet ﷺ forbade the earnings of slave women."]}},"tuhfa":{},"full":1,"dr":1,"rep":[12881],"tks":"صحيح: رواه البخاري (2283)."}]);